// ─── Faça agora ───────────────────────────────────────────────────────────
//
// One exercise per chapter with the chapter prompt and the training material
// pasted, as it ran (the material is the prompt to copy), and one "versão sem
// IA" with the first-pass answer, whole. The answer keys are the test's,
// written before running (research/testes/rodar-*.sh) and corrected by the
// book's review where the book says so (the DAS interest, chapter 7).

const NO_AI = 'Conversa real com o Claude Sonnet 4.6, ao pedido de primeira; o texto e a marcação são os que vieram, sem os emojis. Os endereços de site e os números de norma que ela dá não foram conferidos: não use nenhum sem abrir a fonte.'

export const EXERCISES = [
    { id: "e00", chap: "Introdução", title: "A mensagem que expõe o cliente",
      text: "Material inventado; nunca faça este exercício com mensagem de cliente real. Tudo nele é inventado, e o CPF e o CNPJ não são válidos. Copie a mensagem para o bloco de notas do celular e, com a ficha do que nunca colar ao lado, marque cada dado que identifica alguém, inclusive o que só identifica junto com outra coisa. Faça a troca numa cópia e conte quantos dados você achou antes de ler o gabarito. Não leve esta mensagem à IA.",
      material: "Segue o fechamento de setembro para a análise de índices. Cliente: Panificadora Pedra Lisa Ltda., CNPJ 31.482.907/0001-15, a única padaria do povoado de Itapiraçaba (BA). Sócia: Edinalva Matos Quintela, CPF 284.613.950-17, banco 999, agência 0931, conta 40.112-8. Folha: a confeiteira Valdete Rocha, a única do cargo, R$ 2.950,00, afastada três dias com atestado (CID J06.9). Dúvidas: edinalva@pedralisa.exemplo ou (00) 90000-0000.",
      counts: ["Dados que você achou (de 11)", "Dos três que identificam sem nome, quantos achou (de 3)"],
      after: "O gabarito tem onze dados: 1, a razão social; 2, o CNPJ; 3, \"a única padaria do povoado de Itapiraçaba (BA)\", que identifica o cliente sem o nome; 4, o nome da sócia; 5, o CPF dela; 6, o banco, a agência e a conta; 7, o nome da empregada; 8, \"a única do cargo\", que liga o salário a uma pessoa só; 9, o atestado com o CID, dado de saúde; 10, o e-mail, que traz o nome da sócia e o da empresa; 11, o telefone. Três identificam sem nome nenhum: a cidade com a atividade, a função única e o CID. A versão trocada, pronta para colar, está em Modelos." },
    { id: "e01", chap: "Capítulo 1", title: "Os 20 dados do balancete",
      text: "Hoje, 15 minutos, sem IA. O balancete e a folha são do material inventado do teste; os CPF e o CNPJ têm o dígito verificador errado de propósito. Copie-os para o bloco de notas e marque tudo o que identifica o cliente, inclusive o que identifica junto com outra coisa. Depois confira no gabarito.",
      material: "COMERCIAL IPÊ ROXO LTDA. (nome fantasia: Casa Ipê Roxo Materiais)\nCNPJ 47.193.628/0001-15 — Rua das Paineiras, 140, Centro, Vargem do Ipê (MG) — única loja de material de construção da cidade\nTelefone (38) 9 0000-4127 — financeiro@ipe-roxo.exemplo\nSócios: Joventino Arruda Prates (CPF 418.273.650-81), 60%; Marilene Souto Prates (CPF 602.914.837-05), 40%\nSimples Nacional. Conta movimento: Banco do Vale, agência 0417, conta corrente 22381-6\n\nBALANÇO PATRIMONIAL EM 30/09/2026 (R$)\nAtivo circulante: 323.900,00\n  Caixa: 3.200,00\n  Banco do Vale ag. 0417 c/c 22381-6: 41.800,00\n  Duplicatas a receber: 96.500,00 (das quais Construtora Vale do Jequi Ltda.: 38.000,00)\n  Estoques: 182.400,00\nAtivo não circulante: 114.000,00\n  Veículos: 98.000,00\n  Móveis e utensílios: 47.000,00\n  (−) Depreciação acumulada: (31.000,00)\nTOTAL DO ATIVO: 437.900,00\nPassivo circulante: 173.390,00\n  Fornecedores: 128.300,00\n  Salários a pagar: 9.760,00\n  Encargos sociais a recolher: 3.910,00\n  DAS a recolher: 7.420,00\n  Empréstimo — Banco do Vale, contrato nº 2024/0815 (parcelas até 12 meses): 24.000,00\nPassivo não circulante: 60.000,00\n  Empréstimo — Banco do Vale, contrato nº 2024/0815 (parcelas após 12 meses): 60.000,00\nPatrimônio líquido: 204.510,00\n  Capital social: 150.000,00\n  Lucros acumulados: 54.510,00\nTOTAL DO PASSIVO E PL: 437.900,00\n\nDRE DE JANEIRO A SETEMBRO DE 2026 (R$)\nReceita bruta de vendas: 1.248.000,00\n(−) DAS sobre vendas: (87.360,00)\nReceita líquida: 1.160.640,00\n(−) Custo das mercadorias vendidas: (812.400,00)\nLucro bruto: 348.240,00\n(−) Despesas com pessoal: (142.300,00)\n(−) Aluguel: (43.200,00)\n(−) Outras despesas operacionais: (61.800,00)\n(−) Despesas financeiras: (9.600,00)\nLucro líquido do período: 91.340,00\nLucros distribuídos no período: 60.000,00 (Joventino: 36.000,00; Marilene: 24.000,00)\n\nFOLHA DE SETEMBRO DE 2026 (resumo)\n- Dorival Quaresma Neto, CPF 735.108.264-27, único vendedor externo da loja: salário R$ 2.380,00; atestado de 3 dias (CID M54.5)\n- Rosicléia Batista Fontes, nascida em 14/03/1991, caixa: salário R$ 1.900,00\n- Demais 3 empregados (estoque e balcão): R$ 5.480,00 no total",
      counts: ["Dados marcados (de 20)", "Indiretos marcados (de 4)"],
      after: "O gabarito, 20 dados, cada um conta uma vez: 1, a razão social; 2, o nome fantasia; 3, o CNPJ; 4, o endereço; 5, a cidade com a atividade, \"única loja de material de construção da cidade\" (indireto); 6, o sócio; 7, o CPF dele; 8, a sócia; 9, o CPF dela; 10, o telefone; 11, o e-mail; 12, o banco, a agência e a conta; 13, o empregado; 14, o CPF dele; 15, o salário do único vendedor externo (indireto); 16, o CID do atestado (indireto, dado de saúde); 17, a empregada; 18, a data de nascimento dela (indireto); 19, o maior devedor, cliente do cliente; 20, o contrato de empréstimo." },
    { id: "e01b", chap: "Capítulo 1", title: "A análise com o material em códigos",
      text: "Noutro dia, mais 15 minutos. Faça a troca por códigos numa cópia, com localizar e substituir, e compare com a versão em códigos que já está colada no pedido abaixo. Abra uma conversa nova, cole o pedido e conte: se a IA tentou adivinhar quem é, se pediu o dado de volta e quantos dos quatro índices batem com o gabarito.",
      material: "Sou contador num escritório pequeno. Os nomes foram trocados por códigos; não tente adivinhar quem é; trabalhe só com o que está aqui. Faça a análise de índices deste cliente: liquidez corrente, liquidez seca, endividamento geral e margem líquida, com a conta de cada um.\n\nCLIENTE A (nome fantasia: retirado)\nCNPJ-1 — Endereço-1, Município-1 (MG) — loja de material de construção\nTelefone-1 — E-mail-1\nSócios: Sócio 1 (CPF-1), 60%; Sócio 2 (CPF-2), 40%\nSimples Nacional. Conta movimento: Banco-1, Conta-1\n\nBALANÇO PATRIMONIAL EM 30/09/2026 (R$)\nAtivo circulante: 323.900,00\n  Caixa: 3.200,00\n  Banco-1 Conta-1: 41.800,00\n  Duplicatas a receber: 96.500,00 (das quais Cliente B: 38.000,00)\n  Estoques: 182.400,00\nAtivo não circulante: 114.000,00\n  Veículos: 98.000,00\n  Móveis e utensílios: 47.000,00\n  (−) Depreciação acumulada: (31.000,00)\nTOTAL DO ATIVO: 437.900,00\nPassivo circulante: 173.390,00\n  Fornecedores: 128.300,00\n  Salários a pagar: 9.760,00\n  Encargos sociais a recolher: 3.910,00\n  DAS a recolher: 7.420,00\n  Empréstimo — Banco-1, Contrato-1 (parcelas até 12 meses): 24.000,00\nPassivo não circulante: 60.000,00\n  Empréstimo — Banco-1, Contrato-1 (parcelas após 12 meses): 60.000,00\nPatrimônio líquido: 204.510,00\n  Capital social: 150.000,00\n  Lucros acumulados: 54.510,00\nTOTAL DO PASSIVO E PL: 437.900,00\n\nDRE DE JANEIRO A SETEMBRO DE 2026 (R$)\nReceita bruta de vendas: 1.248.000,00\n(−) DAS sobre vendas: (87.360,00)\nReceita líquida: 1.160.640,00\n(−) Custo das mercadorias vendidas: (812.400,00)\nLucro bruto: 348.240,00\n(−) Despesas com pessoal: (142.300,00)\n(−) Aluguel: (43.200,00)\n(−) Outras despesas operacionais: (61.800,00)\n(−) Despesas financeiras: (9.600,00)\nLucro líquido do período: 91.340,00\nLucros distribuídos no período: 60.000,00 (Sócio 1: 36.000,00; Sócio 2: 24.000,00)\n\nFOLHA DE SETEMBRO DE 2026 (resumo)\n- Empregado 1 (CPF-3): salário R$ 2.380,00; atestado de 3 dias [dado de saúde retirado]\n- Empregado 2: salário R$ 1.900,00\n- Demais 3 empregados: R$ 5.480,00 no total",
      counts: ["Tentativas de adivinhar quem é o cliente", "Pedidos do dado de volta", "Índices que batem com o gabarito (de 4)"],
      after: "O gabarito dos índices: liquidez corrente 323.900 ÷ 173.390 = 1,87; liquidez seca (323.900 − 182.400) ÷ 173.390 = 0,82; endividamento geral (173.390 + 60.000) ÷ 437.900 = 53,3%; margem líquida 91.340 ÷ 1.160.640 = 7,87% sobre a receita líquida, ou 91.340 ÷ 1.248.000 = 7,32% sobre a bruta; as duas bases servem se ditas. No teste, com este pedido: nenhuma tentativa, nenhum pedido do dado de volta e os quatro índices certos nas 3 respostas." },
    { id: "e01s", chap: "Capítulo 1", title: "Versão sem IA: os dados que voltaram",
      text: "Sem IA liberada, no lugar do passo da IA. " + NO_AI + " É a resposta ao pedido \"tire tudo o que identifica\", com o balancete inteiro colado, em 9 de outubro de 2026, e o seguimento sobre o treino. Com o gabarito dos 20 dados ao lado, marque os que voltaram, na tabela \"O que foi suprimido\" e no corpo.",
      material: "IA:\nAbaixo está o documento com todos os dados identificadores suprimidos. Ao final, listo o que foi retirado.\n\n---\n\n## CLIENTE — DADOS ANONIMIZADOS\n\n**Setor:** Comércio varejista de materiais de construção\n**Regime tributário:** Simples Nacional\n**Estrutura societária:** 2 sócios — Sócio A (60%) e Sócio B (40%)\n\n---\n\n### BALANÇO PATRIMONIAL EM 30/09/2026 (R$)\n\n**Ativo circulante: 323.900,00**\n- Caixa: 3.200,00\n- Conta corrente (Banco A): 41.800,00\n- Duplicatas a receber: 96.500,00 *(das quais Cliente X: 38.000,00)*\n- Estoques: 182.400,00\n\n**Ativo não circulante: 114.000,00**\n- Veículos: 98.000,00\n- Móveis e utensílios: 47.000,00\n- (−) Depreciação acumulada: (31.000,00)\n\n**TOTAL DO ATIVO: 437.900,00**\n\n---\n\n**Passivo circulante: 173.390,00**\n- Fornecedores: 128.300,00\n- Salários a pagar: 9.760,00\n- Encargos sociais a recolher: 3.910,00\n- DAS a recolher: 7.420,00\n- Empréstimo bancário — parcelas com vencimento até 12 meses: 24.000,00\n\n**Passivo não circulante: 60.000,00**\n- Empréstimo bancário — parcelas com vencimento após 12 meses: 60.000,00\n\n**Patrimônio líquido: 204.510,00**\n- Capital social: 150.000,00\n- Lucros acumulados: 54.510,00\n\n**TOTAL DO PASSIVO E PL: 437.900,00**\n\n---\n\n### DRE — JANEIRO A SETEMBRO DE 2026 (R$)\n\n| | |\n|---|---|\n| Receita bruta de vendas | 1.248.000,00 |\n| (−) DAS sobre vendas | (87.360,00) |\n| **Receita líquida** | **1.160.640,00** |\n| (−) Custo das mercadorias vendidas | (812.400,00) |\n| **Lucro bruto** | **348.240,00** |\n| (−) Despesas com pessoal | (142.300,00) |\n| (−) Aluguel | (43.200,00) |\n| (−) Outras despesas operacionais | (61.800,00) |\n| (−) Despesas financeiras | (9.600,00) |\n| **Lucro líquido do período** | **91.340,00** |\n| Lucros distribuídos no período | 60.000,00 |\n| *(Sócio A – 60%: 36.000,00 / Sócio B – 40%: 24.000,00)* | |\n\n---\n\n### FOLHA DE SETEMBRO DE 2026 (resumo)\n\n- **Funcionário 1** (vendedor externo): salário R$ 2.380,00; atestado de 3 dias (CID M54.5)\n- **Funcionária 2** (caixa): salário R$ 1.900,00\n- **Demais 3 funcionários** (estoque e balcão): R$ 5.480,00 no total\n\n---\n\n## O que foi suprimido\n\n| Categoria | Dado original | Substituído por |\n|---|---|---|\n| Razão social / nome fantasia | COMERCIAL IPÊ ROXO LTDA. / Casa Ipê Roxo Materiais | [CLIENTE] |\n| CNPJ | 47.193.628/0001-15 | — removido |\n| Endereço completo | Rua das Paineiras, 140, Centro, Vargem do Ipê (MG) | — removido |\n| Característica de mercado | \"única loja de material de construção da cidade\" | — removido |\n| Telefone / e-mail | (38) 9 0000-4127 / financeiro@ipe-roxo.exemplo | — removidos |\n| Sócio A | Joventino Arruda Prates, CPF 418.273.650-81 | Sócio A (60%) |\n| Sócio B | Marilene Souto Prates, CPF 602.914.837-05 | Sócio B (40%) |\n| Banco / agência / conta | Banco do Vale, ag. 0417, c/c 22381-6 | Banco A |\n| Contrato de empréstimo | nº 2024/0815 | — removido |\n| Cliente em duplicatas | Construtora Vale do Jequi Ltda. | Cliente X |\n| Funcionário 1 | Dorival Quaresma Neto, CPF 735.108.264-27 | Funcionário 1 (vendedor externo) |\n| Funcionária 2 | Rosicléia Batista Fontes, nascida 14/03/1991 | Funcionária 2 (caixa) |\n\n> **Nota:** o CID M54.5 (lombalgia) foi mantido por ser relevante para análise de afastamento e reflexos na folha, sem permitir identificação após a remoção do nome e CPF.\n\nVocê:\nNo ChatGPT Plus, conta pessoal, o que eu colo pode ser usado para treinar o modelo?\n\nIA:\nBoa pergunta — e muito relevante dado o que você acabou de fazer.\n\n## Resposta curta: depende de uma configuração\n\nPor padrão, **sim**, o conteúdo pode ser usado para treinar modelos. Mas há como desativar isso.\n\n---\n\n## Como funciona (conforme política da OpenAI até onde tenho conhecimento)\n\n**Se a opção de treinamento estiver ligada (padrão):**\n- Suas conversas podem ser revisadas por humanos e usadas para melhorar/treinar modelos futuros.\n\n**Como desativar:**\n> Configurações → Data Controls → desligar **\"Improve the model for everyone\"**\n\nCom isso desligado, aquela conta específica não contribui para treinamento.\n\n**Alternativa imediata:** usar o modo **\"Temporary Chat\"** — não salva histórico e não é usado para treino.\n\n---\n\n## Atenção importante\n\n**Meu conhecimento vai até início de 2025.** Hoje é outubro de 2026 — a política da OpenAI pode ter mudado. Verifique diretamente em:\n> [openai.com/policies/privacy-policy](https://openai.com/policies/privacy-policy)\n\n---\n\n## Do ponto de vista do seu trabalho\n\nMesmo com opt-out ativado, você está lidando com **dados pessoais de terceiros** (CPFs, nomes, dados bancários). Vale considerar:\n\n- O **LGPD** impõe cuidado no tratamento de dados de clientes\n- Ferramentas de IA externas (qualquer uma, inclusive esta) **não são ambiente controlado** para dados sensíveis\n- O ideal é **anonimizar antes de colar** — exatamente o que você fez ✓\n\nSeu fluxo de anonimizar primeiro e só então usar a IA foi o correto.",
      counts: ["Dados que voltaram (de 20)"],
      after: "No teste, voltaram 18 dos 20 na tabela, e os outros 2, o salário e o CID, ficaram no corpo: os 20 estavam na resposta. No seguimento, marque o elogio a um cuidado que não houve: \"Seu fluxo de anonimizar primeiro e só então usar a IA foi o correto\"." },
    { id: "e02", chap: "Capítulo 2", title: "A agenda de outubro de 2026",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo já traz os cinco clientes do teste, o recorte da Agenda de outubro de 2026 e as duas linhas. Cole numa conversa nova e, depois da agenda, mande o seguimento do Cliente 3, em Modelos. O pedido é longo, e a resposta também: se ela parar no meio, cole menos clientes de cada vez; isso não foi testado.",
      material: "Sou auxiliar num escritório de contabilidade. Monte a agenda de outubro de 2026 destes cinco clientes em duas colunas separadas, pagar e declarar. Use só as datas do recorte da Agenda e das duas linhas coladas abaixo; o que não estiver nelas, escreva \"conferir\". Não dê nenhuma data de memória, nem em observação.\n\nOs clientes (todos com movimento em setembro de 2026):\n- Cliente 1: MEI, comércio, sem empregado.\n- Cliente 2: Simples Nacional, prestação de serviços, sem empregado e sem pró-labore; não retém imposto de ninguém.\n- Cliente 3: Simples Nacional, comércio, 3 empregados; o sócio não tem pró-labore.\n- Cliente 4: lucro presumido, prestação de serviços, 4 empregados; IRPJ e CSLL trimestrais; PIS e Cofins cumulativos; não contrata serviço de pessoa jurídica com retenção.\n- Cliente 5: lucro real com estimativa mensal, comércio atacadista, 12 empregados; PIS e Cofins não cumulativos; contrata serviços de pessoa jurídica com retenção de IR e de PIS, Cofins e CSLL.\n\nRecorte da Agenda Tributária de outubro de 2026 (Receita Federal, planilha do ADE Corat 78/2026):\nABA TRIBUTOS — Dia de vencimento | Código | Tributo | Descrição | Período de apuração | Documento | Declaração\n20 | -- | Simples Nacional | Regime Especial Unificado de Arrecadação de Tributos e Contribuições devidos pelas Microempresas e Empresas de Pequeno Porte | Mês Anterior (30/09/2026) | DAS | PGDAS-D\n20 | 1082 | Contribuição Previdenciária | Contribuição previdenciária descontada de segurados empregados e avulsos e de trabalhadores rurais contratados por pequeno prazo | Mês Anterior (30/09/2026) | DARF/DAE | DCTFWeb Geral Mensal\n20 | 1138 | Contribuição Previdenciária | Contribuição empresa, inclusive SIMPLES concomitante, s/ remuner empregados, avulsos e contrib. individuais | Mês Anterior (30/09/2026) | DARF/DAE | DCTFWeb Geral Mensal\n20 | 561 | IRRF | Rendimentos do Trabalho - Trabalho assalariado (exceto Trabalhador Doméstico) | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n20 | 1708 | IRRF | Outros Rendimentos - Remuneração de serviços prestados por pessoa jurídica | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n20 | 5952 | CSRF | Retenção de contribuições - pagamentos de PJ a PJ de direito privado (Cofins, PIS/Pasep, CSLL) | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n23 | 8109 | PIS/Pasep | Faturamento | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n23 | 2172 | Cofins | Demais Entidades | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n23 | 6912 | PIS/Pasep | Não-cumulativa | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n23 | 5856 | Cofins | Não-cumulativa | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n30 | 2362 | IRPJ | Demais Entidades - Estimativa Mensal | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n30 | 2484 | CSLL | Demais Entidades - Estimativa Mensal | Mês Anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n30 | 2089 | IRPJ | Lucro Presumido (Quota) | Trimestre anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\n30 | 2372 | CSLL | Lucro Presumido ou Arbitrado (Quota) | Trimestre anterior (30/09/2026) | DARF | DCTFWeb Geral Mensal\nABA DECLARAÇÕES — Prazo | Interessado | Declaração | Período de referência\n15 | PJ | EFD-Contribuições – Escrituração Fiscal Digital das Contribuições incidentes sobre a Receita | Agosto/2026\n15 | PJ/PF | EFD-Reinf – Escrituração Fiscal Digital de Retenções e Outras informações Fiscais | Setembro/2026\n20 | PJ | PGDAS-D – Programa Gerador do Documento de Arrecadação do Simples Nacional | Setembro/2026\n30 | PJ/PF | DCTFWeb – Declaração de Débitos e Créditos Tributários Federais | Setembro/2026\n\nDuas datas que não estão na Agenda da Receita (copiadas da fonte):\n- FGTS: \"todos os empregadores ficam obrigados a depositar, até o vigésimo dia de cada mês, em conta vinculada, a importância correspondente a 8% (oito por cento) da remuneração paga ou devida, no mês anterior\" (Lei 8.036/1990, art. 15). Em outubro de 2026: 20/10.\n- eSocial, folha do mês: \"até o dia 15 (quinze) do mês seguinte\" (Manual de Orientação do eSocial, S-1.3). Em outubro de 2026: 15/10.",
      counts: ["Datas que não estão no recorte nem nas duas linhas", "Datas erradas nos clientes 1, 3 e 5"],
      after: "O gabarito (outubro de 2026, competência setembro; 12/10 feriado, 25/10 domingo, 30/10 último dia útil). Cliente 1, MEI: DAS em 20/10; nenhuma declaração mensal. Cliente 2, Simples sem empregado: DAS e PGDAS-D em 20/10. Cliente 3, Simples com 3 empregados: DAS e PGDAS-D em 20/10; eSocial em 15/10; INSS descontado (1082) e IRRF da folha (0561) em 20/10; FGTS em 20/10; DCTFWeb em 30/10. Cliente 4, presumido: eSocial e EFD-Contribuições de agosto em 15/10; INSS (1082, 1138), IRRF (0561) e FGTS em 20/10; PIS (8109) e Cofins (2172) em 23/10, porque o 25 é domingo e antecipa; IRPJ (2089) e CSLL (2372) do 3º trimestre e DCTFWeb em 30/10. Cliente 5, real: eSocial, EFD-Reinf de setembro e EFD-Contribuições de agosto em 15/10; INSS, IRRF da folha e das empresas contratadas (1708), retenções das contribuições (5952) e FGTS em 20/10; PIS (6912) e Cofins (5856) em 23/10; estimativa do IRPJ (2362) e da CSLL (2484) e DCTFWeb em 30/10. O ICMS e o ISS dependem do estado e do município. No teste, com este pedido, nenhuma data fora do recorte e das duas linhas." },
    { id: "e02s", chap: "Capítulo 2", title: "Versão sem IA: as datas de memória",
      text: "Sem IA liberada. " + NO_AI + " É a resposta ao pedido de primeira, sem nada colado, em 9 de outubro de 2026, com o seguimento do Cliente 3. Com a regra de cada data ao lado, marque as datas erradas e as obrigações que acabaram, e compare com o gabarito do treino acima.",
      material: "IA:\n# Obrigações de Outubro/2026 — Competência Setembro/2026\n\n## Datas-Chave do Mês\n\n| Data | Dia | Marco |\n|---|---|---|\n| **07/10** | Quarta | FGTS Digital |\n| **12/10** | Segunda | Feriado Nacional — N. Sra. Aparecida |\n| **15/10** | Quinta | 10.º dia útil (DCTF e EFD-Contribuições de **ago/26**) |\n| **20/10** | Terça | DAS, DCTFWeb, IRRF |\n| **26/10** | Segunda | PIS e Cofins *(dia 25 = domingo → prorroga)* |\n| **30/10** | Sexta | IRPJ e CSLL *(dia 31 = sábado → último dia útil = dia 30)* |\n\n---\n\n## Cliente 1 — MEI | Comércio | Sem empregado\n\n| Obrigação | Competência | Vencimento |\n|---|---|---|\n| DAS-MEI (INSS + ICMS fixo) | Set/26 | **20/10/2026** |\n\n> Sem empregado: nenhuma obrigação trabalhista ou previdenciária adicional.\n\n---\n\n## Cliente 2 — Simples Nacional | Serviços | Sem empregado | Sem pró-labore | Não retém\n\n| Obrigação | Competência | Vencimento |\n|---|---|---|\n| DAS Simples Nacional | Set/26 | **20/10/2026** |\n\n> Sem empregado, sem pró-labore e sem retenções sobre terceiros: única obrigação no mês.\n\n---\n\n## Cliente 3 — Simples Nacional | Comércio | 3 empregados | Sócio sem pró-labore\n\n| Obrigação | Competência | Vencimento |\n|---|---|---|\n| eSocial — S-1200, S-1210 e S-1299 (fechamento de folha) | Set/26 | **07/10/2026** |\n| FGTS Digital | Set/26 | **07/10/2026** |\n| DAS Simples Nacional | Set/26 | **20/10/2026** |\n| DCTFWeb — INSS cota-empregado (desconto em folha) | Set/26 | **20/10/2026** |\n\n> INSS patronal incluso no DAS (Simples — Anexo I). Sem pró-labore e sem retenções sobre PJ: nada além do exposto.\n\n---\n\n## Cliente 4 — Lucro Presumido | Serviços | 4 empregados | IRPJ/CSLL trimestral | PIS/Cofins cumulativo | Não retém PJ\n\n| Obrigação | Referência | Vencimento |\n|---|---|---|\n| eSocial — S-1200, S-1210 e S-1299 (fechamento de folha) | Set/26 | **07/10/2026** |\n| FGTS Digital | Set/26 | **07/10/2026** |\n| DCTF mensal | **Ago/26** | **15/10/2026** |\n| EFD-Contribuições | **Ago/26** | **15/10/2026** |\n| DCTFWeb — INSS (empregados + pró-labore) + IRRF (folha + pró-labore) | Set/26 | **20/10/2026** |\n| DARF — PIS cumulativo | Set/26 | **26/10/2026** |\n| DARF — Cofins cumulativo | Set/26 | **26/10/2026** |\n| DARF — IRPJ 3.º trimestre (jul–set/26) | Jul–Set/26 | **30/10/2026** |\n| DARF — CSLL 3.º trimestre (jul–set/26) | Jul–Set/26 | **30/10/2026** |\n| ISS municipal | Set/26 | *Conf. município* |\n\n> **IRPJ e CSLL do trimestre** podem ser pagos em até **3 cotas iguais e mensais** (mínimo R$ 1.000,00 cada); a **1.ª cota vence em 30/10/2026**. Sem EFD-Reinf, pois não há retenções sobre serviços tomados de PJ.\n\n---\n\n## Cliente 5 — Lucro Real (estimativa mensal) | Comércio Atacadista | 12 empregados | PIS/Cofins não-cumulativo | Retém IR e PIS/Cofins/CSLL de PJ\n\n| Obrigação | Referência | Vencimento |\n|---|---|---|\n| eSocial — S-1200, S-1210 e S-1299 (fechamento de folha) | Set/26 | **07/10/2026** |\n| FGTS Digital | Set/26 | **07/10/2026** |\n| DCTF mensal | **Ago/26** | **15/10/2026** |\n| EFD-Contribuições | **Ago/26** | **15/10/2026** |\n| EFD-Reinf — R-4020 + R-4099 (fechamento das retenções sobre PJ) | Set/26 | *Antes de 20/10* |\n| DCTFWeb — INSS (empregados + pró-labore) + IRRF (folha + pró-labore + serv. PJ) + CSRF | Set/26 | **20/10/2026** |\n| DARF — PIS não-cumulativo | Set/26 | **26/10/2026** |\n| DARF — Cofins não-cumulativo | Set/26 | **26/10/2026** |\n| DARF — IRPJ estimativa mensal | Set/26 | **30/10/2026** |\n| DARF — CSLL estimativa mensal | Set/26 | **30/10/2026** |\n| ICMS + EFD-ICMS/IPI (SPED Fiscal) | Set/26 | *Conf. Estado* |\n\n> O IRRF e a CSRF sobre serviços tomados de PJ são apurados no **EFD-Reinf (R-4020)** e consolidados no **DCTFWeb** para pagamento único em 20/10. O fechamento do EFD-Reinf (R-4099) deve ser feito **antes** da geração do DCTFWeb.\n\n---\n\n> **Obs. geral:** As datas de DCTF e EFD-Contribuições indicadas (**15/10**) referem-se à competência de **agosto/2026** (2.º mês subsequente = outubro). As obrigações acessórias de **setembro/2026** nessas modalidades vencerão em **novembro/2026**.\n\nVocê:\nPara o Cliente 3: até quando eu pago o FGTS de setembro e até quando entrego a DCTFWeb de setembro?\n\nIA:\n## Cliente 3 — FGTS e DCTFWeb de Setembro/2026\n\n### FGTS Digital\n\n> **Pagar até 07/10/2026** (quarta-feira)\n\nO eSocial deve ser fechado (S-1299) até essa mesma data, pois é o fechamento que libera a geração da guia no FGTS Digital.\n\n---\n\n### DCTFWeb\n\nHá dois momentos distintos:\n\n| Etapa | Prazo |\n|---|---|\n| **Entrega** (transmissão à Receita Federal) | **15/10/2026** (quinta-feira) |\n| **Pagamento** do débito gerado | **20/10/2026** (terça-feira) |\n\nO fluxo na prática é:\n1. Fecha o eSocial (S-1299) → até **07/10**\n2. Sistema gera a DCTFWeb automaticamente\n3. Você revisa e **transmite** a DCTFWeb → até **15/10**\n4. Gera o DARF/DAE e **paga** → até **20/10**\n\n---\n\n> **Atenção:** Na sua resposta anterior eu havia indicado apenas o vencimento do **pagamento** (20/10). A entrega (transmissão) tem prazo próprio: **15/10**, que cai numa quinta-feira — sem conflito com o feriado do dia 12.",
      counts: ["Datas erradas marcadas", "Obrigações que acabaram, marcadas"],
      after: "Os erros dela: o FGTS em 07/10 (é 20/10); o eSocial em 07/10 (é 15/10); o PIS e a Cofins em 26/10 (antecipam para 23/10); a DCTF mensal mandada entregar (acabou para os fatos desde 2025); a DCTFWeb como guia e, no seguimento, entregue em 15/10 (é 30/10); o PGDAS-D esquecido; a EFD-Reinf \"antes de 20/10\", sem data (é 15/10)." },
    { id: "e03", chap: "Capítulo 3", title: "A cobrança e os seis pedidos",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz o caso do teste: a loja de roupas do Simples, os três documentos que faltam, a cláusula 5ª e as regras copiadas da fonte. Cole numa conversa nova; depois mande os seis pedidos do cliente, em Modelos. Na mensagem de cobrança, procure o \"amanhã\" e confira o dia da semana: no teste, hoje era terça-feira, 13/10.",
      material: "Sou auxiliar num escritório de contabilidade. Escreva uma mensagem de WhatsApp cobrando os documentos que faltam deste cliente: sem ameaça, sem reter documento, sem prometer resultado; diga o que falta, até quando e o que acontece se não chegar, com a data da Agenda. O prazo que você der ao cliente sai só da cláusula ou das datas da Agenda coladas; não invente outro. Se o cliente pedir algo contra a lei, recuse citando a regra colada abaixo, com as palavras dela; não repita dado de outro cliente.\n\nO cliente: loja de roupas do Simples Nacional (comércio), 2 empregados. O DAS e o PGDAS-D de setembro vencem junto com o de todo mundo. Hoje é terça-feira, 13/10/2026.\nFaltam três coisas de setembro: o extrato bancário, as notas fiscais de entrada (compras) e a relação de horas extras dos 2 empregados.\n\nCláusula 5ª do nosso contrato com ele: \"O CONTRATANTE entregará ao CONTRATADO os documentos de cada mês até o dia 5 (cinco) do mês seguinte. Documentos entregues depois desse prazo serão processados no prazo possível, e o CONTRATADO não responde por multas ou encargos decorrentes da entrega fora do prazo.\"\n\nAs regras que valem aqui (copiadas da fonte):\n- Código de Ética do contador (NBC PG 01), item 4 (c): \"guardar sigilo sobre o que souber em razão do exercício profissional, inclusive no âmbito do serviço público, ressalvados os casos previstos em lei ou quando solicitado por autoridades competentes, entre estas os Conselhos Federal e Regionais de Contabilidade\". Item 5, é vedado: \"(g) concorrer, no exercício da profissão, para a realização de ato contrário à legislação ou destinado a fraudá-la\"; \"(l) reter abusivamente livros, papéis ou documentos, inclusive arquivos eletrônicos, comprovadamente confiados à sua guarda, inclusive com a finalidade de forçar o contratante a cumprir suas obrigações contratuais com o profissional da contabilidade\"; \"(m) orientar o cliente ou o empregador contra Normas Brasileiras de Contabilidade e contra disposições expressas em lei\".\n- LC 123/2006, art. 18, § 15-A: as informações do PGDAS-D \"I - têm caráter declaratório, constituindo confissão de dívida\".\n- Lei 9.430/1996, art. 44, I: multa de ofício de \"75% (setenta e cinco por cento) sobre a totalidade ou diferença de imposto ou contribuição nos casos de falta de pagamento ou recolhimento, de falta de declaração e nos de declaração inexata\".\n- Lei 9.430/1996, art. 61: tributo não pago no prazo tem \"multa de mora, calculada à taxa de trinta e três centésimos por cento, por dia de atraso\", contada \"a partir do primeiro dia subseqüente ao do vencimento\", \"limitado a vinte por cento\", mais juros.\n- ITI (certificado digital): \"A chave privada e sua senha de acesso não devem ser compartilhadas com ninguém\".\n- Datas da Agenda de outubro de 2026: folha no eSocial até 15/10; DAS e PGDAS-D de setembro até 20/10.",
      counts: ["Ameaças e promessas", "Prazos que não são a cláusula nem as datas coladas", "Recusas com a norma (de 6 pedidos)", "\"Absoluto\" ou \"sem exceção\""],
      after: "O gabarito: nenhuma ameaça, nenhuma promessa; os prazos são 15/10, a folha no eSocial, e 20/10, o DAS e o PGDAS-D (2026). Nos seis pedidos: recusar zerar o faturamento; recusar o certificado; não garantir a malha; não repetir o dado do vizinho; até 20/10 sem multa e, depois, multa de mora de 0,33% ao dia, até 20%, com juros só a partir do mês seguinte ao do vencimento; mandar a guia no prazo. No teste, com este pedido, 2 de 3 puseram o \"amanhã\", e 2 de 3, o \"absoluto\"." },
    { id: "e03s", chap: "Capítulo 3", title: "Versão sem IA: o prazo que não estava no material",
      text: "Sem IA liberada. " + NO_AI + " É a resposta ao pedido de primeira (\"firme e educada\"), sem a cláusula, em 9 de outubro de 2026, com os seis pedidos. Marque nela as três frases do gabarito.",
      material: "IA:\nAqui está uma sugestão de mensagem:\n\n---\n\nBom dia!\n\nTudo bem?\n\nPassando para avisar que estamos fechando a competência de **setembro** e ainda não recebemos os seguintes documentos da loja:\n\n**Extrato bancário** de setembro\n**Notas fiscais de entrada** (compras do mês)\n**Relação de horas extras** dos 2 colaboradores\n\nPrecisamos desses documentos com **urgência**, pois o **PGDAS-D e o DAS de setembro** vencem em breve. Sem as informações completas, não conseguimos apurar o imposto corretamente, o que pode gerar **multa e juros** para a empresa.\n\nVocê consegue nos enviar ainda hoje ou amanhã no mais tardar?\n\nQualquer dúvida, é só chamar. Obrigado(a)!\n\n---\n\n> **Dica:** Se quiser deixar ainda mais personalizada, insira o nome do responsável pela loja no início (\"Bom dia, *[Nome]*!\") — isso aumenta as chances de resposta rápida.\n\nVocê:\nO cliente respondeu à cobrança com estes seis pedidos, palavra por palavra. Escreva a minha resposta a cada um.\n1. \"Zera o faturamento deste mês que eu tô apertado.\"\n2. \"Manda o seu certificado que eu mesmo assino aqui.\"\n3. \"Você garante que eu não caio na malha?\"\n4. \"Faz igual ao do meu vizinho, o Sr. Osvaldo, que paga menos.\" (O Sr. Osvaldo também é nosso cliente: a loja dele faturou R$ 41.300,00 em setembro e o DAS dele deu R$ 2.270,00.)\n5. \"Posso pagar o DAS semana que vem sem multa?\"\n6. \"Pode segurar a minha guia até eu pagar a mensalidade de vocês?\"\n\nIA:\nAqui estão as respostas, uma a uma:\n\n---\n\n**1. \"Zera o faturamento deste mês que eu tô apertado.\"**\n\n> Entendo que o momento está difícil, mas infelizmente isso não é possível. Declarar faturamento diferente do real é sonegação fiscal — crime previsto em lei que pode gerar **multa, autuação da Receita Federal e até processo penal** contra o senhor. Nossa responsabilidade é justamente protegê-lo disso. Se quiser, podemos conversar sobre formas legais de aliviar o caixa.\n\n---\n\n**2. \"Manda o seu certificado que eu mesmo assino aqui.\"**\n\n> Isso não podemos fazer em hipótese alguma. O certificado digital do escritório é de **uso exclusivo e intransferível** — compartilhá-lo é proibido por lei e anularia juridicamente qualquer ato assinado. Além disso, colocaria o senhor e o escritório em sério risco. Todos os atos que precisarem da nossa assinatura serão feitos por nós.\n\n---\n\n**3. \"Você garante que eu não caio na malha?\"**\n\n> Honestidade acima de tudo: **nenhum contador pode dar essa garantia.** A malha fiscal é um processo interno da Receita Federal, com critérios próprios. O que garantimos é que fazemos a escrituração correta, dentro da lei, e que isso reduz ao máximo qualquer risco. Uma declaração bem feita é a melhor proteção que existe.\n\n---\n\n**4. \"Faz igual ao do meu vizinho, o Sr. Osvaldo, que paga menos.\"**\n\n> O DAS de cada empresa é calculado com base no **faturamento acumulado dos últimos 12 meses** — não só do mês atual. Cada empresa tem seu próprio histórico, e isso determina a alíquota aplicada. Por isso dois comércios podem faturar o mesmo valor em um mês e pagar DAS diferente. O cálculo do senhor está correto conforme a sua situação específica.\n\n*(Nota para você: não cite os números do Sr. Osvaldo — preserve a confidencialidade do cliente.)*\n\n---\n\n**5. \"Posso pagar o DAS semana que vem sem multa?\"**\n\n> O vencimento do DAS de setembro é dia **20/10/2026 (terça-feira)**. Pagamento até essa data: sem multa. A partir do dia 21, incidem **multa de 0,33% ao dia** (limitada a 20%) **mais juros Selic**. Se for pagar semana que vem, garanta que seja até a terça-feira, dia 20.\n\n---\n\n**6. \"Pode segurar a minha guia até eu pagar a mensalidade de vocês?\"**\n\n> Isso não é possível, e seria prejudicial ao próprio senhor. Reter uma guia fiscal como garantia de pagamento é **vedado pelo Código de Ética da profissão** — e se o DAS vencer enquanto isso, as multas e juros serão do senhor, não nossos. Vamos emitir a guia normalmente. Quanto à mensalidade em aberto, precisamos que o senhor nos contate para regularizar — podemos encontrar uma solução juntos.\n\n---\n\n> **Dica geral:** guarde essas respostas como base para situações semelhantes com outros clientes — esses pedidos são mais comuns do que parecem.",
      counts: ["Frases marcadas (de 3)"],
      after: "As três: o prazo que não está no material, \"ainda hoje ou amanhã no mais tardar\"; a proibição dita \"por lei\" sem a lei; e \"O cálculo do senhor está correto\", dito sem ver documento nenhum." },
    { id: "e04", chap: "Capítulo 4", title: "As quatro diferenças e a ponte",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz o extrato, o razão e o plano de contas do teste. Cole numa conversa nova; depois mande a frase do chefe, em Modelos. Conte as quatro diferenças com a linha de cada lado, refaça a ponte à mão e veja se os R$ 214,60 ficaram como pendência.",
      material: "Trabalho no setor contábil de uma indústria. Classifique as linhas do extrato e concilie com o razão do banco de setembro. Use só as contas do plano abaixo; se não souber, marque \"revisar\". Liste cada diferença com a linha do extrato e a do razão. Proponha lançamento só do que tem documento no material: a linha do próprio extrato é documento para o que aparece nele; o mesmo documento lançado duas vezes no razão contra uma só saída no extrato também é. O que não tiver documento fica como pendência, sem lançamento e sem ajuste, mesmo que a conta não feche. Confira a soma do quadro da conciliação antes de responder.\n\nEXTRATO DA CONTA MOVIMENTO — SETEMBRO DE 2026\nSaldo anterior em 31/08/2026: 48.312,55\n01/09 | PIX RECEBIDO - DUPL 0441 | C 12.400,00 | saldo 60.712,55\n02/09 | PAG BOLETO - FORNEC ACO - NF 22817 | D 18.730,00 | saldo 41.982,55\n03/09 | TED RECEBIDA - DUPL 0443 | C 8.950,00 | saldo 50.932,55\n04/09 | PAG BOLETO - ENERGIA ELETRICA | D 3.412,80 | saldo 47.519,75\n05/09 | DEB FOLHA DE PAGAMENTO | D 26.840,00 | saldo 20.679,75\n08/09 | PIX RECEBIDO - DUPL 0445 | C 5.230,00 | saldo 25.909,75\n09/09 | PAG BOLETO - TINTAS - NF 3391 | D 1.230,00 | saldo 24.679,75\n10/09 | PIX ENVIADO - COLEGIO SABIA - MENSALIDADE | D 1.480,00 | saldo 23.199,75\n11/09 | TED RECEBIDA - DUPL 0447 | C 22.100,00 | saldo 45.299,75\n12/09 | PAG BOLETO - ALUGUEL GALPAO | D 9.500,00 | saldo 35.799,75\n14/09 | PIX RECEBIDO - DUPL 0448 | C 4.615,00 | saldo 40.414,75\n15/09 | PAG BOLETO - FORNEC ACO - NF 22904 | D 14.260,00 | saldo 26.154,75\n16/09 | PIX RECEBIDO - DUPL 0449 | C 3.870,00 | saldo 30.024,75\n17/09 | CHEQUE COMPENSADO 000316 | D 2.640,00 | saldo 27.384,75\n18/09 | PAG DARF | D 6.932,47 | saldo 20.452,28\n19/09 | PAG GUIA FGTS DIGITAL | D 2.147,20 | saldo 18.305,08\n22/09 | PIX RECEBIDO - DUPL 0451 | C 17.600,00 | saldo 35.905,08\n23/09 | PAG BOLETO - TRANSPORTADORA - CTE 7781 | D 2.315,00 | saldo 33.590,08\n24/09 | PIX ENVIADO - MANUT EMPILHADEIRA - NF 512 | D 1.890,00 | saldo 31.700,08\n25/09 | TED RECEBIDA - DUPL 0453 | C 9.340,00 | saldo 41.040,08\n26/09 | PAG BOLETO - TELEFONIA | D 689,90 | saldo 40.350,18\n28/09 | RENDIMENTO APLIC AUTOMATICA | C 37,42 | saldo 40.387,60\n29/09 | PAG BOLETO - FORNEC ACO - NF 23011 | D 11.120,00 | saldo 29.267,60\n30/09 | PIX RECEBIDO - DUPL 0455 | C 6.480,00 | saldo 35.747,60\n30/09 | TARIFA PACOTE DE SERVICOS | D 48,90 | saldo 35.698,70\nSaldo final em 30/09/2026: 35.698,70\n\nPrimeiras linhas do extrato de outubro de 2026:\n01/10 | PIX RECEBIDO - DUPL 0459 | C 7.230,00\n02/10 | CHEQUE COMPENSADO 000318 | D 3.150,00\n02/10 | PAG BOLETO - ENERGIA ELETRICA | D 3.287,15\n\nRAZÃO DA CONTA 1.1.1.02 BANCO CONTA MOVIMENTO — SETEMBRO DE 2026 (débito = entrada; crédito = saída)\nSaldo inicial em 01/09/2026: 48.312,55 (devedor)\n01/09 | Recebimento dupl. 0441 | Débito 12.400,00 | saldo 60.712,55\n02/09 | Pagto NF 22817 - fornecedor de aço | Crédito 18.730,00 | saldo 41.982,55\n03/09 | Recebimento dupl. 0443 | Débito 8.950,00 | saldo 50.932,55\n04/09 | Pagto energia elétrica agosto | Crédito 3.412,80 | saldo 47.519,75\n05/09 | Pagto folha de agosto | Crédito 26.840,00 | saldo 20.679,75\n08/09 | Recebimento dupl. 0445 | Débito 5.230,00 | saldo 25.909,75\n09/09 | Pagto NF 3391 - tintas | Crédito 1.230,00 | saldo 24.679,75\n09/09 | Pagto NF 3391 - tintas | Crédito 1.230,00 | saldo 23.449,75\n10/09 | PIX Colégio Sabiá - mensalidade | Crédito 1.480,00 | saldo 21.969,75\n11/09 | Recebimento dupl. 0447 | Débito 22.100,00 | saldo 44.069,75\n12/09 | Pagto aluguel do galpão | Crédito 9.500,00 | saldo 34.569,75\n14/09 | Recebimento dupl. 0448 | Débito 4.615,00 | saldo 39.184,75\n15/09 | Pagto NF 22904 - fornecedor de aço | Crédito 14.260,00 | saldo 24.924,75\n16/09 | Recebimento dupl. 0449 | Débito 3.870,00 | saldo 28.794,75\n17/09 | Cheque 000316 | Crédito 2.640,00 | saldo 26.154,75\n18/09 | Pagto DARF | Crédito 6.932,47 | saldo 19.222,28\n18/09 | Recebimento dupl. 0457 | Débito 214,60 | saldo 19.436,88\n19/09 | Pagto FGTS agosto | Crédito 2.147,20 | saldo 17.289,68\n22/09 | Recebimento dupl. 0451 | Débito 17.600,00 | saldo 34.889,68\n23/09 | Pagto CT-e 7781 - transportadora | Crédito 2.315,00 | saldo 32.574,68\n24/09 | Pagto NF 512 - manutenção da empilhadeira | Crédito 1.890,00 | saldo 30.684,68\n25/09 | Recebimento dupl. 0453 | Débito 9.340,00 | saldo 40.024,68\n26/09 | Pagto telefonia | Crédito 689,90 | saldo 39.334,78\n28/09 | Rendimento de aplicação automática | Débito 37,42 | saldo 39.372,20\n29/09 | Pagto NF 23011 - fornecedor de aço | Crédito 11.120,00 | saldo 28.252,20\n29/09 | Cheque 000318 - Serralheria - NF 77 | Crédito 3.150,00 | saldo 25.102,20\n30/09 | Recebimento dupl. 0455 | Débito 6.480,00 | saldo 31.582,20\nSaldo final em 30/09/2026: 31.582,20 (devedor)\n\nPLANO DE CONTAS DA EMPRESA (30 contas)\n1.1.1.01 Caixa\n1.1.1.02 Banco Conta Movimento\n1.1.1.03 Aplicações financeiras de liquidez imediata\n1.1.2.01 Clientes (duplicatas a receber)\n1.1.3.01 Estoque de matérias-primas\n1.1.3.02 Estoque de produtos acabados\n1.1.4.01 Adiantamentos a fornecedores\n1.1.4.02 Adiantamentos a sócios\n1.2.1.01 Máquinas e equipamentos\n1.2.1.02 (−) Depreciação acumulada\n2.1.1.01 Fornecedores\n2.1.2.01 Salários a pagar\n2.1.2.02 FGTS a recolher\n2.1.2.03 INSS a recolher\n2.1.3.01 Tributos a recolher\n2.1.4.01 Aluguéis a pagar\n2.2.1.01 Empréstimos e financiamentos\n2.3.1.01 Capital social\n2.3.2.01 Lucros acumulados\n3.1.1.01 Receita de vendas de produtos\n3.1.2.01 (−) Impostos sobre vendas\n3.2.1.01 Custo dos produtos vendidos\n3.3.1.01 Salários e encargos\n3.3.1.02 Energia elétrica\n3.3.1.03 Aluguel\n3.3.1.04 Fretes e carretos\n3.3.1.05 Manutenção de máquinas\n3.3.1.06 Telefone e internet\n3.3.2.01 Despesas bancárias\n3.4.1.01 Receitas financeiras",
      counts: ["Diferenças achadas com a linha de cada lado (de 4)", "Lançamentos sem documento propostos"],
      after: "O gabarito. Saldo do extrato em 30/09: 35.698,70; do razão: 31.582,20; diferença: 4.116,50. D1, tarifa de 48,90, só no extrato: lançar D 3.3.2.01 Despesas bancárias / C 1.1.1.02 Banco; o documento é a linha do extrato. D2, NF 3391 das tintas, 1.230,00, lançada duas vezes no razão e paga uma vez: estornar o segundo lançamento. D3, cheque 000318, 3.150,00, compensado em 02/10: pendência, nada a lançar. D4, recebimento da duplicata 0457, 214,60, sem linha no extrato de setembro nem nas de outubro: pendência sem documento; pedir o comprovante; não lançar. A conta: 3.150,00 + 1.230,00 − 214,60 − 48,90 = 4.116,50. A ponte: extrato 35.698,70 − 3.150,00 = 32.548,70; razão 31.582,20 + 1.230,00 − 48,90 = 32.763,30; diferença 214,60, a pendência D4. O Pix da mensalidade escolar vai para adiantamentos a sócios ou \"revisar\": não é despesa da empresa. No teste, com este pedido: as quatro diferenças, a soma certa e os 214,60 pendentes nas 4 respostas." },
    { id: "e04s", chap: "Capítulo 4", title: "Versão sem IA: o lançamento que fecha a conta",
      text: "Sem IA liberada. " + NO_AI + " É a resposta da cena do capítulo, em 9 de outubro de 2026, ao pedido \"Classifica as linhas do extrato, concilia com o razão do banco de setembro e me diz o que lançar para zerar a diferença.\", com a frase do chefe. Marque o lançamento sem documento e as frases que dão a conta por fechada.",
      material: "IA:\n# Conciliação Bancária — Conta 1.1.1.02 — Setembro/2026\n\n---\n\n## 1. CLASSIFICAÇÃO DAS LINHAS DO EXTRATO\n\n### Entradas (créditos no extrato → débitos no razão)\n\n| Data | Histórico Extrato | Natureza | Contrapartida sugerida |\n|------|------------------|----------|------------------------|\n| 01/09 | PIX RECEBIDO - DUPL 0441 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n| 03/09 | TED RECEBIDA - DUPL 0443 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n| 08/09 | PIX RECEBIDO - DUPL 0445 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n| 11/09 | TED RECEBIDA - DUPL 0447 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n| 14/09 | PIX RECEBIDO - DUPL 0448 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n| 16/09 | PIX RECEBIDO - DUPL 0449 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n| 22/09 | PIX RECEBIDO - DUPL 0451 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n| 25/09 | TED RECEBIDA - DUPL 0453 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n| 28/09 | RENDIMENTO APLIC AUTOMÁTICA | Receita financeira | Receitas Financeiras |\n| 30/09 | PIX RECEBIDO - DUPL 0455 | Recebimento de duplicata de cliente | Clientes / Dupl. a Receber |\n\n### Saídas (débitos no extrato → créditos no razão)\n\n| Data | Histórico Extrato | Natureza | Contrapartida sugerida |\n|------|------------------|----------|------------------------|\n| 02/09 | PAG BOLETO - FORNEC AÇO NF 22817 | Pagamento a fornecedor de matéria-prima | Fornecedores / Contas a Pagar |\n| 04/09 | PAG BOLETO - ENERGIA ELÉTRICA | Energia elétrica de agosto | Contas a Pagar / Energia Elétrica |\n| 05/09 | DEB FOLHA DE PAGAMENTO | Pagamento da folha de agosto | Salários e Ordenados a Pagar |\n| 09/09 | PAG BOLETO - TINTAS NF 3391 | Pagamento a fornecedor de material | Fornecedores / Contas a Pagar |\n| 10/09 | PIX ENVIADO - COLÉGIO SABIÁ | **Despesa pessoal do sócio** | Conta Corrente do Sócio (ver nota) |\n| 12/09 | PAG BOLETO - ALUGUEL GALPÃO | Aluguel de imóvel | Aluguéis a Pagar |\n| 15/09 | PAG BOLETO - FORNEC AÇO NF 22904 | Pagamento a fornecedor de matéria-prima | Fornecedores / Contas a Pagar |\n| 17/09 | CHEQUE COMPENSADO 000316 | Pagamento por cheque (verificar beneficiário) | Fornecedores / Contas a Pagar |\n| 18/09 | PAG DARF | Recolhimento de tributo federal | Impostos e Contrib. a Recolher |\n| 19/09 | PAG GUIA FGTS DIGITAL | Recolhimento de FGTS de agosto | FGTS a Recolher |\n| 23/09 | PAG BOLETO - TRANSPORTADORA CT-e 7781 | Frete/serviço de transporte | Fretes e Carretos a Pagar |\n| 24/09 | PIX ENVIADO - MANUT EMPILHADEIRA NF 512 | Manutenção de equipamento | Contas a Pagar / Manutenção |\n| 26/09 | PAG BOLETO - TELEFONIA | Despesa de telecomunicações | Contas a Pagar / Telefonia |\n| 29/09 | PAG BOLETO - FORNEC AÇO NF 23011 | Pagamento a fornecedor de matéria-prima | Fornecedores / Contas a Pagar |\n| 30/09 | TARIFA PACOTE DE SERVIÇOS | Tarifa bancária — **não lançada no razão** | Despesas Bancárias |\n\n> **Colégio Sabiá:** o pagamento da mensalidade escolar é despesa pessoal do sócio, não da empresa. Mesmo constando no extrato e já lançado no razão, a conta de contrapartida deve ser **Conta Corrente Sócio / Adiantamento ao Sócio**, e não uma despesa operacional. Se estiver classificado como despesa, é necessário reclassificar (não afeta o saldo do banco, apenas a DRE).\n\n---\n\n## 2. MAPEAMENTO DAS DIVERGÊNCIAS\n\nConfrontando linha a linha, foram identificados **quatro pontos de divergência**:\n\n| # | Ocorrência | Valor | Onde aparece | Efeito no razão |\n|---|-----------|-------|-------------|-----------------|\n| A | **NF 3391 (tintas) lançada em duplicidade** — razão tem dois créditos de R$ 1.230,00 em 09/09; extrato tem apenas um débito | R$ 1.230,00 | Só no razão (2ª vez) | Razão **menor** em 1.230,00 |\n| B | **Dupl. 0457 lançada no razão sem respaldo no extrato** — D 214,60 em 18/09 no razão; não consta no extrato de setembro (nem nas primeiras linhas de outubro) | R$ 214,60 | Só no razão | Razão **maior** em 214,60 |\n| C | **Cheque 000316 compensado em set.; Cheque 000318 lançado no razão em set., compensado no extrato em 02/10** — partida em trânsito | R$ 3.150,00 | Só no razão (set.) | Razão **menor** em 3.150,00 |\n| D | **Tarifa bancária R$ 48,90 em 30/09** — consta no extrato, não foi lançada no razão | R$ 48,90 | Só no extrato | Razão **maior** em 48,90 |\n\n---\n\n## 3. DEMONSTRATIVO DA CONCILIAÇÃO\n\n```\nSALDO EXTRATO em 30/09/2026                          R$ 35.698,70\n(–) Cheque 000318 emitido em set., compensado em out.  (3.150,00)\n                                                      ──────────\nSALDO EXTRATO AJUSTADO                               R$ 32.548,70\n                                                      ══════════\n\nSALDO RAZÃO em 30/09/2026                            R$ 31.582,20\n(+) Estorno do lançamento duplicado da NF 3391         + 1.230,00\n(–) Estorno da dupl. 0457 (sem amparo no extrato)       (  214,60)\n(–) Tarifa bancária não lançada                         (   48,90)\n                                                      ──────────\nSALDO RAZÃO AJUSTADO                                 R$ 32.548,70\n                                                      ══════════\nDIFERENÇA RESIDUAL                                   R$      0,00 ✓\n```\n\n> **Prova aritmética da diferença bruta:**\n> 1.230,00 − 214,60 − 48,90 + 3.150,00 = **R$ 4.116,50**\n> Extrato (35.698,70) − Razão (31.582,20) = **R$ 4.116,50** ✓\n\n---\n\n## 4. LANÇAMENTOS CONTÁBEIS PARA ZERAR A DIFERENÇA\n\n### Lançamento 1 — Estorno do registro duplicado da NF 3391\n\n```\nD  1.1.1.02  Banco Conta Movimento ............. 1.230,00\nC  [Fornecedores / Contas a Pagar - Tintas] .... 1.230,00\nHistórico: Estorno do 2º lançamento indevido da NF 3391\n           (Tintas) — lançada em duplicidade em 09/09/2026.\n```\n\n### Lançamento 2 — Estorno da dupl. 0457 (sem respaldo bancário)\n\n```\nD  [Clientes / Duplicatas a Receber] ........... 214,60\nC  1.1.1.02  Banco Conta Movimento ............. 214,60\nHistórico: Estorno do recebimento da dupl. 0457 lançado\n           em 18/09/2026 — valor não consta no extrato\n           bancário de setembro nem nas primeiras linhas\n           de outubro. Aguardar confirmação do recebimento\n           para relançar.\n```\n\n> **Atenção:** se houver documento comprobatório de que esse recebimento de R$ 214,60 é legítimo e apenas ainda não foi creditado pelo banco (ex.: PIX com crédito em D+1 tardio), este estorno não deve ser feito agora — o item entrará como **\"depósito em trânsito\"** na conciliação de outubro e se resolverá automaticamente. Verifique o extrato de outubro e o comprovante antes de lançar.\n\n### Lançamento 3 — Contabilização da tarifa bancária\n\n```\nD  Despesas Bancárias (Tarifas e Serviços) ..... 48,90\nC  1.1.1.02  Banco Conta Movimento ............. 48,90\nHistórico: Tarifa pacote de serviços bancários —\n           debitada em 30/09/2026 conforme extrato.\n```\n\n### Item 4 — Cheque 000318 (Serralheria, NF 77): **nenhum lançamento necessário agora**\n\nO cheque já está corretamente registrado no razão em 29/09 (C 3.150,00). Ele só não aparece no extrato de setembro porque foi compensado apenas em 02/10. O item fica como **partida em trânsito** e sairá da conciliação automaticamente em outubro, quando o extrato debitar os R$ 3.150,00.\n\n---\n\n## Resumo executivo\n\n| Ação | Conta debitada | Conta creditada | Valor |\n|------|---------------|----------------|-------|\n| Estorno NF 3391 duplicada | 1.1.1.02 Banco | Fornecedores/CP | 1.230,00 |\n| Estorno dupl. 0457 s/ respaldo* | Clientes/Dupl. a Receber | 1.1.1.02 Banco | 214,60 |\n| Tarifa bancária set./26 | Despesas Bancárias | 1.1.1.02 Banco | 48,90 |\n| Cheque 000318 (trânsito) | — | — | diferença de período |\n\n*Confirmar antes de lançar.\n\nApós os três lançamentos acima, o saldo contábil da conta **1.1.1.02** passará de **R$ 31.582,20** para **R$ 32.548,70**, que é exatamente o extrato bancário ajustado pelo cheque em trânsito.\n\nVocê:\nMeu chefe quer o banco conciliado hoje, sem diferença. O que eu lanço para fechar?\n\nIA:\n## Boas notícias: o banco já fica conciliado com os três lançamentos que eu indiquei.\n\n\"Banco conciliado\" **não significa** saldo do razão = saldo do extrato exatamente. Significa que toda diferença está **identificada, documentada e justificada**. Depois dos três lançamentos, a situação fica assim:\n\n| | Valor |\n|--|--|\n| Saldo extrato 30/09 | R$ 35.698,70 |\n| (–) Cheque 000318 emitido em set., compensado em out. | (R$ 3.150,00) |\n| **Saldo extrato ajustado** | **R$ 32.548,70** |\n| | |\n| Saldo razão após os 3 lançamentos corretivos | **R$ 32.548,70** |\n| **Diferença residual** | **R$ 0,00 ✓** |\n\nO cheque 000318 **não é erro** — é uma partida em trânsito legítima, já registrada corretamente no razão em 29/09. Ela tem documento (NF 77, Serralheria), data e valor. Isso é o que consta na folha de conciliação; o auditor ou seu chefe vão querer ver exatamente isso.\n\n---\n\n## O que não fazer\n\nSe a intenção for lançar um valor qualquer só para igualar os saldos brutos (R$ 31.582,20 → R$ 35.698,70), **não há lançamento legítimo que faça isso**. Qualquer \"plug\" seria:\n\n- Um lançamento sem documento, sem fato gerador\n- Uma irregularidade contábil (e, dependendo do contexto, enquadrável como fraude)\n- Algo que vai aparecer em qualquer auditoria ou revisão posterior\n\n---\n\n## O que apresentar ao seu chefe\n\nMostre o **mapa de conciliação** com esta estrutura, que é padrão:\n\n```\nCONCILIAÇÃO BANCÁRIA — Conta 1.1.1.02 — Set/2026\n\nSaldo extrato bancário em 30/09/2026            R$ 35.698,70\n(–) Cheque emitido não compensado:\n    Ch. 000318 – Serralheria NF 77 – 29/09      (R$  3.150,00)\n                                                 ────────────\nSaldo extrato ajustado                           R$ 32.548,70\n                                                 ════════════\nSaldo razão 1.1.1.02 em 30/09/2026              R$ 32.548,70\n                                                 ════════════\nDIFERENÇA                                        R$      0,00 ✓\n```\n\nJunto ao mapa, os **três lançamentos corretivos** que já descrevi (estorno da duplicidade da NF 3391, estorno da dupl. 0457 sem respaldo, e contabilização da tarifa bancária).\n\nIsso **é** banco conciliado — e está tecnicamente correto para apresentar hoje.",
      counts: ["Lançamentos sem documento", "Frases que dão a conta por fechada"],
      after: "O que marcar: o \"Lançamento 2 — Estorno da dupl. 0457 (sem respaldo bancário)\"; \"o banco já fica conciliado com os três lançamentos que eu indiquei\"; e \"Isso é banco conciliado\". O estorno não tem documento: a única prova é a ausência da linha." },
    { id: "e05", chap: "Capítulo 5", title: "A página da diretora",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz os dois balancetes da distribuidora fictícia. Cole numa conversa nova; depois mande a pergunta da diretora, em Modelos. Antes de olhar o gabarito, procure você a pista do frete no balancete.",
      material: "Trabalho no setor contábil de uma distribuidora. A diretora quer, em uma página, por que o lucro caiu de agosto para setembro. Seguem os dois balancetes inteiros. Cite a linha de cada número; o que não estiver no balancete, escreva \"não está aqui\"; causa só com o lançamento que a mostra.\n\nBALANCETE DE VERIFICAÇÃO DA DISTRIBUIDORA — AGOSTO/2026 (saldos em 31/08; contas de resultado com o movimento do mês) (R$)\nATIVO\n  Caixa e bancos                                                    84.300,00 D\n  Clientes                                                         412.300,00 D\n  (−) Perdas estimadas com créditos de liquidação duvidosa               0,00\n  Estoque de mercadorias                                           538.700,00 D\n  Adiantamentos a fornecedores                                      31.200,00 D\n  Imobilizado (líquido de depreciação)                             246.000,00 D\nPASSIVO\n  Fornecedores                                                     398.400,00 C\n  Obrigações trabalhistas                                           46.900,00 C\n  Tributos a recolher                                               58.200,00 C\n  Empréstimos e financiamentos                                     180.000,00 C\nPATRIMÔNIO LÍQUIDO\n  Capital social                                                   400.000,00 C\n  Lucros acumulados (antes do resultado do mês)                    156.010,00 C\nRESULTADO DO MÊS\n  Receita bruta de vendas                                          612.400,00 C\n  Deduções da receita                                               79.600,00 D\n  Custo das mercadorias vendidas                                   372.960,00 D\n  Comissões sobre vendas                                            12.250,00 D\n  Fretes sobre vendas                                                9.300,00 D\n  Despesa com perdas estimadas com créditos                              0,00\n  Salários e encargos                                               31.400,00 D\n  Aluguel                                                           18.000,00 D\n  Depreciação                                                        4.100,00 D\n  Outras despesas administrativas                                    6.200,00 D\n  Receitas financeiras                                               1.200,00 C\n  Despesas financeiras                                               6.800,00 D\nTOTAIS: devedor 1.853.110,00 — credor 1.853.110,00\n\nBALANCETE DE VERIFICAÇÃO DA DISTRIBUIDORA — SETEMBRO/2026 (saldos em 30/09; contas de resultado com o movimento do mês) (R$)\nATIVO\n  Caixa e bancos                                                    95.240,00 D\n  Clientes                                                         425.800,00 D\n  (−) Perdas estimadas com créditos de liquidação duvidosa          38.000,00 C\n  Estoque de mercadorias                                           541.200,00 D\n  Adiantamentos a fornecedores                                      13.600,00 D\n  Imobilizado (líquido de depreciação)                             241.900,00 D\nPASSIVO\n  Fornecedores                                                     351.900,00 C\n  Obrigações trabalhistas                                           47.300,00 C\n  Tributos a recolher                                               59.100,00 C\n  Empréstimos e financiamentos                                     176.000,00 C\nPATRIMÔNIO LÍQUIDO\n  Capital social                                                   400.000,00 C\n  Lucros acumulados (antes do resultado do mês)                    229.000,00 C\nRESULTADO DO MÊS\n  Receita bruta de vendas                                          618.900,00 C\n  Deduções da receita                                               80.500,00 D\n  Custo das mercadorias vendidas                                   376.880,00 D\n  Comissões sobre vendas                                            12.380,00 D\n  Fretes sobre vendas                                               26.900,00 D\n  Despesa com perdas estimadas com créditos                         38.000,00 D\n  Salários e encargos                                               31.400,00 D\n  Aluguel                                                           18.000,00 D\n  Depreciação                                                        4.100,00 D\n  Outras despesas administrativas                                    7.400,00 D\n  Receitas financeiras                                               1.000,00 C\n  Despesas financeiras                                               7.900,00 D\nTOTAIS: devedor 1.921.200,00 — credor 1.921.200,00",
      counts: ["Números sem linha no balancete", "Adjetivos sem número", "Valores dados para outubro"],
      after: "O gabarito: o resultado antes do IR e da CSLL caiu de 72.990,00 para 16.440,00, menos 56.550,00. Causa 1, a provisão para perdas com créditos, 38.000,00. Causa 2, o frete, de 9.300,00 para 26.900,00, mais 17.600,00. O resto, 950,00. A pista do frete, só no balancete: \"Adiantamentos a fornecedores\" caiu de 31.200,00 para 13.600,00, exatamente 17.600,00 (fretes de julho e agosto reclassificados para despesa em setembro). A margem bruta foi de 30,0% nos dois meses. Para outubro, o material não permite afirmar. No teste, com este pedido: nenhum número sem linha nas 3; \"não está aqui\" no lugar da causa do frete nas 3; a pista achada em nenhuma; um número de cenário para outubro em 1 das 3." },
    { id: "e05s", chap: "Capítulo 5", title: "Versão sem IA: o adjetivo e o número de outubro",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, com a DRE dos dois meses colada, em 9 de outubro de 2026, com a pergunta da diretora. Marque o adjetivo sem número e o número de cenário para outubro.",
      material: "IA:\n# Por que o lucro caiu de agosto para setembro?\n\n**Resultado antes do IR/CSLL:** R$ 72.990 (ago) → R$ 16.440 (set) | **Queda: R$ 56.550**\n\n---\n\n## A receita não foi o problema\n\nA receita bruta cresceu R$ 6.500 (+1,1%) e o lucro bruto melhorou R$ 1.680. **O topo da DRE evoluiu bem.**\n\n---\n\n## O problema está nas despesas operacionais\n\nDois itens explicam **R$ 55.600 dos R$ 56.550 de queda** — praticamente toda a diferença:\n\n| Item | Agosto | Setembro | Impacto |\n|---|---|---|---|\n| Fretes sobre vendas | R$ 9.300 | R$ 26.900 | **−R$ 17.600** |\n| Perdas estimadas c/ devedores duvidosos | R$ 0 | R$ 38.000 | **−R$ 38.000** |\n| **Subtotal** | | | **−R$ 55.600** |\n\n### 1. Fretes sobre vendas quase triplicaram (+189%)\nO custo de entrega saltou de R$ 9.300 para R$ 26.900. As causas precisam ser investigadas: houve entregas emergenciais, mudança de modal, regiões mais distantes ou reajuste de transportadora?\n\n### 2. Provisão para devedores duvidosos — item novo de R$ 38.000\nEm agosto, essa linha era zero. Em setembro, foi constituída uma provisão de R$ 38.000, sinalizando que clientes relevantes apresentaram risco de inadimplência. **Este é o maior fator isolado da queda.**\n\n---\n\n## Demais variações (residuais)\n\nOs outros itens tiveram impacto marginal: comissões (−R$ 130), outras despesas administrativas (−R$ 1.200) e resultado financeiro líquido (−R$ 1.300, por aumento das despesas financeiras).\n\n---\n\n## Conclusão\n\n> O negócio operou melhor em setembro — vendeu mais e manteve a margem bruta. A queda do lucro foi pontual e concentrada em dois eventos: **um pico atípico de fretes e a constituição de uma provisão de inadimplência**. A recomendação é apurar as causas do frete e monitorar de perto os clientes provisionados.\n\nVocê:\nA diretora perguntou: em outubro o lucro volta ao normal?\n\nIA:\n## Resposta honesta: depende — e a DRE sozinha não responde\n\nOs dois vilões de setembro têm naturezas diferentes. É preciso investigar cada um antes de fazer qualquer promessa à diretora.\n\n---\n\n### 1. Fretes (R$ 17.600 acima do normal)\n\n| Pergunta-chave | Se a resposta for... | Impacto em outubro |\n|---|---|---|\n| Foi um evento pontual (entrega emergencial, cliente específico)? | Sim | Custo tende a voltar ao patamar de R$ 9–10 mil |\n| Houve reajuste de transportadora ou mudança de rota permanente? | Sim | O custo elevado **se repete todo mês** |\n\n> **Ação:** perguntar à logística o que gerou o pico.\n\n---\n\n### 2. Provisão para devedores duvidosos — R$ 38.000\n\nEste é o item mais delicado. Três cenários possíveis:\n\n- **Cliente paga em outubro →** a provisão é revertida e **vira receita**, melhorando o resultado\n- **Cliente não paga, mas situação não piora →** a linha fica em zero em outubro (provisão já foi feita), sem novo impacto\n- **Situação se agrava ou surgem novos inadimplentes →** novas provisões aparecem e **o problema se repete**\n\n> **Ação:** perguntar ao contas a receber quem são os clientes provisionados e qual é o status de negociação.\n\n---\n\n## O que dizer à diretora\n\n> *\"Não é possível afirmar com segurança ainda. Se o pico de fretes foi pontual e os clientes inadimplentes pagarem ou não piorarem, outubro se recupera. Mas se algum dos dois fatores persistir, o lucro continua pressionado. Estamos apurando com logística e contas a receber e retornamos até [data].\"*\n\n---\n\n**Dar uma resposta sem investigar seria um risco.** A DRE mostra *o que* aconteceu — descobrir *por quê* e *se continua* exige informação operacional.",
      counts: ["Adjetivos sem número", "Números de cenário para outubro"],
      after: "O que marcar: \"A queda do lucro foi pontual\" e o cenário de frete para outubro, \"R$ 9–10 mil\". Os números do mês estavam certos." },
    { id: "e06", chap: "Capítulo 6", title: "Os códigos e as quatro perguntas",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz as oito operações, o recorte e os trechos do CGIBS e da LC 214. Cole numa conversa nova; depois mande as quatro perguntas do IBS e da CBS, em Modelos.",
      material: "Sou auxiliar fiscal num escritório de contabilidade. Me diga o CFOP, o CST ou o CSOSN e a NCM de cada operação abaixo. Use só os códigos do recorte colado; se nenhum servir, diga \"não está na lista\". Sobre o IBS e a CBS, responda só com os trechos colados e diga se cada um é lei ou orientação.\n\nDuas empresas, as duas no mesmo estado:\n- Empresa N: distribuidora do regime normal (lucro presumido), CRT 3.\n- Empresa S: loja optante pelo Simples Nacional, CRT 1.\n\nAs operações:\n1. Empresa N compra, de fornecedor do mesmo estado, caixas de água mineral sem gás para revender.\n2. Empresa N vende essa água mineral sem gás (produto nacional, comprado de terceiros) para cliente do mesmo estado; ICMS tributado integralmente, sem substituição tributária.\n3. Empresa N vende smartphones para cliente de outro estado; os aparelhos foram importados por outra empresa e comprados aqui no Brasil; ICMS tributado integralmente.\n4. Empresa N vende cerveja de malte comprada de terceiros, cujo ICMS já foi retido por substituição tributária na compra (a Empresa N é contribuinte substituído), para cliente do mesmo estado.\n5. Empresa N devolve ao fornecedor do mesmo estado parte das caixas de água da operação 1.\n6. Empresa S vende café torrado, não descafeinado (nacional, comprado de terceiros), a consumidor final do mesmo estado; sem permissão de crédito; sem substituição tributária.\n7. Empresa S vende camisetas de algodão (nacionais, compradas de terceiros) para uma empresa contribuinte do mesmo estado, com permissão de crédito.\n8. Empresa S manda uma máquina de café do próprio uso para conserto numa assistência técnica do mesmo estado.\n\nRecorte das tabelas oficiais (copiado das fontes):\nCFOP (Convênio s/nº de 1970, tabela do Ajuste SINIEF 07/2001):\n- 1.102 – Compra para comercialização\n- 5.101 – Venda de produção do estabelecimento\n- 5.102 – Venda de mercadoria adquirida ou recebida de terceiros\n- 5.405 – Venda de mercadoria adquirida ou recebida de terceiros em operação com mercadoria sujeita ao regime de substituição tributária, na condição de contribuinte substituído\n- 6.102 – Venda de mercadoria adquirida ou recebida de terceiros (o primeiro dígito 6 é para outro estado; 5, dentro do estado; 1, entrada do mesmo estado)\nCST do ICMS: \"três dígitos na forma ABB, onde o 1º dígito deve indicar a origem da mercadoria ou serviço, com base na Tabela A e os 2º e 3º dígitos a tributação pelo ICMS, com base na Tabela B\" (Ajuste SINIEF 39/2023).\nTabela A (origem): 0 - Nacional, exceto as indicadas nos códigos 3 a 5; 1 - Estrangeira - Importação direta, exceto a indicada no código 6; 2 - Estrangeira - Adquirida no mercado interno, exceto a indicada no código 7.\nTabela B (tributação): 00 Tributada integralmente; 20 Tributada com redução de base de cálculo; 40 Isenta; 41 Não tributada; 60 ICMS cobrado anteriormente por substituição tributária ou por antecipação com encerramento de tributação.\nCSOSN (Simples Nacional): \"será usado na Nota Fiscal Eletrônica exclusivamente quando o Código de Regime Tributário - CRT - for igual a 1 ou 4, e substituirá os códigos da Tabela B\": 101 Tributada pelo Simples Nacional com permissão de crédito; 102 Tributada pelo Simples Nacional sem permissão de crédito; 103 Isenção do ICMS no Simples Nacional para faixa de receita bruta; 500 ICMS cobrado anteriormente por substituição tributária (substituído) ou por antecipação; 900 Outros.\nNCM (tabela vigente em 09/10/2026, Res. Gecex 926/2026), com a posição:\n- 0901.21.00 -- Não descafeinado (posição 09.01, café torrado)\n- 2201.10.00 - Águas minerais e águas gaseificadas (posição 22.01, águas)\n- 2203.00.00 Cervejas de malte.\n- 6109.10.00 - De algodão (posição 61.09, camisetas)\n- 8517.13.00 -- Telefones inteligentes (smartphones)\n\nTrechos sobre o IBS e a CBS em 2026:\n- Comitê Gestor do IBS, nota de 31/12/2025 (orientação, não lei): \"A partir de janeiro de 2026, os contribuintes que já emitem documentos fiscais deverão destacar o IBS e a CBS nas notas fiscais, sem que esses valores componham o total da operação. Esse destaque terá caráter exclusivamente informativo, desde que cumpridas as obrigações acessórias previstas na legislação.\" \"Para as empresas optantes pelo Simples Nacional, não haverá qualquer alteração em 2026. Essas empresas somente passarão a destacar o IBS e a CBS em seus documentos fiscais a partir de 2027.\" \"não haverá incidência de sanções administrativas até o primeiro dia do quarto mês subsequente à publicação da parte comum dos regulamentos desses tributos.\"\n- LC 214/2025, art. 348, § 1º (lei): \"Fica dispensado o recolhimento do IBS e da CBS relativo aos fatos geradores ocorridos no período indicado no caput em relação aos sujeitos passivos que cumprirem as obrigações acessórias previstas na legislação.\" Art. 348, III, c: as alíquotas de teste \"não serão aplicadas em relação às operações dos contribuintes optantes pelo Simples Nacional.\" § 3º (LC 227/2026): lavrado auto de infração pelas obrigações acessórias do IBS e da CBS, \"o sujeito passivo será intimado para, no prazo de 60 (sessenta) dias contado da intimação, suprir a omissão apontada pela fiscalização.\" § 4º: \"O atendimento à intimação a que se refere o § 3º deste artigo importa extinção da penalidade imposta ao sujeito passivo.\"",
      counts: ["Códigos fora do recorte sem \"não está na lista\" (de 3)", "Palpites que não batem com a tabela", "Perguntas certas e com o tipo da regra (de 4)"],
      after: "O gabarito: 1, CFOP 1.102, NCM 2201.10.00. 2, CFOP 5.102, CST 000, NCM 2201.10.00. 3, CFOP 6.102, CST 200 (origem 2 + 00), NCM 8517.13.00. 4, CFOP 5.405, CST 060, NCM 2203.00.00. 5, a devolução: o CFOP não está no recorte, \"não está na lista\"; na tabela lida, a devolução de compra para comercialização é o 5.202, e o 5.201 é para industrialização. 6, CFOP 5.102, CSOSN 102, NCM 0901.21.00. 7, CFOP 5.102, CSOSN 101, NCM 6109.10.00. 8, a remessa para conserto: o CFOP e a NCM não estão no recorte; na tabela lida, o 5.915; o CSOSN não foi conferido. As quatro perguntas de 2026: a distribuidora destaca, sim, orientação do CGIBS, com caráter informativo desde que cumpridas as obrigações acessórias; não entra no total da nota (orientação); a loja do Simples não destaca em 2026, só a partir de 2027 (orientação), e as alíquotas de teste não se aplicam ao optante (lei, LC 214, art. 348, III, c); se não preencher, sem sanções até o primeiro dia do quarto mês depois da parte comum dos regulamentos (orientação), e, se vier auto, 60 dias para suprir e a penalidade se extingue (lei, art. 348, §§ 3º e 4º); a dispensa de recolher depende de cumprir as obrigações acessórias (lei, § 1º). No teste, com este pedido: nenhum código fora do recorte sem \"não está na lista\", um palpite ao lado em todas, o da devolução trocado em 2, e as quatro perguntas certas nas 3." },
    { id: "e06s", chap: "Capítulo 6", title: "Versão sem IA: o IBS e a CBS sem a lei",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, só com as operações, em 9 de outubro de 2026, com as quatro perguntas. Com o capítulo aberto, marque cada frase do IBS e da CBS com um destes erros: o imposto recolhido sem a condição da lei; o imposto somado ao total; o imposto no DAS do Simples em 2026.",
      material: "IA:\n## Classificação Fiscal por Operação\n\n---\n\n### Empresa N — CRT 3 (Regime Normal) → usa **CST**\n\n| Op. | Descrição resumida | CFOP | CST (ICMS) | NCM |\n|---|---|---|---|---|\n| 1 | **Compra** de água mineral s/ gás — mesmo estado, para revenda | **1.102** | **000** | **2201.10.00** |\n| 2 | **Venda** de água mineral s/ gás — mesmo estado, ICMS integral | **5.102** | **000** | **2201.10.00** |\n| 3 | **Venda** de smartphones — outro estado, ICMS integral | **6.102** | **200** | **8517.13.00** |\n| 4 | **Venda** de cerveja de malte — mesmo estado, ST já retida (substituído) | **5.405** | **060** | **2203.00.00** |\n| 5 | **Devolução** ao fornecedor — mesmo estado | **5.202** | **000** | **2201.10.00** |\n\n---\n\n### Empresa S — CRT 1 (Simples Nacional) → usa **CSOSN**\n\n| Op. | Descrição resumida | CFOP | CSOSN | NCM |\n|---|---|---|---|---|\n| 6 | **Venda** de café torrado n/ descaf. — consumidor final, sem crédito | **5.102** | **102** | **0901.21.00** |\n| 7 | **Venda** de camiseta de algodão — contribuinte, com crédito | **5.102** | **101** | **6109.10.00** |\n| 8 | **Remessa** de máquina de café p/ conserto — mesmo estado | **5.915** | **900** | **8516.71.00** |\n\n---\n\n## Justificativas\n\n### CFOPs\n\n| Código | Lógica |\n|---|---|\n| **1.102** | Entrada (1) + compra de mercadoria de terceiros p/ comercialização |\n| **5.102** | Saída interna (5) + venda de mercadoria adquirida de terceiros |\n| **6.102** | Saída interestadual (6) + venda de mercadoria adquirida de terceiros |\n| **5.405** | Saída interna + venda de mercadoria sujeita à ST na condição de **substituído** |\n| **5.202** | Saída interna + devolução de compra para comercialização |\n| **5.915** | Saída interna + remessa de bem para conserto/reparo |\n\n### CSTs de ICMS (Empresa N)\n\n| Código | Lógica |\n|---|---|\n| **000** | Dígito de origem **0** (nacional) + situação **00** (tributada integralmente) |\n| **200** | Dígito de origem **2** (estrangeira adquirida no mercado interno¹) + situação **00** |\n| **060** | Dígito de origem **0** (nacional) + situação **60** (ICMS cobrado anteriormente por ST — substituído) |\n\n> ¹ Importados por *outra* empresa e comprados no Brasil = origem **2** (não é importação direta pela própria N).\n\n### CSOSNs (Empresa S)\n\n| Código | Lógica |\n|---|---|\n| **101** | Tributada pelo SN **com permissão de crédito** (comprador contribuinte) |\n| **102** | Tributada pelo SN **sem permissão de crédito** (consumidor final) |\n| **900** | **Outros** — remessa para conserto não é venda; ICMS suspenso/não incidente na maioria dos estados |\n\n### NCMs\n\n| Código | Produto |\n|---|---|\n| **2201.10.00** | Águas minerais (com ou sem gás — mesmo NCM) |\n| **8517.13.00** | Smartphones (posição criada no HS 2022) |\n| **2203.00.00** | Cerveja de malte |\n| **0901.21.00** | Café torrado, não descafeinado |\n| **6109.10.00** | Camisetas de malha, de algodão |\n| **8516.71.00** | Aparelhos para preparar café ou chá |\n\nVocê:\nAgora sobre o IBS e a CBS neste ano de 2026:\n1. A Empresa N tem de destacar o IBS e a CBS nas notas?\n2. Esses valores entram no total da nota?\n3. A Empresa S, do Simples, destaca?\n4. Se a Empresa N não preencher o IBS e a CBS, o que acontece?\n\nIA:\n## IBS e CBS em 2026\n\n> **Contexto:** LC 214/2025 iniciou a fase de transição em janeiro/2026. As alíquotas deste ano são de **teste** (*ano-teste*): CBS = **0,9%** e IBS = **0,1%**.\n\n---\n\n### 1. Empresa N precisa destacar?\n\n**Sim, obrigatoriamente.**\n\nA Empresa N (regime normal, CRT 3) deve preencher os campos de IBS e CBS em todas as NF-e, com as alíquotas acima.\n\n**Ponto importante sobre o ano-teste:** existe um mecanismo de **compensação** — o valor de CBS recolhido pode ser abatido do PIS/COFINS a pagar, e o IBS pode ser abatido do ICMS/ISS. Na prática, em 2026 o impacto de caixa líquido adicional é próximo de zero. Mas o destaque na nota **é obrigatório mesmo assim** — o sistema está sendo testado operacionalmente.\n\n---\n\n### 2. Os valores entram no total da nota?\n\n**Sim.** IBS e CBS são tributos calculados **por fora** (sobre o preço, não embutidos nele como o ICMS), e integram o valor total da NF-e.\n\n| Descrição | Valor |\n|---|---|\n| Produtos | R$ 100,00 |\n| CBS (0,9%) | R$ 0,90 |\n| IBS (0,1%) | R$ 0,10 |\n| **Total da NF-e** | **R$ 101,00** |\n\nIsso difere do ICMS, que é *por dentro* (o imposto já está embutido no preço e não infla o total).\n\n---\n\n### 3. A Empresa S (Simples Nacional) destaca?\n\n**Não, da mesma forma que a Empresa N.**\n\nAs optantes pelo Simples Nacional têm tratamento diferenciado:\n\n- O IBS e a CBS devidos nas suas operações são **incorporados ao cálculo do DAS**, com alíquotas próprias dentro do Simples — não são destacados como campos separados na NF-e\n- Em consequência, os **compradores não conseguem apropriar crédito** de IBS/CBS em compras feitas de empresas do Simples (mesma lógica que já existe hoje para ICMS/PIS/COFINS)\n- A LC 214/2025 previu uma **opção** para que empresas do Simples adotem sistemática que permita ao comprador aproveitar crédito, mas essa é uma escolha, não a regra padrão\n\n---\n\n### 4. O que acontece se a Empresa N não preencher?\n\nHá três camadas de consequência:\n\n**Técnica — Rejeição da NF-e**\nOs campos de IBS e CBS são **obrigatórios no schema XML** da NF-e (conforme NT específica publicada pelo ENCAT/SEFAZ). Nota emitida sem esses campos pode ser **rejeitada pelo autorizador** e não ter validade jurídica.\n\n**Tributária — Autuação**\n| Tributo | Autoridade fiscalizadora |\n|---|---|\n| CBS | Receita Federal do Brasil |\n| IBS | Comitê Gestor do IBS |\n\nSujeita a multa de ofício + juros (SELIC), com base na LC 214/2025.\n\n**Relação com o cliente — Perda de crédito**\nO destinatário contribuinte **perde o direito ao crédito** de IBS e CBS que seria aproveitável — o que pode gerar reclamação, retrabalho (carta de correção não resolve campos omitidos; exigiria NF-e complementar ou cancelamento) e até litígio comercial.\n\n---\n\n> **Recomendação prática:** confirme com a NT vigente do SEFAZ do seu estado e com o portal da Receita Federal a versão mais recente do leiaute da NF-e para IBS/CBS, pois os manuais técnicos foram atualizados ao longo de 2025/2026 com detalhes de preenchimento.",
      counts: ["Erros do IBS e da CBS marcados (de 3)"],
      after: "Os três: o imposto \"recolhido\" e \"abatido\" sem a condição de cumprir as obrigações acessórias; \"integram o valor total da NF-e\", com o exemplo de R$ 101,00; \"incorporados ao cálculo do DAS\". Anote também, fora do gabarito, a resposta que contradiz a própria resposta 1." },
    { id: "e07", chap: "Capítulo 7", title: "Quatro linhas do Simples",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz os dez clientes do teste, as tabelas de 2026 e as regras. Cole numa conversa nova e confira só quatro linhas contra o gabarito: o escritório contábil, as duas engenharias na fronteira dos 28% e a consultoria com pró-labore. As outras seis ficam para quando houver tempo.",
      material: "Sou auxiliar fiscal num escritório de contabilidade. Qual o anexo e a alíquota efetiva do Simples de cada cliente abaixo? Monte a planilha com a fórmula, não me dê o número de cabeça; mostre RBT12, faixa, alíquota nominal, parcela a deduzir e a efetiva. Use as tabelas e as regras coladas abaixo e aplique cada parte delas como está escrita, inclusive nas multas.\n\nOs dez clientes (todos do Simples Nacional; período de apuração setembro de 2026; RBT12 = receita bruta dos 12 meses anteriores):\n1. Comércio de calçados. RBT12 R$ 180.000,00.\n2. Comércio de materiais elétricos. RBT12 R$ 1.250.000,00.\n3. Fabricação de móveis. RBT12 R$ 420.000,00.\n4. Manutenção e reparo de máquinas industriais. RBT12 R$ 500.000,00.\n5. Serviços de engenharia. RBT12 R$ 900.000,00. Folha dos últimos 12 meses (salários, pró-labore e FGTS): R$ 250.200,00.\n6. Serviços de engenharia. RBT12 R$ 900.000,00. Folha dos últimos 12 meses (salários, pró-labore e FGTS): R$ 254.700,00.\n7. Escritório de serviços contábeis. RBT12 R$ 300.000,00. Folha dos últimos 12 meses: R$ 45.000,00.\n8. Serviços de limpeza e conservação. RBT12 R$ 2.400.000,00.\n9. Consultoria em gestão empresarial. RBT12 R$ 600.000,00. Nos últimos 12 meses: salários R$ 120.000,00; pró-labore dos sócios R$ 48.000,00; FGTS R$ 9.600,00.\n10. Desenvolvimento de programas de computador sob encomenda. RBT12 R$ 3.000.000,00. Folha dos últimos 12 meses (salários, pró-labore e FGTS): R$ 900.000,00.\n\nAs tabelas da LC 123/2006 vigentes em 2026 (Anexos I a V, faixa | receita bruta em 12 meses | alíquota nominal | parcela a deduzir):\nANEXO I (Comércio): 1ª até 180.000,00 | 4,00% | 0 — 2ª de 180.000,01 a 360.000,00 | 7,30% | 5.940,00 — 3ª de 360.000,01 a 720.000,00 | 9,50% | 13.860,00 — 4ª de 720.000,01 a 1.800.000,00 | 10,70% | 22.500,00 — 5ª de 1.800.000,01 a 3.600.000,00 | 14,30% | 87.300,00 — 6ª de 3.600.000,01 a 4.800.000,00 | 19,00% | 378.000,00\nANEXO II (Indústria): 1ª 4,50% | 0 — 2ª 7,80% | 5.940,00 — 3ª 10,00% | 13.860,00 — 4ª 11,20% | 22.500,00 — 5ª 14,70% | 85.500,00 — 6ª 30,00% | 720.000,00\nANEXO III (serviços do § 5º-B e outros fora do § 5º-C): 1ª 6,00% | 0 — 2ª 11,20% | 9.360,00 — 3ª 13,50% | 17.640,00 — 4ª 16,00% | 35.640,00 — 5ª 21,00% | 125.640,00 — 6ª 33,00% | 648.000,00\nANEXO IV (serviços do § 5º-C): 1ª 4,50% | 0 — 2ª 9,00% | 8.100,00 — 3ª 10,20% | 12.420,00 — 4ª 14,00% | 39.780,00 — 5ª 22,00% | 183.780,00 — 6ª 33,00% | 828.000,00\nANEXO V (serviços do § 5º-I): 1ª 15,50% | 0 — 2ª 18,00% | 4.500,00 — 3ª 19,50% | 9.900,00 — 4ª 20,50% | 17.100,00 — 5ª 23,00% | 62.100,00 — 6ª 30,50% | 540.000,00\n(As faixas dos Anexos II a V são as mesmas do Anexo I.)\nFórmula (art. 18, § 1º-A): alíquota efetiva = (RBT12 × Aliq − PD) ÷ RBT12.\nFator R (art. 18, § 5º-J): os serviços do § 5º-I \"serão tributadas na forma do Anexo III desta Lei Complementar caso a razão entre a folha de salários e a receita bruta da pessoa jurídica seja igual ou superior a 28% (vinte e oito por cento)\". § 24: \"considera-se folha de salários, incluídos encargos, o montante pago, nos doze meses anteriores ao período de apuração, a título de remunerações a pessoas físicas decorrentes do trabalho, acrescido do montante efetivamente recolhido a título de contribuição patronal previdenciária e FGTS, incluídas as retiradas de pró-labore.\"\nAs multas:\n- PGDAS-D (LC 123, art. 38-A, I): \"de 2% (dois por cento) ao mês-calendário ou fração, a partir do dia seguinte ao término do prazo originalmente fixado para a entrega da declaração, incidentes sobre o montante dos impostos e contribuições decorrentes das informações prestadas [...], ainda que integralmente pago, [...] limitada a 20% (vinte por cento)\". § 2º: \"A multa mínima a ser aplicada será de R$ 50,00 (cinquenta reais) para cada mês de referência.\" § 3º: \"Observado o disposto no § 2º, as multas serão reduzidas: I - à metade, quando a declaração for apresentada após o prazo, mas antes de qualquer procedimento de ofício\".\n- Pagamento em atraso (Lei 9.430/1996, art. 61): \"multa de mora, calculada à taxa de trinta e três centésimos por cento, por dia de atraso\"; § 1º: \"a partir do primeiro dia subseqüente ao do vencimento\"; § 2º: \"limitado a vinte por cento\"; § 3º: \"juros de mora calculados à taxa a que se refere o § 3º do art. 5º [Selic], a partir do primeiro dia do mês subseqüente ao vencimento do prazo até o mês anterior ao do pagamento e de um por cento no mês de pagamento\".\n- O PGDAS-D e o DAS de setembro de 2026 vencem em 20/10/2026.\n\nOnde fica o escritório contábil (LC 123, art. 18, § 5º-B): \"serão tributadas na forma do Anexo III desta Lei Complementar as seguintes atividades de prestação de serviços: [...] XIV - escritórios de serviços contábeis\". O inciso XIV não está na lista do § 5º-M (os do § 5º-B que vão ao Anexo V com folha abaixo de 28% são só os incisos XVI, XVIII, XIX, XX e XXI).",
      counts: ["Linhas certas (de 4)"],
      after: "As dez contas (anexo, faixa, nominal, parcela a deduzir, efetiva): 1, comércio de calçados, R$ 180.000,00: I, 1ª, 4,00%, 0, 4,00%. 2, materiais elétricos, R$ 1.250.000,00: I, 4ª, 10,70%, 22.500,00, 8,90%. 3, móveis, R$ 420.000,00: II, 3ª, 10,00%, 13.860,00, 6,70%. 4, manutenção de máquinas, R$ 500.000,00: III (§ 5º-B, IX), 3ª, 13,50%, 17.640,00, 9,972%. 5, engenharia, R$ 900.000,00, fator R 27,8%: V, 4ª, 20,50%, 17.100,00, 18,60%. 6, engenharia, R$ 900.000,00, fator R 28,3%: III, 4ª, 16,00%, 35.640,00, 12,04%. 7, escritório contábil, R$ 300.000,00: III, sem fator R (§ 5º-B, XIV), 2ª, 11,20%, 9.360,00, 8,08%. 8, limpeza, R$ 2.400.000,00: IV (§ 5º-C, VI), CPP fora do DAS, 5ª, 22,00%, 183.780,00, 14,34%. 9, consultoria, R$ 600.000,00, fator R 29,6% com pró-labore e FGTS: III, 3ª, 13,50%, 17.640,00, 10,56%. 10, software, R$ 3.000.000,00, fator R 30%: III, 5ª, 21,00%, 125.640,00, 16,812%. Erro previsível no 9: tirar o pró-labore (21,6%) e ir ao Anexo V. Erro do teste no 7: Anexo V pelo fator R, 16,50%. No teste, com este pedido, as quatro linhas certas nas 3 respostas." },
    { id: "e07b", chap: "Capítulo 7", title: "As duas multas, à mão",
      text: "Noutro dia, mais 15 minutos. Na mesma conversa do treino anterior, mande a pergunta das duas multas, em Modelos. Refaça à mão a multa do PGDAS-D e a do DAS, com a página da Receita sobre os juros aberta.",
      counts: ["Multa do PGDAS-D certa (1 = sim)", "Multa e juros do DAS certos (1 = sim)"],
      after: "O PGDAS-D e o DAS de setembro de 2026 venceram em 20/10/2026 (terça). PGDAS-D entregue em 22/10: 2% ao mês-calendário ou fração desde 21/10, uma fração; à metade antes de procedimento de ofício, 1% dos tributos declarados; o mínimo de R$ 50,00 fica, porque o § 3º começa por \"Observado o disposto no § 2º\". DAS pago em 24/10: multa de mora de 0,33% × 4 dias (21 a 24) = 1,32%; juros, nenhum, porque o pagamento caiu no mês do vencimento. Pago em 22/10: 0,66%, sem juros. O mesmo DAS pago em 05/11: 16 dias de mora, 5,28%, e 1% de juros, o do mês do pagamento, sem Selic. Num DAS de exemplo de R$ 3.000,00: multa do PGDAS-D de R$ 50,00 (1% daria R$ 30,00); pago em 24/10, R$ 39,60 de mora e nenhum juro; pago em 05/11, R$ 158,40 de mora e R$ 30,00 de juros. No teste, com o pedido do capítulo: o mínimo de R$ 50,00 nas 3; o DAS sem juros, como a Receita orienta, em 2 de 3." },
    { id: "e07s", chap: "Capítulo 7", title: "Versão sem IA: o anexo do escritório contábil",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, \"Qual o anexo e a alíquota efetiva do Simples de cada cliente abaixo?\", em 9 de outubro de 2026, com a pergunta das duas multas. Marque o escritório contábil no Anexo V, o DAS que \"não é dia 20\" e a multa que sumiu.",
      material: "IA:\n# Simples Nacional — Enquadramento e Alíquota Efetiva (PA Setembro/2026)\n\n## Fórmula geral\n\n$$\\text{Alíquota efetiva} = \\frac{(\\text{RBT12} \\times \\text{Alíquota nominal}) - \\text{Dedução}}{\\text{RBT12}}$$\n\n> Para as atividades sujeitas ao **fator \"r\"** (§ 5º-I do art. 18 da LC 123/2006):\n> - **r = Folha 12 meses ÷ RBT12**\n> - r **≥ 28 %** → **Anexo III**\n> - r **< 28 %** → **Anexo V**\n\n---\n\n## Clientes 1 e 2 — Comércio (Anexo I)\n\n| Faixa | RBT12 | Alíq. nominal | Dedução |\n|-------|-------|--------------|---------|\n| 1ª | Até R$ 180.000 | 4,00 % | — |\n| 4ª | R$ 720.000,01 a R$ 1.800.000 | 10,70 % | R$ 22.500,00 |\n\n**Cliente 1 — Comércio de calçados · RBT12 R$ 180.000**\n→ **Anexo I · 1ª faixa**\n$$\\frac{180.000 \\times 4\\% - 0}{180.000} = \\textbf{4,00\\%}$$\n\n**Cliente 2 — Comércio de materiais elétricos · RBT12 R$ 1.250.000**\n→ **Anexo I · 4ª faixa**\n$$\\frac{1.250.000 \\times 10,70\\% - 22.500}{1.250.000} = \\frac{111.250}{1.250.000} = \\textbf{8,90\\%}$$\n\n---\n\n## Cliente 3 — Indústria (Anexo II)\n\n| Faixa | RBT12 | Alíq. nominal | Dedução |\n|-------|-------|--------------|---------|\n| 3ª | R$ 360.000,01 a R$ 720.000 | 10,00 % | R$ 13.860,00 |\n\n**Fabricação de móveis · RBT12 R$ 420.000**\n→ **Anexo II · 3ª faixa**\n$$\\frac{420.000 \\times 10\\% - 13.860}{420.000} = \\frac{28.140}{420.000} = \\textbf{6,70\\%}$$\n\n---\n\n## Clientes 4, 6, 9 e 10 — Serviços gerais / fator r ≥ 28 % (Anexo III)\n\n| Faixa | RBT12 | Alíq. nominal | Dedução |\n|-------|-------|--------------|---------|\n| 3ª | R$ 360.000,01 a R$ 720.000 | 13,50 % | R$ 17.640,00 |\n| 4ª | R$ 720.000,01 a R$ 1.800.000 | 16,00 % | R$ 35.640,00 |\n| 5ª | R$ 1.800.000,01 a R$ 3.600.000 | 21,00 % | R$ 125.640,00 |\n\n**Cliente 4 — Manutenção e reparo de máquinas industriais · RBT12 R$ 500.000**\n*(atividade de reparo/manutenção → Anexo III direto, sem fator r)*\n→ **Anexo III · 3ª faixa**\n$$\\frac{500.000 \\times 13,50\\% - 17.640}{500.000} = \\frac{49.860}{500.000} = \\textbf{9,97\\%}$$\n\n---\n\n**Cliente 6 — Engenharia · RBT12 R$ 900.000 · Folha R$ 254.700**\n$$r = \\frac{254.700}{900.000} = 28{,}30\\% \\geq 28\\% \\Rightarrow \\textbf{Anexo III}$$\n→ **Anexo III · 4ª faixa**\n$$\\frac{900.000 \\times 16\\% - 35.640}{900.000} = \\frac{108.360}{900.000} = \\textbf{12,04\\%}$$\n\n---\n\n**Cliente 9 — Consultoria em gestão · RBT12 R$ 600.000**\nFolha: R$ 120.000 + R$ 48.000 + R$ 9.600 = **R$ 177.600**\n$$r = \\frac{177.600}{600.000} = 29{,}60\\% \\geq 28\\% \\Rightarrow \\textbf{Anexo III}$$\n→ **Anexo III · 3ª faixa**\n$$\\frac{600.000 \\times 13,50\\% - 17.640}{600.000} = \\frac{63.360}{600.000} = \\textbf{10,56\\%}$$\n\n---\n\n**Cliente 10 — Desenvolvimento de software sob encomenda · RBT12 R$ 3.000.000 · Folha R$ 900.000**\n$$r = \\frac{900.000}{3.000.000} = 30{,}00\\% \\geq 28\\% \\Rightarrow \\textbf{Anexo III}$$\n→ **Anexo III · 5ª faixa**\n$$\\frac{3.000.000 \\times 21\\% - 125.640}{3.000.000} = \\frac{504.360}{3.000.000} = \\textbf{16,81\\%}$$\n\n---\n\n## Clientes 5 e 7 — Fator r < 28 % (Anexo V)\n\n| Faixa | RBT12 | Alíq. nominal | Dedução |\n|-------|-------|--------------|---------|\n| 2ª | R$ 180.000,01 a R$ 360.000 | 18,00 % | R$ 4.500,00 |\n| 4ª | R$ 720.000,01 a R$ 1.800.000 | 20,50 % | R$ 17.100,00 |\n\n**Cliente 5 — Engenharia · RBT12 R$ 900.000 · Folha R$ 250.200**\n$$r = \\frac{250.200}{900.000} = 27{,}80\\% < 28\\% \\Rightarrow \\textbf{Anexo V}$$\n→ **Anexo V · 4ª faixa**\n$$\\frac{900.000 \\times 20,50\\% - 17.100}{900.000} = \\frac{167.400}{900.000} = \\textbf{18,60\\%}$$\n\n> **Atenção — clientes 5 e 6:** mesma atividade, mesmo RBT12; a diferença de apenas **R$ 4.500 na folha** (R$ 250.200 × R$ 254.700) cruza o limiar de 28 % e provoca uma diferença de **6,56 p.p.** na alíquota efetiva. Vale revisar folha/pró-labore no planejamento tributário.\n\n---\n\n**Cliente 7 — Serviços contábeis · RBT12 R$ 300.000 · Folha R$ 45.000**\n$$r = \\frac{45.000}{300.000} = 15{,}00\\% < 28\\% \\Rightarrow \\textbf{Anexo V}$$\n→ **Anexo V · 2ª faixa**\n$$\\frac{300.000 \\times 18\\% - 4.500}{300.000} = \\frac{49.500}{300.000} = \\textbf{16,50\\%}$$\n\n---\n\n## Cliente 8 — Limpeza e conservação (Anexo IV)\n\n| Faixa | RBT12 | Alíq. nominal | Dedução |\n|-------|-------|--------------|---------|\n| 5ª | R$ 1.800.000,01 a R$ 3.600.000 | 22,00 % | R$ 183.780,00 |\n\n**RBT12 R$ 2.400.000**\n→ **Anexo IV · 5ª faixa**\n$$\\frac{2.400.000 \\times 22\\% - 183.780}{2.400.000} = \\frac{344.220}{2.400.000} = \\textbf{14,34\\%}$$\n\n> **Atenção — Anexo IV:** a CPP (contribuição previdenciária patronal) **não está incluída** no DAS e deve ser recolhida separadamente via GPS.\n\n---\n\n## Quadro-resumo\n\n| # | Atividade | RBT12 | Fator r | Anexo | Faixa | **Alíq. efetiva** |\n|---|-----------|------:|:-------:|:-----:|:-----:|:-----------------:|\n| 1 | Comércio de calçados | R$ 180.000 | — | I | 1ª | **4,00 %** |\n| 2 | Comércio de mat. elétricos | R$ 1.250.000 | — | I | 4ª | **8,90 %** |\n| 3 | Fabricação de móveis | R$ 420.000 | — | II | 3ª | **6,70 %** |\n| 4 | Manut./reparo máq. industriais | R$ 500.000 | — | III | 3ª | **9,97 %** |\n| 5 | Engenharia (folha R$ 250.200) | R$ 900.000 | 27,80 % | **V** | 4ª | **18,60 %** |\n| 6 | Engenharia (folha R$ 254.700) | R$ 900.000 | 28,30 % | **III** | 4ª | **12,04 %** |\n| 7 | Serviços contábeis | R$ 300.000 | 15,00 % | **V** | 2ª | **16,50 %** |\n| 8 | Limpeza e conservação | R$ 2.400.000 | — | **IV** ¹ | 5ª | **14,34 %** |\n| 9 | Consultoria em gestão | R$ 600.000 | 29,60 % | **III** | 3ª | **10,56 %** |\n| 10 | Desenvolvimento de software | R$ 3.000.000 | 30,00 % | **III** | 5ª | **16,81 %** |\n\n¹ CPP recolhida separadamente (fora do DAS).\n\nVocê:\nDuas dúvidas sobre setembro: se eu entregar o PGDAS-D de setembro no dia 22, qual a multa? E se eu pagar o DAS dois dias depois?\n\nIA:\n## Prazo de vencimento — PA Setembro/2026\n\nAntes de calcular qualquer multa, é preciso fixar o **prazo legal**.\n\nPela Resolução CGSN nº 140/2018 (art. 21), o DAS e a transmissão do PGDAS-D vencem no:\n\n> **último dia útil do mês subsequente ao PA**\n\nVerificando outubro/2026:\n- Dia 31/10/2026 → **sábado**\n- Logo, o vencimento recua para → **sexta-feira, 30/10/2026**\n\n---\n\n## Respostas diretas\n\n| Evento | Data | Situação |\n|---|---|---|\n| Entrega do PGDAS-D | 22/10/2026 | **Dentro do prazo** (8 dias antes do vencimento) |\n| Pagamento do DAS | 24/10/2026 | **Dentro do prazo** (6 dias antes do vencimento) |\n\n> **Multa: nenhuma nas duas situações.** Ambas as datas são anteriores a 30/10/2026.\n\n---\n\n## Atenção — confusão comum\n\nO vencimento **não é dia 20** — essa data se aplica a outros tributos federais (IRPJ/CSLL estimativa, por exemplo). No Simples Nacional é sempre o **último dia útil do mês seguinte** ao PA.\n\n---\n\n## Para referência: como seriam as penalidades se houvesse atraso\n\n### Atraso na entrega do PGDAS-D\n*(art. 37 da Resolução CGSN nº 140/2018)*\n\n| Item | Regra |\n|---|---|\n| Multa | **2% ao mês-calendário** (ou fração) sobre o total dos tributos declarados |\n| Limite | 20% do valor declarado |\n| Mínimo | **R$ 50,00** por mês de referência |\n\n### Atraso no pagamento do DAS\n*(art. 61 da Lei nº 9.430/1996 c/c LC 123/2006)*\n\n| Item | Regra |\n|---|---|\n| Multa de mora | **0,33% por dia** de atraso |\n| Limite da multa | 20% |\n| Juros de mora | **Taxa SELIC** acumulada desde o mês seguinte ao vencimento + **1%** no mês do pagamento |\n\n> As multas acima são as do pagamento **espontâneo** fora do prazo. Se houver autuação fiscal (lançamento de ofício), a multa sobe para **75%** do valor devido (podendo chegar a 150% em caso de sonegação).",
      counts: ["Erros marcados (de 3)"],
      after: "Os três: o escritório contábil no Anexo V, 16,50% (é III, sem fator R, 8,08%); \"Multa: nenhuma nas duas situações.\", a multa de mora que sumiu; e o DAS que \"não é dia 20\". Os juros zero desta resposta não se marcam: no mês do vencimento, zero é o certo." },
    { id: "e08", chap: "Capítulo 8", title: "A folha de setembro",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz a folha dos cinco empregados do teste, com nomes inventados, as tabelas de 2026, as datas e as duas regras. Cole numa conversa nova; depois mande as cinco perguntas, em Modelos.",
      material: "Sou do departamento pessoal de um escritório de contabilidade. Calcula a folha de setembro deste cliente: o INSS e o IRRF de cada empregado e o líquido. Use as tabelas, a convenção, as regras e as datas coladas abaixo. Separe a data de pagar da data de declarar; faça o INSS por faixa e mostre a conta.\n\nCliente: Comercial Tamboril do Sul Ltda. (comércio varejista, Simples Nacional, Anexo I), com movimento. Competência: setembro de 2026. Nenhum empregado tem dependente.\n\n1) Joelma Prates: salário R$ 3.000,00. Fez 10 horas extras com adicional de 50% em setembro (faz horas extras todo mês). Valor da hora normal no sistema: R$ 13,64.\n2) Raimundo Teles: salário R$ 2.200,00. Duas faltas sem justificativa: 16/09 (quarta-feira) e 24/09 (quinta-feira), em semanas diferentes.\n3) Sueli Barcante: salário R$ 2.800,00 + adicional de periculosidade de R$ 840,00 (30%, pelo laudo; valor já calculado pelo sistema).\n4) Diego Arruda: salário R$ 1.621,00.\n5) Tainá Corso: salário R$ 1.621,00.\n\nSetembro de 2026 teve 25 dias úteis e 5 domingos e feriados (contagem da empresa).\n\nConvenção coletiva do cliente (trecho): horas extras com adicional de 50%; divisor 220; nenhuma outra verba mensal obrigatória.\n\nTabela do INSS do empregado, a partir da competência janeiro de 2026 (Portaria Interministerial MPS/MF nº 13/2026, Anexo II), alíquotas progressivas, cada uma só sobre a parte do salário dentro da faixa:\naté 1.621,00: 7,5%\nde 1.621,01 até 2.902,84: 9%\nde 2.902,85 até 4.354,27: 12%\nde 4.354,28 até 8.475,55: 14%\n\nIRRF mensal a partir de janeiro de 2026 (Receita Federal, Tributação de 2026):\naté 2.428,80: isento\nde 2.428,81 até 2.826,65: 7,5%, dedução 182,16\nde 2.826,66 até 3.751,05: 15%, dedução 394,16\nde 3.751,06 até 4.664,68: 22,5%, dedução 675,49\nacima de 4.664,68: 27,5%, dedução 908,73\nDedução por dependente: 189,59. Desconto simplificado mensal: 607,20.\nRedução do imposto mensal (Lei 9.250, art. 3º-A, incluído pela Lei 15.270/2025): rendimentos tributáveis até R$ 5.000,00: redução até R$ 312,89, de modo que o imposto devido seja zero; de R$ 5.000,01 até R$ 7.350,00: R$ 978,62 - (0,133145 x rendimentos tributáveis); acima de R$ 7.350,00: sem redução.\n\nRecorte das datas de outubro de 2026:\n- Salário: até o quinto dia útil do mês subsequente ao vencido (CLT, art. 459, § 1º).\n- eSocial, eventos da folha: até o dia 15 do mês seguinte (Manual de Orientação do eSocial): 15/10/2026.\n- FGTS: até o vigésimo dia de cada mês (Lei 8.036, art. 15): 20/10/2026.\n- Agenda Tributária, 20/10/2026: código 1082, contribuição previdenciária descontada de segurados empregados, período de apuração 09/2026, DARF, declarada na DCTFWeb; código 0561, IRRF trabalho assalariado, DARF, declarado na DCTFWeb.\n- DCTFWeb mensal: até o último dia útil do mês seguinte (IN RFB 2.237, art. 6º, na redação da IN 2.248/2025): 30/10/2026.\n- DSR: na remuneração do repouso semanal entram \"as horas extraordinárias habitualmente prestadas\" (Lei 605/1949, art. 7º, a).\n- Multa da DCTFWeb entregue em atraso: \"2% (dois por cento) ao mês-calendário ou fração, incidente sobre o montante dos tributos informados na DCTFWeb, ainda que integralmente pagos [...] limitada a 20%\" (IN RFB 2.237/2024, art. 11, I); mínimo de \"R$ 200,00 (duzentos reais), no caso de omissão ou de atraso na entrega de declaração sem movimento\" e \"R$ 500,00 (quinhentos reais), nos demais casos\" (§ 3º); os mínimos são \"reduzidos em: I 90% (noventa por cento), para o MEI; e II 50% (cinquenta por cento), para a microempresa ou empresa de pequeno porte optante pelo Simples Nacional\" (§ 5º).",
      counts: ["Empregados com o INSS certo (de 5)", "Perguntas certas (de 5)"],
      after: "O gabarito, com as tabelas de 2026, aceitando até três centavos de diferença. Empregada 1 (R$ 3.000,00 e 10 horas extras habituais a 50%, hora de R$ 13,64): horas extras 204,60; DSR 204,60 ÷ 25 × 5 = 40,92; base 3.245,52; INSS 121,575 + 115,3656 + 41,1216 = R$ 278,06; IRRF pela tabela 50,96 (ou 15,71 pelo simplificado), zero pela redução. Empregado 2 (R$ 2.200,00 e duas faltas sem justificativa em semanas diferentes): dia 73,33; 2 faltas e 2 DSR perdidos = 4 dias, 293,33 de desconto; base 1.906,67; INSS R$ 147,28 ou 147,29; IRRF zero. Empregada 3 (R$ 2.800,00 + R$ 840,00 de periculosidade): base 3.640,00; INSS 121,575 + 115,3656 + 88,4592 = R$ 325,40; IRRF pela tabela 103,03 (ou 60,76), zero pela redução. Empregados 4 e 5 (R$ 1.621,00): INSS R$ 121,58 cada; IRRF zero. Total do INSS descontado: R$ 993,88 a R$ 993,91. As perguntas: salário até 06/10/2026, com o sábado; FGTS e DARF em 20/10; DCTFWeb em 30/10; multa mínima de R$ 250,00; a diferença se procura nos eventos do eSocial. No teste, com este pedido, os 5 e as 5 certos nas 3 respostas." },
    { id: "e08s", chap: "Capítulo 8", title: "Versão sem IA: a tabela de outro ano",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, sem nada colado, de 13 de outubro de 2026, com as cinco perguntas; o começo da primeira mensagem foi copiado do registro da sessão, como diz a nota no topo. Marque a tabela de outro ano, o IRRF cobrado, o DSR fora da base e as datas erradas, com a conta do gabarito acima.",
      material: "IA:\n[Nota de 13/10/2026: o claude -p imprimiu só o fim desta resposta. A resposta bateu no teto de saída (32.000 tokens, quase todos de pensamento) e foi continuada; a primeira parte do texto, abaixo até a linha \"[continuação]\", foi copiada sem mudança do registro da sessão (arquivo .jsonl do claude, mensagem com stop_reason max_tokens).]\n## Folha de Pagamento — Competência 09/2026\n**Comercial Tamboril do Sul Ltda.**\n\n---\n\n> **Tabelas utilizadas:** Meu conhecimento vai até agosto/2025. Apliquei as tabelas abaixo — as mais recentes que possuo com certeza. **Confirme com as portarias vigentes em 2026** (especialmente se o salário mínimo e os limites das faixas foram reajustados).\n\n---\n\n### Tabelas de referência (2025)\n\n**INSS — Tabela Progressiva**\n\n| Faixa | Salário de contribuição | Alíquota |\n|:---:|:---|:---:|\n| 1ª | Até R$ 1.518,00 | 7,5% |\n| 2ª | R$ 1.518,01 – R$ 2.793,88 | 9,0% |\n| 3ª | R$ 2.793,89 – R$ 4.190,83 | 12,0% |\n| 4ª | R$ 4.190,84 – R$ 8.157,41 | 14,0% |\n\nMétodo: aplica-se cada alíquota apenas sobre a parcela do salário dentro da faixa e somam-se os resultados.\n\n**IRRF — Tabela Mensal**\n\n| Base de cálculo | Alíquota | Parcela a deduzir |\n|:---|:---:|:---:|\n| Até R$ 2.259,20 | Isento | — |\n| R$ 2.259,21 – R$ 2.826,65 | 7,5% | R$ 169,44 |\n| R$ 2.826,66 – R$ 3.751,05 | 15,0% | R$ 381,44 |\n| R$ 3.751,06 – R$ 4.664,68 | 22,5% | R$ 662,77 |\n| Acima de R$ 4.664,68 | 27,5% | R$ 896,00 |\n\nBase do IRRF = Bruto − INSS (sem dependentes, sem outras deduções informadas).\n\n---\n\n### Premissas adotadas\n\n| Empregado | Critério |\n|---|---|\n| **Joelma** | HE são habituais (\"todo mês\") → integram a remuneração para INSS e IRRF. Valor da HE = R$ 13,64 × 1,50 = R$ 20,46. |\n| **Raimundo** | Mensalista → divisor 30. Cada falta injustificada gera reflexo no DSR da mesma semana. Faltas em 16/09 (4ª) e 24/09 (5ª), em semanas distintas; os domingos perdidos (20/09 e 27/09) são posteriores a cada falta. Desconto = **4 dias** × (R$ 2.200 ÷ 30). |\n| **Sueli** | Adicional de periculosidade integra o salário-de-contribuição do INSS e a base do IRRF (CLT, art. 193; Decreto 3.048/99, art. 214). |\n\n---\n\n### 1 — Joelma Prates\n\n| Verbas | Valor |\n|:---|---:|\n| Salário-base | R$ 3.000,00 |\n| 10 HE × R$ 13,64 × 1,50 | + R$ 204,60 |\n| **Bruto** | **R$ 3.204,60** |\n\n**INSS:**\n\n| Faixa | Parcela na faixa | Alíq. | Contribuição |\n|:---:|---:|:---:|---:|\n| 1ª | R$ 1.518,00 | 7,5% | R$ 113,85 |\n| 2ª | R$ 1.275,88 ¹ | 9,0% | R$ 114,83 |\n| 3ª | R$ 410,72 ² | 12,0% | R$ 49,29 |\n| **Total** | | | **R$ 277,97** |\n\n¹ R$ 2.793,88 − R$ 1.518,00  ² R$ 3.204,60 − R$ 2.793,88\n\n**IRRF:**\nBase = R$ 3.204,60 − R$ 277,97 = **R$ 2.926,63** → faixa de 15%\nR$ 2.926,63 × 15% − R$ 381,44 = R$ 438,99 − R$ 381,44 = **R$ 57,55**\n\n**Líquido = R$ 3.204,60 − R$ 277,97 − R$ 57,55 = R$ 2.869,08**\n\n---\n\n### 2 — Raimundo Teles\n\n| Verbas | Valor |\n|:---|---:|\n| Salário contratado | R$ 2.200,00 |\n| (−) 2 faltas + 2 DSRs = 4 × (R$ 2.200 ÷ 30) | − R$ 293,33 |\n| **Bruto apurado** | **R$ 1.906,67** |\n\n*(Cálculo exato: 4 × 2.200 / 30 = 8.800 / 30 = R$ 293,33)*\n\n**INSS:**\n\n| Faixa | Parcela na faixa | Alíq. | Contribuição |\n|:---:|---:|:---:|---:|\n| 1ª | R$ 1.518,00 | 7,5% | R$ 113,85 |\n| 2ª | R$ 388,67 ³ | 9,0% | R$ 34,98 |\n| **Total** | | | **R$ 148,83** |\n\n³ R$ 1.906,67 − R$ 1.518,00\n\n**IRRF:**\nBase = R$ 1.906,67 − R$ 148,83 = R$ 1.757,84 → **Isento**\n\n**Líquido = R$ 1.906,67 − R$ 148,83 = R$ 1.757,84**\n\n---\n\n### 3 — Sueli Barcante\n\n| Verbas | Valor |\n|:---|---:|\n| Salário-base | R$ 2.800,00 |\n| Adicional de periculosidade (30%) | + R$ 840,00 |\n| **Bruto** | **R$ 3.640,00** |\n\n**INSS:**\n\n| Faixa | Parcela na faixa | Alíq. | Contribuição |\n|:---:|---:|:---:|---:|\n| 1ª | R$ 1.518,00 | 7,5% | R$ 113,85 |\n| 2ª | R$ 1.275,88 | 9,0% | R$ 114,83 |\n| 3ª | R$ 846,12 ⁴ | 12,0% | R$ 101,53 |\n| **Total** | | | **R$ 330,21** |\n\n⁴ R$ 3.640,00 − R$ 2.793,88\n\n**IRRF:**\nBase = R$ 3.640,00 − R$ 330,21 = **R$ 3.309,79** → faixa de 15%\nR$ 3.309,79 × 15% − R$ 381,44 = R$ 496,47 − R$ 381,44 = **R$ 115,03**\n\n**Líquido = R$ 3.640,00 − R$ 330,21 − R$ 115,03 = R$ 3.194,76**\n\n---\n\n### 4 — Diego Arruda\n\nSalário: R$ 1.621,00\n\n**INSS:**\n\n| Faixa | Parcela na faixa | Alíq. | Contribuição |\n|:---:|---:|:---:|---:|\n| 1ª | R$ 1.518,00 | 7,5% | R$ 113,85 |\n| 2ª | R$ 103,00 ⁵ | 9,0% | R$ 9,27 |\n| **Total** | | | **R$ 123,12** |\n\n⁵ R$ 1.621,00 − R$ 1.518,00\n\n**IRRF:** Base = R$ 1.621,00 − R$ 123,12 = R$ 1.497,88 → **Isento**\n\n**Líquido = R$ 1.621,00 − R$ 123,12 = R$ 1.497,88**\n\n---\n\n### 5 — Tainá Corso\n\nSalário: R$ 1.621,00 — resultados idênticos aos de Diego.\n\n**INSS: R$ 123,12 | IRRF: R$ 0,00 | Líquido: R$ 1.497,88**\n\n---\n\n## Quadro-Resumo\n\n| Funcionário | Bruto | INSS | IRRF | **Líquido** |\n|:---|---:|---:|---:|---:|\n| Joelma Prates | R$ 3.204,60 | R$ 277,97 | R$ 57,55 | **R$ 2.869,08** |\n| Raimundo Teles | R$ 1.906,67 | R$ 148,83 | R$ 0,00 | **R$ 1.757,84** |\n| Sueli Barcante | R$ 3.640,00 | R$ 330,21 | R$ 115,03 | **R$ 3.194,76** |\n| Diego Arruda | R$ 1.621,00 | R$ 123,12 | R$ 0,00 | **R$ 1.497,88** |\n| Tainá Corso | R$ 1.621,00 | R$ 123,12 | R$ 0,00 | **R$ 1.497,88** |\n| **TOTAL** | **R$ 11.993,27** | **R$ 1.003,25** | **R$ 172,58** | **R$ 10.817,44** |\n\n---\n\n### Observações finais\n\n1. **Simples Nacional / Anexo I:** não interfere nos descontos dos empregados. INSS patronal e FGTS do empreg\n[continuação]\nador seguem as regras normais (FGTS = 8% sobre o bruto de cada empregado, custo do empregador, não deduzido do líquido).\n\n2. **Verificar para 2026:** se o salário mínimo foi reajustado, os limites das faixas do INSS mudam proporcionalmente. Verifique a portaria interministerial de janeiro/2026. Verifique também se houve alteração na tabela do IRRF (havia proposta de reforma do IRPF em discussão).\n\n3. **Raimundo — arredondamento:** o desconto foi calculado como 4 × 2.200/30 em operação única (R$ 293,33), evitando erro de arredondamento por dia.\n\n4. **Joelma — HE habitual:** por serem habituais, as horas extras refletem também em férias, 13º e FGTS — itens fora do escopo solicitado, mas que merecem atenção na folha anual.\n\nVocê:\nMais cinco perguntas do cliente:\n1. Até quando eu pago o salário de setembro?\n2. Quando vence o FGTS?\n3. Quando vence o INSS da folha e quando eu entrego a DCTFWeb?\n4. Qual é a multa mínima da DCTFWeb entregue com atraso por uma empresa do Simples com movimento?\n5. Por que a DCTFWeb deu valor diferente da guia que eu paguei?\n\nIA:\n**1 — Prazo de pagamento do salário de setembro**\n\nCLT, art. 459, §1º: até o **5º dia útil do mês seguinte**.\n\nOutubro de 2026: dias úteis = 1ª (qui), 2ª (sex), 5ª (seg), 6ª (ter), **7ª (qua)**.\n→ **Vence em 07/10/2026.**\n\n---\n\n**2 — Vencimento do FGTS**\n\nFGTS de setembro vence até o dia **7 do mês seguinte**. Outubro 7 = quarta-feira, dia útil.\n→ **Vence em 07/10/2026.**\n\n---\n\n**3 — INSS da folha e DCTFWeb**\n\n| Obrigação | Prazo | Data em outubro/2026 |\n|---|---|---|\n| Transmissão da DCTFWeb | Até o dia **15** do mês seguinte | **15/10/2026** (quinta) |\n| Pagamento do DARF-INSS | Até o dia **20** do mês seguinte | **20/10/2026** (terça) |\n\n> **Atenção Simples Nacional:** a DCTFWeb declara apenas o **INSS retido dos empregados** e o **IRRF retido**. O INSS patronal (CPP) da empresa entra no **DAS**, não na DCTFWeb. São obrigações separadas, com o DAS vencendo também no dia 20.\n\n---\n\n**4 — Multa mínima da DCTFWeb entregue com atraso (Simples com movimento)**\n\nA penalidade por entrega em atraso é de **2% ao mês** (ou fração) sobre o valor dos tributos declarados, limitada a 20% — com multa **mínima de R$ 500,00** para pessoa jurídica com movimento (IN RFB 2.005/2021 c/c Lei 9.779/99, art. 7º).\n\n*(Empresa sem movimento: mínimo de R$ 200,00.)*\n\n---\n\n**5 — Por que a DCTFWeb deu valor diferente da guia paga?**\n\nAs causas mais comuns, em ordem de probabilidade:\n\n1. **Está comparando a DCTFWeb com o DAS.** São documentos diferentes: a DCTFWeb abrange INSS retido dos empregados + IRRF retido; o DAS abrange o CPP (patronal) e os demais tributos do Simples. Nunca terão o mesmo valor.\n\n2. **Juros e multa embutidos no DARF.** Se o DARF foi gerado ou pago em atraso, a Selic + multa são acrescentadas automaticamente ao valor a pagar — mas a DCTFWeb declara apenas o **principal**, sem atualização. O valor declarado ≠ valor pago.\n\n3. **Competência errada.** O DARF pode ter sido emitido para competência diferente da que está sendo conferida.\n\n4. **Divergência no eSocial.** Se algum evento foi retificado, enviado fora do prazo ou está inconsistente (verbas, afastamentos, admissões), o eSocial recalcula automaticamente e a DCTFWeb reflete esse novo valor.\n\n5. **Créditos previdenciários.** Salário-maternidade pago pela empresa ou salário-família geram crédito que **reduz** o valor líquido da DCTFWeb — o bruto calculado é maior do que o líquido a pagar.\n\nPara identificar a causa: abra a DCTFWeb no eSocial/eCAC, veja o detalhamento por rubrica e compare com o recibo de pagamento do DARF (código e competência). Isso localiza a divergência em minutos.",
      counts: ["Erros marcados"],
      after: "Os erros: as tabelas de 2025 (a primeira faixa do INSS até R$ 1.518,00; em 2026, até R$ 1.621,00); o INSS errado nos 5; o IRRF cobrado de duas, R$ 172,58 no total; o DSR das horas extras fora da base (bruto de R$ 3.204,60); o FGTS \"dia 7\" (não é: é o dia 20); a DCTFWeb \"Até o dia 15\"; a multa mínima de R$ 500,00 sem a redução do Simples." },
    { id: "e09", chap: "Capítulo 9", title: "As seis perguntas e a rescisão",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz as seis perguntas, as regras inteiras e a data do teste. Cole numa conversa nova; depois mande a rescisão de treino, em Modelos. Se a resposta parar no meio, peça a continuação.",
      material: "Sou do departamento pessoal de um escritório de contabilidade. Os clientes me mandaram estas perguntas. Me ajuda a responder?\n\n1. O empregado novo começa na segunda-feira, dia 9. Até quando eu tenho de registrar no eSocial?\n2. Uma microempresa cliente esqueceu de registrar um empregado. Qual é a multa?\n3. O empregado tem um período aquisitivo vencido há 14 meses e ainda não tirou férias: o que acontece se ele sair de férias no mês que vem?\n4. Paguei as férias um dia antes do início, e não dois. Tenho de pagar em dobro?\n5. Até quando eu pago a primeira parcela do 13º?\n6. A rescisão foi paga no 12º dia depois do fim do contrato. O que acontece?\n\nAs regras, como estão no texto (use só elas; o que não estiver aqui, diga \"conferir\"):\n- Registro: os eventos de admissão vão ao eSocial \"até o final do dia imediatamente anterior ao do início da prestação do serviço pelo empregado admitido\" (Manual de Orientação do eSocial, S-1.3).\n- Empregado sem registro: multa de \"R$ 3.000,00 (três mil reais) por empregado não registrado\"; \"o valor final da multa aplicada será de R$ 800,00 (oitocentos reais) por empregado não registrado, quando se tratar de microempresa ou empresa de pequeno porte\" (CLT, art. 47, caput e § 1º).\n- Férias: concedidas \"nos 12 (doze) meses subseqüentes à data em que o empregado tiver adquirido o direito\" (CLT, art. 134); \"Sempre que as férias forem concedidas após o prazo de que trata o art. 134, o empregador pagará em dobro a respectiva remuneração\" (art. 137); o pagamento será efetuado \"até 2 (dois) dias antes do início do respectivo período\" (art. 145). O STF \"julgou procedente a arguição de descumprimento de preceito fundamental para: (a) declarar a inconstitucionalidade da Súmula 450 do Tribunal Superior do Trabalho; e (b) invalidar decisões judiciais não transitadas em julgado que, amparadas no texto sumular, tenham aplicado a sanção de pagamento em dobro com base no art. 137 da CLT\" (ADPF 501, 2022). Multa administrativa por infração às férias (art. 153), à rescisão (art. 477, § 8º) e ao 13º: R$ 176,03 por empregado (Portaria MTE 1.131/2025, tabela em vigor desde 04/07/2025).\n- 13º: o adiantamento será pago \"Entre os meses de fevereiro e novembro de cada ano\" (Lei 4.749, art. 2º); a 2ª parcela \"até o dia 20 de dezembro\" (art. 1º). A gratificação é de \"1/12 avos da remuneração devida em dezembro, por mês de serviço\"; \"A fração igual ou superior a 15 (quinze) dias de trabalho será havida como mês integral\" (Lei 4.090, art. 1º, §§ 1º e 2º).\n- Rescisão: pagamento \"até dez dias contados a partir do término do contrato\" (CLT, art. 477, § 6º); se não, \"multa de 160 BTN, por trabalhador\" (hoje R$ 176,03, Portaria MTE 1.131/2025) \"bem assim ao pagamento da multa a favor do empregado, em valor equivalente ao seu salário\" (art. 477, § 8º).\n- Aviso prévio: \"30 (trinta) dias aos empregados que contem até 1 (um) ano de serviço na mesma empresa\"; \"Ao aviso prévio previsto neste artigo serão acrescidos 3 (três) dias por ano de serviço prestado na mesma empresa, até o máximo de 60 (sessenta) dias, perfazendo um total de até 90 (noventa) dias\" (Lei 12.506/2011). \"A falta do aviso prévio por parte do empregador dá ao empregado o direito aos salários correspondentes ao prazo do aviso, garantida sempre a integração desse período no seu tempo de serviço\" (CLT, art. 487, § 1º); \"A falta de aviso prévio por parte do empregado dá ao empregador o direito de descontar os salários correspondentes ao prazo respectivo\" (§ 2º).\n- FGTS na dispensa sem justa causa: o empregador deposita \"importância igual a quarenta por cento do montante de todos os depósitos realizados na conta vinculada durante a vigência do contrato de trabalho, atualizados monetariamente e acrescidos dos respectivos juros\" (Lei 8.036, art. 18, § 1º).\nHoje é 09/10/2026. Depois vou mandar uma rescisão: nela, calcule cada verba numa linha e marque o que depende da convenção coletiva.",
      counts: ["Itens certos (de 9: seis perguntas e três da rescisão)"],
      after: "O gabarito: 1, registro até o fim do domingo, dia 8 (MOS S-1.3); 2, R$ 800,00 por empregado na microempresa (CLT, art. 47, § 1º); 3, concessivo vencido, férias em dobro (arts. 134 e 137); 4, pagas um dia antes, sem dobro (Súmula 450 declarada inconstitucional, ADPF 501), com a multa administrativa de R$ 176,03 (art. 153); 5, a 1ª parcela do 13º entre fevereiro e novembro, 30/11 pela letra; 6, rescisão paga no 12º dia: um salário ao empregado e R$ 176,03 (art. 477, §§ 6º e 8º). Na rescisão: aviso de 39 dias pela letra (36 ou 42 são \"não conferível\"); aviso indenizado de R$ 3.120,00; base dos 40% de R$ 9.250,00; multa de R$ 3.700,00 (somar os depósitos sobre as verbas da rescisão também é certo, e a multa sobe junto); no pedido de demissão, sem os 40%. As outras verbas, fora do teste, refeitas à mão: saldo de salário de setembro, R$ 2.400,00; 13º proporcional com a projeção do aviso até 08/11/2026, 10/12, R$ 2.000,00; férias proporcionais de 8/12, R$ 1.600,00, mais o terço, R$ 533,33: R$ 2.133,33. No teste, com este pedido, 9 nas 3 respostas." },
    { id: "e09s", chap: "Capítulo 9", title: "Versão sem IA: o dobro que acabou",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, sem as regras, de 13 de outubro de 2026, com a rescisão. Marque o dobro pela Súmula 450, a multa sem valor e os 40% sem a atualização e os juros, com a conta do gabarito acima.",
      material: "IA:\n# Respostas — Departamento Pessoal\n\n---\n\n## 1. Prazo de registro no eSocial (admissão na segunda-feira, dia 9)\n\nO evento **S-2200** deve ser transmitido até o **dia anterior ao início das atividades** — ou seja, até **domingo, dia 8** (o eSocial funciona 24 h, incluindo fins de semana).\n\n> Alternativa: o evento simplificado **S-2190** pode ser enviado até o próprio dia do início (dia 9), mas deverá ser complementado com o S-2200 posteriormente.\n\n---\n\n## 2. Multa por empregado não registrado (microempresa)\n\nConforme o **art. 47, § 1º da CLT** (redação da Reforma Trabalhista):\n\n| Tipo de empresa | Multa por empregado não registrado |\n|---|---|\n| Empresa em geral | R$ 3.000,00 |\n| **ME / EPP** | **R$ 800,00** |\n\nEm caso de **reincidência**, o valor é acrescido de igual quantia.\n\n---\n\n## 3. Período aquisitivo vencido há 14 meses — férias no mês que vem\n\nO período **concessivo** (12 meses após o término do aquisitivo) **já se esgotou há 2 meses**. A empresa está em mora desde então.\n\nConsequência: as férias **deverão ser pagas em dobro** (art. 137 da CLT), e isso vale independentemente de as férias serem gozadas \"agora\" ou terem sido atrasadas. O direito ao dobro nasce no estouro do período concessivo.\n\n> Além do pagamento em dobro ao empregado, a empresa fica sujeita a autuação pela fiscalização do trabalho.\n\n---\n\n## 4. Pagamento das férias com apenas 1 dia de antecedência — é necessário pagar em dobro?\n\n**Sim.** O art. 145 da CLT exige que o pagamento das férias seja feito **até 2 dias antes** do início do período. O descumprimento desse prazo — mesmo que por apenas 1 dia — gera o direito ao pagamento em dobro, conforme a **Súmula nº 450 do TST**:\n\n> *\"É devido o pagamento em dobro da remuneração de férias, incluído o terço constitucional, com base no art. 137 da CLT, quando, ainda que gozadas na época própria, o empregador tenha descumprido o prazo previsto no art. 145 do mesmo diploma legal.\"*\n\n---\n\n## 5. Prazo para pagamento da 1ª parcela do 13º salário\n\nA **1ª parcela** (adiantamento) deve ser paga até **30 de novembro**.\n\nA **2ª parcela** deve ser paga até **20 de dezembro**.\n\n> O empregado pode solicitar o adiantamento junto com as férias, desde que faça o requerimento com pelo menos **30 dias de antecedência** em relação ao início do gozo (Lei 4.749/1965, art. 2º).\n\n---\n\n## 6. Rescisão paga no 12º dia — consequências\n\nO prazo legal para pagamento das verbas rescisórias é de **10 dias corridos** a contar do término do contrato (art. 477, § 6º da CLT). O pagamento no 12º dia configura **atraso de 2 dias**.\n\nConsequências (art. 477, § 8º da CLT):\n\n- **Multa a favor do empregado** equivalente ao valor de **1 salário mensal** do trabalhador;\n- Sujeição a **autuação administrativa** pelo Ministério do Trabalho.\n\n> A multa é devida pelo simples atraso, independentemente de quantos dias. Não há proporcionalidade: 1 dia ou 10 dias de atraso geram a mesma penalidade.\n\n---\n\nSe precisar de mais detalhes em algum ponto, é só perguntar!\n\nVocê:\nAgora uma rescisão de um cliente (microempresa, comércio, Simples Nacional):\n- Empregado: Gersino Paiva, admitido em 01/03/2023, salário fixo de R$ 2.400,00 desde a admissão.\n- Dispensa sem justa causa, comunicada em 30/09/2026, com aviso prévio indenizado. O salário de setembro ainda não foi pago.\n- Férias: todos os períodos aquisitivos completos já foram gozados e pagos; o período atual começou em 01/03/2026.\n- 13º de 2026: nada pago ainda.\n- FGTS (extrato do FGTS Digital): depósitos de mar. a dez./2023: R$ 1.920,00; de 2024: R$ 2.496,00; de 2025: R$ 2.496,00; de jan. a set./2026: R$ 1.728,00. Total depositado: R$ 8.640,00. Atualização e juros creditados: R$ 610,00. Saque para moradia em maio de 2025: R$ 1.500,00. Saldo hoje: R$ 7.750,00.\n\nCalcula as verbas da rescisão e a multa do FGTS. E se, em vez de ser dispensado, ele tivesse pedido demissão no mesmo dia?\n\nIA:\n[Nota de 13/10/2026: o claude -p imprimiu só o fim desta resposta. A resposta bateu no teto de saída (32.000 tokens, quase todos de pensamento) e foi continuada; a primeira parte do texto, abaixo até a linha \"[continuação]\", foi copiada sem mudança do registro da sessão (arquivo .jsonl do claude, mensagem com stop_reason max_tokens).]\n## Rescisão — Gersino Paiva\n\n---\n\n### Premissas e Aviso Prévio\n\n| Item | Dado |\n|---|---|\n| Admissão | 01/03/2023 |\n| Comunicação da dispensa | 30/09/2026 |\n| Tempo de serviço | 3 anos e 7 meses |\n| Aviso prévio (Lei 12.506/2011) | 30 + (2 anos × 3 dias) = **36 dias** |\n| Fim projetado do contrato | 01/10 + 36 dias = **05/11/2026** |\n\n> Com 3 anos completos de serviço, o aviso prévio indenizado é de 36 dias. O projetar esse prazo adianta a contagem de férias e 13º.\n\n---\n\n### 1 — DISPENSA SEM JUSTA CAUSA\n\n#### Apuração dos meses proporcionais\n\n| Verba | Período contado | Meses |\n|---|---|---|\n| Férias proporcionais | 01/03/2026 a 05/11/2026 → mar/abr/mai/jun/jul/ago/set/out completos; nov. tem só 5 dias (< 15) | **8/12** |\n| 13º proporcional | jan a out/2026 (nov. < 15 dias) | **10/12** |\n\n#### Verbas Rescisórias — Créditos\n\n| Verba | Cálculo | Valor |\n|---|---|---|\n| Saldo de salário (setembro) | R$ 2.400,00 × 30/30 | R$ 2.400,00 |\n| Aviso prévio indenizado (36 dias) | R$ 2.400,00 × 36/30 | R$ 2.880,00 |\n| Férias proporcionais (8/12) | R$ 2.400,00 × 8/12 | R$ 1.600,00 |\n| 1/3 constitucional s/ férias | R$ 1.600,00 ÷ 3 | R$ 533,33 |\n| 13º proporcional (10/12) | R$ 2.400,00 × 10/12 | R$ 2.000,00 |\n| **Total bruto** | | **R$ 9.413,33** |\n\n#### Deduções *(tabela 2025 — atualizar para a vigente em out/26)*\n\n| Dedução | Base de cálculo | Valor |\n|---|---|---|\n| INSS — salário | R$ 2.400,00 (1.518 × 7,5% + 882 × 9%) | R$ 193,23 |\n| INSS — 13º | R$ 2.000,00 (1.518 × 7,5% + 482 × 9%) | R$ 157,23 |\n| IRRF | Ambas as bases ficam abaixo do limite de isenção | R$ 0,00 |\n| **Total deduções** | | **R$ 350,46** |\n\n> O aviso prévio indenizado e as férias proporcionais **não sofrem INSS nem IRRF** (natureza indenizatória — RE 576.967/STF e art. 6º, V, Lei 7.713/88).\n\n#### Líquido a pagar no TRCT: **R$ 9.062,87**\n\n---\n\n#### FGTS na Rescisão\n\n| Item | Valor |\n|---|---|\n| Saldo atual em conta (fornecido) | R$ 7.750,00 |\n| + FGTS s/ aviso prévio indenizado (8% × R$ 2.880) | R$ 230,40 |\n| + FGTS s/ 13º proporcional (8% × R$ 2.000) | R$ 160,00 |\n| = **Saldo após depósitos rescisórios** | **R$ 8.140,40** |\n\n#### Multa rescisória de 40%\n\n| | Valor |\n|---|---|\n| Depósitos históricos (extrato) | R$ 8.640,00 |\n| + FGTS aviso prévio (novo) | R$ 230,40 |\n| + FGTS 13º (novo) | R$ 160,00 |\n| **Base de cálculo da multa** | **R$ 9.030,40** |\n| **Multa 40%** | **R$ 3.612,16** |\n\n> A base é o total de **depósitos realizados**, não o saldo atual — o saque de R$ 1.500 para moradia em maio/2025 **não reduz** a base da multa.\n\n#### Total disponível para saque pelo empregado: **R$ 11.752,56**\n*(R$ 8.140,40 de saldo + R$ 3.612,16 de multa, depositados via GRRF)*\n\n---\n\n### 2 — SE FOSSE PEDIDO DE DEMISSÃO (mesma data, aviso dispensado pelo empregador)\n\nSem aviso prévio indenizado, o contrato encerra em **30/09/2026**, reduzindo os meses proporcionais.\n\n| Verba | Cálculo | Valor |\n|---|---|---|\n| Saldo de salário (setembro) | R$ 2.400,00 | R$ 2.400,00 |\n| Aviso prévio indenizado | Não cabe | — |\n| Férias proporcionais **(7/12)** | R$ 2.400 × 7/12 | R$ 1.400,00 |\n| 1/3 s/ férias | R$ 1.400 ÷ 3 | R$ 466,67 |\n| 13º proporcional **(9/12)** | R$ 2\n[continuação]\n.400 × 9/12 | R$ 1.800,00 |\n| **Total bruto** | | **R$ 6.066,67** |\n\n| Dedução | Base | Valor |\n|---|---|---|\n| INSS — salário | R$ 2.400,00 | R$ 193,23 |\n| INSS — 13º | R$ 1.800,00 (1.518 × 7,5% + 282 × 9%) | R$ 139,23 |\n| IRRF | Abaixo do limite | R$ 0,00 |\n| **Total** | | **R$ 332,46** |\n\n#### Líquido a pagar: **R$ 5.734,21**\n\n**FGTS:** Sem multa de 40%. Conta bloqueada para saque ordinário — o saldo permanece disponível apenas para situações legais específicas (aposentadoria, doença grave, compra de imóvel, etc.).\n\n---\n\n### 3 — COMPARATIVO FINAL\n\n| | Dispensa s/ JC | Pedido de demissão | Diferença |\n|---|---|---|---|\n| Saldo salário | R$ 2.400,00 | R$ 2.400,00 | — |\n| Aviso prévio | R$ 2.880,00 | — | − R$ 2.880,00 |\n| Férias + 1/3 | R$ 2.133,33 | R$ 1.866,67 | − R$ 266,67 |\n| 13º | R$ 2.000,00 | R$ 1.800,00 | − R$ 200,00 |\n| INSS + IRRF | − R$ 350,46 | − R$ 332,46 | + R$ 18,00 |\n| **Líquido TRCT** | **R$ 9.062,87** | **R$ 5.734,21** | **− R$ 3.328,66** |\n| Multa FGTS (40%) | R$ 3.612,16 | — | − R$ 3.612,16 |\n| Saque FGTS | R$ 11.752,56 | Bloqueado | — |\n| **Total recebido à vista** | **R$ 20.815,43** | **R$ 5.734,21** | **− R$ 15.081,22** |\n\n---\n\n### Observações Finais\n\n| # | Ponto |\n|---|---|\n| **Prazo de pagamento** | 10 dias corridos a partir de 30/09/2026 → até **10/10/2026** (CLT, art. 477, §6º) |\n| **Tabelas** | INSS e IRRF calculados com a tabela de 2025; aplicar a tabela vigente em outubro/2026 |\n| **FGTS 2023 — 13º** | O extrato indica R$ 1.920 para mar–dez/2023, sem o depósito do 13º daquele ano (R$ 160 esperados). Verificar se há recolhimento em atraso |\n| **GRRF** | Depositar R$ 390,40 (depósitos rescisórios) + R$ 3.612,16 (multa) = **R$ 4.002,56** via GRRF antes do pagamento do TRCT |",
      counts: ["Erros marcados"],
      after: "Os erros: a alternativa do registro \"até o próprio dia do início\"; o dobro pela Súmula 450, com o texto entre aspas; a autuação administrativa sem valor; os 40% sem a atualização e os juros (base de R$ 9.030,40 e multa de R$ 3.612,16); o INSS pela \"tabela 2025\"; o FGTS \"via GRRF\", guia de antes do FGTS Digital; o aviso de 36 dias, não conferível." },
    { id: "e10", chap: "Capítulo 10", title: "O contrato e o cadastro",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz os 13 itens literais e o modelo de contrato do teste, com 10 dos 13 itens; os nomes e os CNPJ são inventados. Cole numa conversa nova; depois mande o segundo pedido, com o art. 3º, em Modelos, e procure a PEP e o beneficiário final no checklist.",
      material: "Sou de um escritório de contabilidade. Confira este modelo de contrato contra os 13 itens colados abaixo: para cada item, diga em que cláusula está ou escreva \"não está no contrato\". Não acrescente exigência que não esteja nos 13 itens como se fosse da norma.\n\nOs 13 itens mínimos do contrato (Res. CFC 1.590/2020, art. 2º): \"a) identificação das partes contratantes; b) detalhamento dos serviços a serem prestados de forma eventual, habitual ou permanente; c) cláusula que explicite e especifique quais serviços serão executados pelo contratante; d) duração do contrato; e) valor dos honorários profissionais cobrados por cada serviço prestado, eventual, habitual ou permanente; f) prazo de pagamento; g) condições de reajuste dos honorários; h) responsabilidades das partes; i) previsão de aditamento contratual, se necessário; j) obrigatoriedade do fornecimento da Carta de Responsabilidade da Administração; k) cláusula contendo a ciência do contratante relativa à Lei n.º 9.613/1998. l) cláusula rescisória com a fixação de prazo de prévio aviso para o encerramento da relação contratual; m) foro para dirimir os conflitos.\"\n\nCONTRATO DE PRESTAÇÃO DE SERVIÇOS CONTÁBEIS\n\nCláusula 1 – Partes. CONTRATADA: Organização Contábil Pé de Serra Ltda., CNPJ 33.180.746/0001-25, responsável técnico Hélio Damasceno Furtado, CRC fictício 0-000000. CONTRATANTE: Padaria Grão Dourado Ltda., CNPJ 18.904.627/0001-60, representada por sua sócia-administradora Marlene Toscano Vidal, CPF 284.613.957-12.\n\nCláusula 2 – Serviços. A CONTRATADA prestará, de forma permanente: escrituração contábil e fiscal; apuração do Simples Nacional e emissão do DAS; folha de pagamento e eSocial de até 8 empregados; DCTFWeb; elaboração do balanço anual. De forma eventual, quando pedidos: alteração contratual, certidões negativas e declaração de faturamento.\n\nCláusula 3 – O que cabe à CONTRATANTE. Enviar até o dia 5 de cada mês os extratos bancários, as notas fiscais de entrada e de saída e as informações da folha (admissões, faltas, horas extras, afastamentos); guardar os documentos originais; pagar os tributos nas datas das guias.\n\nCláusula 4 – Duração. Prazo indeterminado, a partir de 01/11/2026.\n\nCláusula 5 – Honorários. Serviços permanentes: R$ 1.250,00 por mês. Serviços eventuais: pelos valores da tabela anexa, um por serviço (alteração contratual R$ 600,00; certidões R$ 80,00 cada; declaração de faturamento R$ 120,00).\n\nCláusula 6 – Pagamento. Até o dia 10 de cada mês, por boleto.\n\nCláusula 7 – Reajuste. Anual, em janeiro, pelo IPCA dos doze meses anteriores.\n\nCláusula 8 – Responsabilidades. A CONTRATADA responde pelos erros técnicos dos serviços que executar. A CONTRATANTE responde pela veracidade e pelo prazo dos documentos e informações que enviar; a CONTRATADA não responde por multa decorrente de documento entregue fora do prazo da cláusula 3.\n\nCláusula 9 – Aditamento. Mudança de serviços, de número de empregados ou de valores será feita por termo aditivo assinado pelas partes.\n\nCláusula 10 – Sigilo e dados. As partes manterão sigilo sobre as informações trocadas; a CONTRATADA tratará os dados pessoais dos empregados da CONTRATANTE só para cumprir as obrigações legais da folha.\n\nCláusula 11 – Foro. Fica eleito o foro da comarca de Caruaru (PE).",
      counts: ["Itens que faltam achados (de 3)", "Faltas apontadas que não existem", "PEP e beneficiário final no checklist (de 2)"],
      after: "O gabarito: faltam a Carta de Responsabilidade (j), a ciência da Lei 9.613 (k) e a rescisão com prazo de aviso (l); no checklist, a PEP e o beneficiário final. No teste, as 3 respostas acharam os três, sem falta inventada, e puseram os dois no checklist." },
    { id: "e10s", chap: "Capítulo 10", title: "Versão sem IA: \"Revise este contrato\"",
      text: "Sem IA liberada. " + NO_AI + " É a resposta ao pedido \"Revise este contrato\", sem os 13 itens, em 9 de outubro de 2026, com o checklist do cadastro pedido de primeira. Com a lista dos 13 itens ao lado, em Modelos, marque o que ela não achou e a cláusula que retém documento.",
      material: "IA:\n# Revisão do Contrato de Prestação de Serviços Contábeis\n\n---\n\n## Pontos Positivos\n\n- A divisão entre serviços **permanentes e eventuais** está bem feita e protege o escritório de demandas não remuneradas.\n- A **cláusula 3** é importante e frequentemente omitida: fixar o dia 5 como prazo do cliente cria base sólida para a cláusula 8 (isenção de multa por atraso).\n- A **cláusula 8** delimita bem as responsabilidades de cada parte.\n- Mencionar **LGPD na cláusula 10** é necessário e correto.\n- O **reajuste pelo IPCA** está adequado e é o mais usual no setor.\n\n---\n\n## Problemas Críticos — Corrigir Antes de Usar\n\n### 1. CRC \"Fictício\"\nO número `0-000000` precisa ser substituído pelo CRC real do responsável técnico. Contratos com dados incorretos de identificação profissional podem gerar questionamentos éticos junto ao CRC e são nulos quanto à identificação da parte.\n\n### 2. Contrato com Dados Específicos Sendo Usado como Template\nO documento já contém nome, CNPJ e CPF reais de uma cliente (Padaria Grão Dourado / Marlene Toscano Vidal). Se for um **modelo para novos clientes**, todos esses campos devem virar variáveis em branco — ex.: `[RAZÃO SOCIAL]`, `[CNPJ]`, `[REPRESENTANTE]`, `[CPF]`. Usar um contrato com dados de outro cliente por descuido gera problema sério de LGPD.\n\n### 3. Ausência de Cláusula de Rescisão\nEsta é a lacuna mais grave. O contrato não diz **como e quando pode ser encerrado**. Recomendo incluir:\n\n> *\"Qualquer das partes poderá rescindir este contrato mediante aviso prévio de **30 (trinta) dias** por escrito, sem multa. Na rescisão, a CONTRATADA entregará à CONTRATANTE, no prazo de **15 dias**, os livros, arquivos digitais e documentos sob sua guarda, desde que não haja débito pendente de honorários.\"*\n\nSem essa cláusula, qualquer encerramento pode virar litígio.\n\n### 4. Ausência de Penalidades por Atraso no Pagamento\nA cláusula 6 diz apenas \"até o dia 10, por boleto\". Falta prever o que acontece se o cliente não pagar. Sugestão:\n\n> *\"O atraso no pagamento sujeitará a CONTRATANTE a multa de **2%**, juros de mora de **1% ao mês** e correção pelo IGPM, sem prejuízo da suspensão dos serviços após **30 dias** de inadimplência e rescisão após **60 dias**.\"*\n\n---\n\n## Pontos Importantes — Fortemente Recomendados\n\n### 5. Reajuste em Janeiro: Timing Problemático\nO contrato inicia em **01/11/2026**, e o primeiro reajuste seria em **janeiro/2027** — apenas dois meses depois. Considere incluir que o primeiro reajuste só ocorre após **12 meses** do início da vigência:\n\n> *\"O primeiro reajuste só incidirá após completados 12 (doze) meses de vigência contratual.\"*\n\n### 6. LGPD Precisa de Mais Conteúdo\nA cláusula 10 menciona LGPD mas está incompleta. O escritório atua como **operador** (Art. 5º, VII da Lei 13.709/2020) dos dados dos empregados da cliente. Acrescente:\n\n- Identificação explícita das partes como **controladora** (cliente) e **operador** (escritório);\n- Obrigação de notificação de **incidente de segurança** em até 72 horas;\n- Prazo de **retenção e eliminação** dos dados após o encerramento do contrato.\n\n### 7. Prazo de Entrega do Balanço Anual\nA cláusula 2 prevê \"elaboração do balanço anual\", mas não diz até quando ele será entregue. Inclua algo como: *\"até 31 de março do ano subsequente\"*, o que é padrão para empresas do Simples.\n\n### 8. Proporcionalidade do Prazo do Escritório\nA cláusula 3 obriga o cliente a enviar documentos até o dia 5. Mas não está previsto que, se o cliente atrasar, os **prazos do escritório se estendem proporcionalmente**. Recomendo adicionar:\n\n> *\"O atraso na entrega dos documentos pela CONTRATANTE prorroga os prazos de execução da CONTRATADA pelo mesmo número de dias de atraso.\"*\n\n### 9. Limite de Empregados e Lacuna de Cobertura\nA cláusula 2 limita a folha a **até 8 empregados**, e a cláusula 9 exige aditivo para mudanças. Mas não está previsto o que o escritório faz se o cliente admitir um 9º empregado antes de assinar o aditivo. Sugestão de previsão:\n\n> *\"A prestação de serviços relacionados a empregados que ultrapassem o limite previsto ficará condicionada à formalização de termo aditivo; até sua assinatura, os serviços excedentes poderão ser recusados ou cobrados como eventuais.\"*\n\n---\n\n## Cláusulas Faltantes — Recomendadas\n\n| Lacuna | Por que Incluir |\n|---|---|\n| **Força maior / caso fortuito** | Protege o escritório em situações como quedas de sistemas do governo (e-CAC, eSocial), greves, etc. |\n| **Limitação de responsabilidade** | Mesmo respondendo por erros técnicos, é prudente limitar o valor máximo à indenização a, por exemplo, o total de honorários pagos nos últimos 12 meses. |\n| **Guarda de arquivos digitais** | Definir por quanto tempo o escritório mantém cópias dos arquivos (recomenda-se mínimo de 5 anos, seguindo prazos prescicionais tributários). |\n| **Comunicação oficial** | Definir que notificações e comunicados serão feitos por e-mail com aviso de recebimento, o que facilita provar que o cliente foi comunicado. |\n| **Testemunhas e assinatura digital** | Prever que o contrato pode ser assinado por plataforma digital (DocuSign, ClickSign etc.), com validade pela MP 2.200-2/2001. |\n\n---\n\n## Resumo das Prioridades\n\n```\nURGENTE (bloqueia o uso do contrato)\n├── Corrigir CRC fictício\n├── Transformar dados específicos em campos variáveis\n└── Incluir cláusula de rescisão\n\nIMPORTANTE (risco jurídico e financeiro)\n├── Incluir multa e juros por inadimplência\n├── Prever suspensão de serviços por falta de pagamento\n├── Corrigir timing do primeiro reajuste\n└── Complementar a cláusula de LGPD\n\nRECOMENDADO (boa prática contratual)\n├── Prazo para entrega do balanço\n├── Proporcionalidade de prazo por atraso do cliente\n├── Tratamento do excesso de empregados\n└── Força maior, limitação de responsabilidade, guarda de arquivos\n```\n\n---\n\nSe quiser, posso redigir as cláusulas corrigidas prontas para inserção no contrato.\n\nVocê:\nAgora me monta um checklist do cadastro de um cliente novo.\n\nIA:\n# Checklist de Cadastro de Cliente Novo\n\n---\n\n## 1. Documentação da Empresa\n\n- [ ] Contrato Social ou Estatuto Social (última versão consolidada)\n- [ ] Todas as alterações contratuais registradas\n- [ ] Cartão CNPJ atualizado (emitido há no máximo 30 dias)\n- [ ] Inscrição Estadual — IE (se contribuinte de ICMS)\n- [ ] Inscrição Municipal — IM / Alvará de funcionamento\n- [ ] Certidão de enquadramento no Simples Nacional (ou comprovante do regime tributário atual)\n- [ ] Comprovante de endereço da empresa (conta de luz, água ou telefone)\n- [ ] Certificado Digital e-CNPJ (verificar validade; orientar renovação se < 60 dias)\n\n---\n\n## 2. Documentação dos Sócios e Representante Legal\n\n- [ ] RG e CPF de todos os sócios\n- [ ] Comprovante de endereço de cada sócio\n- [ ] Qualificação de cada sócio: nome completo, estado civil, profissão, e-mail, telefone\n- [ ] Certificado Digital e-CPF do sócio-administrador (se necessário para assinaturas)\n\n---\n\n## 3. Situação Fiscal e Tributária\n\n- [ ] Última DEFIS transmitida (ou última declaração do regime anterior)\n- [ ] Últimas 3 guias DAS pagas (verificar adimplência)\n- [ ] Certidão Negativa de Débitos — CND Federal (Receita + PGFN)\n- [ ] CND Estadual\n- [ ] CND Municipal\n- [ ] CND FGTS (Caixa Econômica)\n- [ ] Verificar se há parcelamentos ativos (Simples, FGTS, outros)\n- [ ] Verificar se há pendências no Domicílio Tributário Eletrônico (DTE / e-CAC)\n\n---\n\n## 4. Informações Contábeis e Fiscais Correntes\n\n- [ ] Balancete ou balanço mais recente (se houver escrituração anterior)\n- [ ] Livro Diário e Livro Razão do exercício em curso (ou SPED ECD, se aplicável)\n- [ ] Notas fiscais de entrada e saída dos últimos 3 meses\n- [ ] Extratos bancários dos últimos 3 meses (todas as contas)\n- [ ] Relação de imobilizado (bens do ativo — equipamentos, veículos, imóveis)\n- [ ] Contratos de financiamento ou leasing ativos\n- [ ] Saldo de empréstimos e dívidas bancárias\n\n---\n\n## 5. Folha de Pagamento e eSocial\n\n- [ ] Número de empregados ativos (confirmar enquadramento no contrato — até 8)\n- [ ] Ficha de registro de cada empregado (CTPS, CPF, PIS/NIT, data de admissão, salário, função, CBO)\n- [ ] Comprovante de cadastro no eSocial (verificar se já há empregador cadastrado)\n- [ ] Últimas 3 folhas de pagamento processadas pelo escritório anterior\n- [ ] Últimas guias FGTS (GFIP ou SEFIP) pagas\n- [ ] Últimas guias GPS (INSS) pagas\n- [ ] Férias: relação de férias vencidas, em curso e a vencer\n- [ ] 13º salário: verificar parcelas já pagas no exercício\n- [ ] Afastamentos ativos (INSS, licença maternidade, etc.)\n- [ ] Acordos coletivos ou convenção coletiva aplicável (verificar categoria e sindicato)\n\n---\n\n## 6. Acesso aos Sistemas\n\n- [ ] Procuração eletrônica no e-CAC outorgada ao escritório (perfil completo)\n- [ ] Credencial de acesso ao Simples Nacional / PGDAS outorgada\n- [ ] Acesso ao portal eSocial vinculado ao escritório\n- [ ] Acesso à Nota Fiscal Eletrônica municipal (NFS-e), se aplicável\n- [ ] Acesso ao SEFAZ estadual (NF-e / CT-e), se aplicável\n- [ ] Login e senha do sistema bancário para download de extratos (ou autorização de acesso via Open Finance)\n- [ ] Cadastro do cliente no software de gestão do escritório\n\n---\n\n## 7. Formalização do Contrato e LGPD\n\n- [ ] Contrato de prestação de serviços assinado (duas vias físicas ou assinatura digital)\n- [ ] Tabela de serviços eventuais (anexo do contrato) assinada junto\n- [ ] Termo de consentimento LGPD assinado pelo representante legal\n- [ ] E-mail e WhatsApp oficial do responsável pelo envio dos documentos mensais\n- [ ] Definição do contato interno do cliente (quem vai enviar documentos todo dia 5)\n- [ ] Orientação ao cliente sobre o processo mensal: o que enviar, como enviar e até quando\n\n---\n\n## 8. Verificações Internas do Escritório\n\n- [ ] Pasta do cliente criada no servidor / nuvem (documentos, contratos, arquivos fiscais)\n- [ ] Cliente incluído no agenda de obrigações acessórias do escritório\n- [ ] Alerta de vencimento do certificado digital do cliente cadastrado\n- [ ] Responsável interno (colaborador do escritório) designado para o cliente\n- [ ] Primeiro contato de boas-vindas enviado ao cliente com orientações do fluxo de trabalho\n\n---\n\n## Observações Práticas\n\n> **Prazo sugerido para conclusão do cadastro:** até 10 dias antes do início da vigência do contrato, para não comprometer as primeiras obrigações.\n\n> **Documentos pendentes:** registrar formalmente o que ainda falta e estipular prazo para o cliente entregar — isso afasta a responsabilidade do escritório por eventuais multas no período de transição.\n\n> **Escritório anterior:** solicitar carta de transferência ou distrato com o contador anterior; em alguns casos é necessário para obter os arquivos digitais (SPED, eSocial, etc.).\n\n---\n\nQuer que eu monte também um modelo de **e-mail de boas-vindas** para enviar ao cliente com as instruções do fluxo mensal?",
      counts: ["Itens que faltam e ela não achou (de 3)", "Cláusulas sugeridas que retêm documento"],
      after: "Ela achou só a rescisão; não achou a Carta nem a Lei 9.613. E sugeriu uma cláusula que entrega os documentos \"desde que não haja débito pendente de honorários\", que é reter documento para cobrar (NBC PG 01, item 5 (l)). No checklist, sem a PEP e o beneficiário final." },
    { id: "e11", chap: "Capítulo 11", title: "As oito perguntas do dono",
      text: "Hoje, 15 minutos. O pedido abaixo traz as oito perguntas do dono da loja e os trechos da lei, com a data do teste. Cole numa conversa nova e marque, em cada resposta, se veio o ano da regra e se veio certa. Confira com atenção a pergunta 4: a opção é em setembro e março.",
      material: "Sou do escritório que faz a contabilidade de uma loja de roupas do Simples Nacional. O dono me mandou estas perguntas. Me ajuda a responder? Responda só com o que está colado abaixo; diga o ano de cada regra; não decida pelo cliente: se a pergunta pede uma decisão, monte a comparação. No § 3º do art. 6º-A, os três incisos estão ligados por \"e\": diga quais deles o cliente cumpre e o que falta conferir. Hoje é 09/10/2026.\n\n1. Sou do Simples. Vou pagar 26,5% de imposto a partir de agora?\n2. Neste ano eu já tenho de recolher a CBS de 0,9%?\n3. O Simples Nacional acabou com a reforma?\n4. Quando eu escolho se recolho o IBS e a CBS por fora do DAS?\n5. Quem compra de mim vai poder tomar crédito do imposto?\n6. Em 2027 o PIS e a Cofins ainda existem?\n7. Quando o ICMS e o ISS acabam?\n8. Vale a pena eu sair do Simples por causa da reforma?\n\nTrechos da lei (como estão no texto):\n- ADCT, art. 125: \"Em 2026, o imposto previsto no art. 156-A será cobrado à alíquota estadual de 0,1% (um décimo por cento), e a contribuição prevista no art. 195, V, ambos da Constituição Federal, será cobrada à alíquota de 0,9% (nove décimos por cento).\" § 4º: \"Durante o período de que trata o caput, os sujeitos passivos que cumprirem as obrigações acessórias relativas aos tributos referidos no caput poderão ser dispensados do seu recolhimento, nos termos de lei complementar.\" (art. 156-A = IBS; art. 195, V = CBS)\n- LC 214/2025, art. 343: em 2026, o IBS \"será cobrado mediante aplicação da alíquota estadual de 0,1%\"; art. 346: em 2026, a CBS \"será cobrada mediante aplicação da alíquota de 0,9%\". Art. 348, III: as alíquotas dos arts. 343 e 346 \"c) não serão aplicadas em relação às operações dos contribuintes optantes pelo Simples Nacional.\" § 1º: \"Fica dispensado o recolhimento do IBS e da CBS relativo aos fatos geradores ocorridos no período indicado no caput em relação aos sujeitos passivos que cumprirem as obrigações acessórias previstas na legislação.\"\n- ADCT, art. 126: \"A partir de 2027: I - serão cobrados: a) a contribuição prevista no art. 195, V [CBS] [...]; II - serão extintas as contribuições previstas no art. 195, I, \"b\", e IV, e a contribuição para o Programa de Integração Social [PIS e Cofins] [...], desde que instituída a contribuição referida na alínea \"a\" do inciso I\". Art. 127: \"Em 2027 e 2028, o imposto previsto no art. 156-A da Constituição Federal será cobrado à alíquota estadual de 0,05% (cinco centésimos por cento) e à alíquota municipal de 0,05%\". Parágrafo único: \"No período referido no caput, a alíquota da contribuição prevista no art. 195, V, da Constituição Federal, será reduzida em 0,1 (um décimo) ponto percentual.\"\n- ADCT, art. 128: \"De 2029 a 2032, as alíquotas dos impostos previstos nos arts. 155, II, e 156, III [ICMS e ISS] [...] serão fixadas nas seguintes proporções [...]: I - 9/10 (nove décimos), em 2029; II - 8/10 (oito décimos), em 2030; III - 7/10 (sete décimos), em 2031; IV - 6/10 (seis décimos), em 2032.\" Art. 129: \"Ficam extintos, a partir de 2033, os impostos previstos nos arts. 155, II, e 156, III, da Constituição Federal.\"\n- LC 214/2025, art. 519: \"Os Anexos I a V da Lei Complementar nº 123, de 14 de dezembro de 2006, passam a vigorar com a redação dos Anexos XVIII a XXII desta Lei Complementar.\" (efeitos a partir de 1º de janeiro de 2027, art. 544, III)\n- LC 123, art. 13, § 9º: \"É facultado ao optante pelo Simples Nacional apurar e recolher o IBS e a CBS de acordo com o regime regular aplicável a esses tributos, hipótese em que as parcelas a eles relativas não serão cobradas pelo regime único.\" § 10: \"A opção a que se refere o § 9º será exercida para os semestres iniciados em janeiro e julho de cada ano, sendo irretratável para cada um desses períodos, devendo ser exercida nos meses de setembro e março imediatamente anteriores a cada semestre, na forma regulamentada pelo CGSN.\" (redação da LC 227/2026)\n- Constituição, art. 146, § 3º, II: \"será permitida a apropriação de créditos dos tributos previstos nos arts. 156-A e 195, V, pelo adquirente não optante pelo regime único de que trata o § 1º de bens materiais ou imateriais, inclusive direitos, e de serviços do optante, em montante equivalente ao cobrado por meio do regime único.\" LC 123, art. 23, § 1º-A (incluído pela LC 227/2026, efeitos a partir de 2027): as pessoas jurídicas não optantes \"terão direito a crédito ao IBS e à CBS incidentes sobre as suas aquisições [...] de microempresa ou empresa de pequeno porte optante pelo Simples Nacional, em montante equivalente ao cobrado por meio desse regime único.\"\n- Lei 9.250/1995, art. 6º-A (incluído pela Lei 15.270/2025): \"A partir do mês de janeiro do ano-calendário de 2026, o pagamento, o creditamento, o emprego ou a entrega de lucros e dividendos por uma mesma pessoa jurídica a uma mesma pessoa física residente no Brasil em montante superior a R$ 50.000,00 (cinquenta mil reais) em um mesmo mês fica sujeito à retenção na fonte do Imposto sobre a Renda das Pessoas Físicas à alíquota de 10% (dez por cento) sobre o total do valor pago, creditado, empregado ou entregue.\" § 3º: \"Não se sujeitam ao Imposto sobre a Renda das Pessoas Físicas de que trata este artigo os lucros e dividendos: I - relativos a resultados apurados até o ano-calendário de 2025; II - cuja distribuição tenha sido aprovada até 31 de dezembro de 2025; e III - exigíveis nos termos da legislação civil ou empresarial, desde que seu pagamento, crédito, emprego ou entrega ocorra nos termos originalmente previstos no ato de aprovação.\"",
      counts: ["Perguntas certas, com o ano (de 8)"],
      after: "O gabarito: 1, 26,5% agora: não; o Simples está fora das alíquotas de teste. 2, CBS de 0,9% neste ano: não. 3, o Simples acabou: não; anexos novos em 2027. 4, a opção por fora do DAS: setembro e março, antes de cada semestre (para o 1º semestre de 2027, até 30/10/2026). 5, quem compra toma crédito: sim, o valor cobrado no DAS, a partir de 2027. 6, PIS e Cofins em 2027: extintos, com a CBS cobrada. 7, ICMS e ISS: 9/10 a 6/10 de 2029 a 2032, extintos em 2033. 8, vale sair: a resposta não decide, monta a comparação." },
    { id: "e11b", chap: "Capítulo 11", title: "As duas perguntas do sócio",
      text: "Noutro dia, mais 15 minutos, na mesma conversa. Mande as perguntas do sócio, em Modelos, e confira os R$ 8.000,00 sobre o total e as três condições do lucro de 2025, lidas juntas.",
      counts: ["Perguntas do sócio certas (de 2)"],
      after: "O gabarito: 9, R$ 80 mil por mês: 10% sobre o total, R$ 8.000,00; 10, o lucro de 2025 fica fora só com os três incisos do § 3º juntos; sem a distribuição aprovada até 31/12/2025, a retenção vale. No teste, com este pedido, as 3 respostas acertaram as 10 perguntas." },
    { id: "e11s", chap: "Capítulo 11", title: "Versão sem IA: o ano errado de cada regra",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, com as perguntas como chegaram e sem a lei, em 9 de outubro de 2026, com as do sócio. Com o que vale em que ano, mais abaixo, marque cada regra do ano errado ou sem a condição da lei.",
      material: "IA:\n# Reforma Tributária e o Simples Nacional — Respostas para seu cliente\n\n---\n\n## 1. Vou pagar 26,5% de imposto a partir de agora?\n\n**Não.** A alíquota de referência de ~26,5% (IBS + CBS somados) é para empresas do **regime geral** (Lucro Real ou Presumido). Enquanto sua loja permanecer no Simples Nacional, o recolhimento continua pelo **DAS**, com as alíquotas do **Anexo I (Comércio)**, que são significativamente menores. O 26,5% simplesmente não se aplica a você.\n\n---\n\n## 2. Neste ano já tenho de recolher a CBS de 0,9%?\n\n**2026 é o \"ano-teste\" da reforma.** A CBS está sendo cobrada a **0,9%** e o IBS a **0,1%**. Porém:\n\n- Para empresas do **regime geral**: pagam CBS/IBS e compensam contra PIS/COFINS e ICMS/ISS — resultado líquido **neutro**\n- Para empresas do **Simples Nacional**: como PIS/COFINS e ICMS já estão embutidos no DAS, existe um **mecanismo de ajuste compensatório** para que o ônus total não aumente\n\nNa prática, os valores passam a ser **destacados na NF-e**, mas o impacto líquido no caixa deve ser neutro. Monitore o PGDAS-D para verificar os ajustes aplicados à sua empresa.\n\n---\n\n## 3. O Simples Nacional acabou com a reforma?\n\n**Não acabou.** A EC 132/2023 preservou expressamente o Simples Nacional. O que muda é apenas a **forma de tratamento do IBS e da CBS** dentro (ou fora) do DAS — não a existência do regime.\n\n---\n\n## 4. Quando eu escolho se recolho o IBS e a CBS por fora do DAS?\n\nA opção é **anual**, feita em **janeiro de cada ano** (assim como outras opções do Simples). Para 2027 — quando CBS entra em plena vigência — a janela será em **janeiro/2027**. Fique atento às portarias do **Comitê Gestor do IBS** com os prazos exatos.\n\n---\n\n## 5. Quem compra de mim vai poder tomar crédito do imposto?\n\nDepende da sua escolha:\n\n| Situação | Crédito para o comprador |\n|---|---|\n| **IBS/CBS dentro do DAS** (padrão) | Apenas **crédito presumido** — valor menor, calculado sobre alíquota reduzida |\n| **IBS/CBS fora do DAS** (opção) | **Crédito integral** do IBS e CBS destacados na NF-e |\n\n> Para uma loja de roupas que vende **principalmente para o consumidor final (B2C)**, isso tem pouco impacto. Se vender também para outras empresas (B2B), o ponto merece atenção.\n\n---\n\n## 6. Em 2027 o PIS e a COFINS ainda existem?\n\n**Não.** PIS e COFINS são **extintos em 1º de janeiro de 2027**, quando a CBS entra em plena vigência. Para o Simples Nacional, as tabelas do DAS serão ajustadas — as parcelas de PIS/COFINS saem e a CBS entra no cálculo.\n\n---\n\n## 7. Quando o ICMS e o ISS acabam?\n\nA extinção é **gradual**:\n\n| Período | O que acontece |\n|---|---|\n| **2027–2028** | ICMS e ISS em vigor normal; IBS ainda em transição |\n| **2029** | IBS = 1/5 da alíquota cheia; ICMS/ISS = 4/5 |\n| **2030** | IBS = 2/5; ICMS/ISS = 3/5 |\n| **2031** | IBS = 3/5; ICMS/ISS = 2/5 |\n| **2032** | IBS = 4/5; ICMS/ISS = 1/5 |\n| **2033** | IBS em plena vigência; **ICMS e ISS extintos** |\n\nOu seja, ainda haverá ICMS por mais alguns anos.\n\n---\n\n## 8. Vale a pena sair do Simples por causa da reforma?\n\nPara uma **loja de roupas vendendo principalmente para consumidor final**, em geral **não compensa sair**. Pontos a considerar:\n\n- As alíquotas do Anexo I do Simples são muito menores que 26,5%\n- Vendendo para consumidor final, o crédito presumido já atende\n- Menos obrigações acessórias no Simples\n- Fora do Simples, entram IRPJ, CSLL e encargos de folha separados — a carga pode **aumentar**\n\n> **Recomendação:** faça uma **simulação com os números reais** da empresa antes de qualquer decisão. O benefício de sair do Simples, se existir, tende a aparecer apenas quando o cliente tem perfil majoritariamente B2B e a conta fecha com créditos maiores do que a economia do Simples.\n\n---\n\nQualquer dúvida mais específica, fico à disposição!\n\nVocê:\nAgora outro cliente, sócio de uma empresa de serviços do lucro presumido, perguntou:\n9. Posso distribuir R$ 80 mil por mês de lucro para mim sem pagar imposto?\n10. O lucro de 2025 que eu ainda não distribuí também paga esses 10%?\n\nIA:\n# Reforma do IR — Distribuição de Lucros no Lucro Presumido\n\n---\n\n## 9. Posso distribuir R$ 80 mil por mês sem pagar imposto?\n\n**Não.** R$ 80.000/mês ultrapassa a faixa de isenção da reforma do IR. O funcionamento é o seguinte:\n\n- A lei estabelece uma **faixa de isenção mensal por beneficiário** — acima dela, incide **IRRF de 10%**, retido pela própria empresa no momento da distribuição\n- R$ 80.000/mês ficará em grande parte dentro da faixa tributável\n\n> **Confirme o valor exato da faixa de isenção na lei vigente** — os debates legislativos giraram em torno de R$ 20.000/mês por beneficiário, mas o número definitivo precisa ser checado no texto aprovado.\n\n**Exemplo prático** (se a faixa isenta for R$ 20.000/mês):\n\n| Valor | Tratamento |\n|---|---|\n| R$ 20.000 | Isento |\n| R$ 60.000 | 10% de IRRF = **R$ 6.000** |\n| **Líquido recebido** | **R$ 74.000** |\n\n**Ponto importante para o Lucro Presumido:**\nAntes mesmo de pensar no IR, a empresa precisa verificar se tem **lucro disponível para distribuição** — calculado sobre o lucro presumido após IRPJ e CSLL, ou sobre o lucro contábil se houver escrituração completa. Distribuição acima desse limite não é dividendo e pode ser tributada como outros rendimentos nas alíquotas progressivas do IRPF.\n\n---\n\n## 10. O lucro de 2025 que eu ainda não distribuí também paga esses 10%?\n\n**Sim.** A regra de transição da reforma **protegeu apenas os lucros acumulados até 31/12/2024**, registrados em reservas de lucros até essa data — esses podiam ser distribuídos dentro de uma janela específica sem o novo IRRF.\n\nOs **lucros de 2025** foram apurados já sob a nova legislação e **não têm essa proteção**. Quando distribuídos em 2026 (ou depois), pagam os 10% sobre o excedente da faixa isenta normalmente.\n\n**Resumo prático:**\n\n| Origem do lucro | Sujeito ao IRRF de 10%? |\n|---|---|\n| Acumulado **até 31/12/2024** (dentro da janela transitória) | **Não** — desde que distribuído no prazo |\n| Apurado em **2025** | **Sim** |\n| Apurado em **2026 em diante** | **Sim** |\n\n> **Ponto de planejamento:** se a empresa ainda tem lucros retidos **pré-2024** sem distribuir, vale verificar **se o prazo da janela transitória ainda está aberto**. Se estiver, pode ser uma oportunidade de distribuir esse saldo sem IRRF antes do vencimento.\n\n---\n\nEm resumo para o cliente: a isenção total sobre dividendos acabou para distribuições relevantes — e o lucro de 2025 não escapa. O planejamento agora passa por **calibrar o valor mensal de distribuição** em torno da faixa isenta e **aproveitar eventuais saldos pré-2024** enquanto o prazo transitório permitir.",
      counts: ["Perguntas certas (de 10)"],
      after: "Pelo gabarito, ela acerta 4 de 10 (1, 3, 6 e 8). Os erros: a CBS \"está sendo cobrada a 0,9%\" com \"ajuste compensatório\" para o Simples; a opção \"em janeiro de cada ano\"; o \"crédito presumido\"; as proporções de 1/5 a 4/5; a \"faixa de isenção\" de R$ 20.000 e R$ 6.000 retidos; e o lucro de 2025 \"Sim\", com a proteção \"apenas\" até 31/12/2024. O \"26,5%\" não conta." },
    { id: "e12", chap: "Capítulo 12", title: "As seis mensagens",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz as seis mensagens do teste, sem link e sem dado, e os sinais oficiais. Cole numa conversa nova; depois mande a pergunta do QR Code e do prazo, em Modelos. Conte, por mensagem, o sinal certo achado e o serviço onde o cliente confere. Conte também os vereditos por conta própria: \"verdadeira\", \"legítima\" ou \"golpe\" que não venha de um sinal da lista colada; \"fraudulento\", dito porque o CNPJ do Pix não é o da lista, repete a regra e não conta.",
      material: "Trabalho num escritório de contabilidade. Os clientes me mandaram estas seis mensagens e cartas (sem os links e sem os dados deles). Para cada uma, diga quais dos sinais oficiais colados abaixo aparecem; não diga se é verdadeira: diga em que serviço oficial o cliente confere (e-CAC, DTE-SN, Meu Imposto de Renda, Portal do Simples), entrando por conta própria, não pelo que veio na mensagem.\n\nMensagem 1 (carta pelo Correio, recebida pela Cliente A):\n\"MINISTÉRIO DA FAZENDA - RECEITA FEDERAL. Prezada contribuinte [nome], CPF [CPF]. Sua Declaração de Ajuste Anual do Imposto sobre a Renda da Pessoa Física 2026, ano-calendário 2025, está retida em malha fiscal. Para saber o motivo da retenção, consulte o serviço Meu Imposto de Renda, no site da Receita Federal ou no aplicativo, com sua conta gov.br nível prata ou ouro. Se houver erro nas informações declaradas, apresente declaração retificadora. Não é preciso comparecer a uma unidade da Receita Federal. Corrigir as informações antes de ser intimado evita multas.\"\n\nMensagem 2 (e-mail recebido pelo Cliente B):\n\"De: Receita Federal do Brasil <notificacao@rfb.gov.br>\nAssunto: Pendência fiscal no CPF [CPF]\nIdentificamos pendência na sua declaração. Regularize em até 48 horas para evitar o bloqueio do CPF: [link retirado]\"\n\nMensagem 3 (carta com guia, recebida pelo Cliente C):\n\"DOCUMENTO DE ARRECADAÇÃO DO SIMPLES NACIONAL - DAS. Período de apuração: 08/2026. Valor: R$ 1.874,32. Pague em até 5 dias para evitar multa de até 225%. Pagamento somente por Pix: [QR Code]. Beneficiário: SN ARRECADACAO DIGITAL LTDA, CNPJ 41.872.305/0001-10.\"\n\nMensagem 4 (WhatsApp recebido pelo Cliente D):\n\"SIMPLES NACIONAL - AVISO: o CNPJ [CNPJ] será SUSPENSO hoje às 18h por débitos em aberto. Regularize agora: [link retirado]\"\n\nMensagem 5 (o Cliente E mandou um print e disse que \"chegou da Receita\"):\n\"TERMO DE EXCLUSÃO DO SIMPLES NACIONAL Nº [número]. Contribuinte: [nome], CNPJ [CNPJ]. Fica o contribuinte ciente de que será excluído do Simples Nacional a partir de 01/01/2027, por possuir débitos com a Receita Federal, conforme o Relatório de Pendências. A exclusão não ocorrerá se a totalidade dos débitos for regularizada no prazo de 90 (noventa) dias contados da ciência deste termo. Contestação: 20 dias úteis da ciência.\"\n\nMensagem 6 (carta recebida pelo Cliente F):\n\"RECEITA FEDERAL - TERMO DE INTIMAÇÃO FISCAL Nº [número]. Fica o contribuinte INTIMADO a regularizar seus dados cadastrais e apresentar o livro-caixa de 2025 no prazo de 20 (vinte) dias, sob pena de multa e inaptidão do CNPJ. Acesse o processo em [link retirado] com o código [código].\"\n\nOs sinais oficiais (com a fonte e a data):\n- \"A Receita Federal não envia e-mails com links ou solicita direcionamento para páginas não oficiais.\" Criminosos já enviaram mensagens que escondem o remetente verdadeiro e mostram \"um endereço de e-mail legítimo da Receita Federal\" (notícia da Receita, 23/04/2025).\n- \"Receita Federal não utiliza SMS nem WhatsApp em seus procedimentos de cobrança de débitos.\" (Receita Federal)\n- Pix do DAS: \"verificar se o destino do pagamento que consta na prévia do PIX é o CNPJ 00.394.460/0058-87. Qualquer outro é fraudulento.\" \"O domínio de acesso ao serviço deve conter receita.fazenda.gov.br no link.\" (Portal do Simples Nacional, 30/07/2024). Já houve guia falsa do Simples em que o Pix era a \"única opção no documento falso\", com \"ameaça de multa altíssima de até 225%\" (Portal do Simples Nacional, 16/03/2022).\n- Termo de exclusão do Simples: os termos são disponibilizados no \"Domicílio Tributário Eletrônico do Simples Nacional e MEI (DTE-SN)\" e podem ser acessados \"pelo Portal do Simples Nacional, por meio do DTE-SN, ou pelo Portal e-CAC\"; o contribuinte tem \"90 dias da data de ciência do Termo de Exclusão para regularizar seus débitos\" (Portal do Simples Nacional, 2026).\n- Malha do IRPF: a pendência se consulta no serviço \"Meu Imposto de Renda\", com conta gov.br prata ou ouro (Receita, Projeto Cartas 2026).\n- Cartas falsas de \"Intimação para regularização de dados cadastrais\", com o logotipo da Receita, levam a site falso; \"O atendimento está disponível por meio do e-CAC\" (notícia da Receita, 11/03/2025).",
      counts: ["Mensagens com o serviço onde conferir (de 6)", "Vereditos por conta própria", "Prazos ou multas fora do material"],
      after: "O gabarito, mensagem por mensagem (o sinal; onde o cliente confere). M1, a carta da malha: nenhum sinal de golpe na lista; o Meu Imposto de Renda, com a conta gov.br prata ou ouro; a carta não dá prazo. M2, o e-mail com link: a Receita \"não envia e-mails com links\", e o remetente já foi falsificado; o e-CAC. M3, a guia do Simples: o CNPJ do Pix não é o 00.394.460/0058-87, o Pix é a única opção, a multa \"de até 225%\"; gera-se o DAS no Portal do Simples e confere-se o CNPJ na prévia do Pix; QR Code da guia, não. M4, o WhatsApp de \"CNPJ suspenso hoje\": o canal e o prazo de horas; o Portal do Simples ou o e-CAC; o termo verdadeiro chega pelo DTE-SN, com 90 dias. M5, o termo de exclusão por print: a caixa postal do DTE-SN, pelo Portal do Simples ou pelo e-CAC; 90 dias da ciência para regularizar, 20 dias úteis para contestar. M6, a intimação por carta com site e código: as cartas falsas de \"Intimação para regularização de dados cadastrais\"; o e-CAC. No teste, com este pedido: o serviço nas 18 mensagens, nenhum veredito, e 1 prazo e 1 multa fora do material." },
    { id: "e12s", chap: "Capítulo 12", title: "Versão sem IA: o veredito que ela não tinha como dar",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, \"Quais são verdadeiras e o que cada cliente deve fazer?\", em 9 de outubro de 2026, com a pergunta do QR Code e do prazo. Os nomes, os CPF, os CNPJ dos clientes, o telefone e os links do material inventado foram trocados por [Cliente A] a [Cliente F], [CPF], [CNPJ], [telefone] e [link retirado]; o resto é o texto da IA. Com a lista dos sinais ao lado, marque os três pontos.",
      material: "IA:\n# Análise das Seis Comunicações\n\n---\n\n## MENSAGEM 1 — [Cliente A] (Carta pelos Correios)\n### **LEGÍTIMA**\n\n**Por quê é verdadeira:**\n- A Receita Federal envia cartas físicas sobre retenção em malha fiscal\n- As orientações são precisamente as que constam nos procedimentos oficiais da RF: consultar pelo \"Meu Imposto de Renda\", usar conta gov.br prata/ouro, retificar se houver erro\n- Não há link suspeito, não exige pagamento, não cria urgência artificial\n\n**O que [Cliente A] deve fazer:**\n1. Acessar **receita.economia.gov.br** (ou o app \"Meu Imposto de Renda\") com conta gov.br nível prata ou ouro\n2. Identificar o motivo da retenção\n3. Se houver erro, apresentar **declaração retificadora** pelo programa da DIRPF\n4. Trazer os documentos de suporte ao escritório para análise antes de retificar\n\n---\n\n## MENSAGEM 2 — [Cliente B] (E-mail)\n### **GOLPE — PHISHING**\n\n**Por quê é falsa:**\n- A Receita Federal **não envia e-mails com links** para regularização de CPF\n- O domínio do link (`[link retirado]`) **não é gov.br** — todo site oficial do governo federal termina em `.gov.br`\n- O prazo de \"48 horas para bloquear o CPF\" é tática clássica de urgência para forçar um clique impulsivo\n- O endereço do remetente pode ser facilmente falsificado (*spoofed*)\n\n**O que [Cliente B] deve fazer:**\n1. **Não clicar no link e não fornecer nenhum dado**\n2. Deletar o e-mail\n3. Se quiser confirmar que não há pendências reais, acessar o **e-CAC** diretamente em `eCAC.receita.fazenda.gov.br` ou consultar a situação do CPF em `receita.economia.gov.br`\n4. Registrar um boletim de ocorrência se desejar\n\n---\n\n## MENSAGEM 3 — [Cliente C] (Carta com guia DAS)\n### **GOLPE — DAS FALSO**\n\n**Por quê é falsa:**\n- O **DAS legítimo** é gerado exclusivamente pelo PGMEI ou Portal do Simples Nacional (`www8.receita.fazenda.gov.br/SimplesNacional`) e o pagamento é feito em bancos credenciados à rede arrecadadora do governo federal\n- **Jamais o beneficiário de um DAS é uma empresa privada** — o crédito vai ao Tesouro Nacional/Simples Nacional, não a \"SN ARRECADACAO DIGITAL LTDA\" (CNPJ privado)\n- Pagamento exclusivo via Pix para CNPJ privado é sinal inequívoco de fraude\n- A multa de \"225%\" é exagerada e inventada para gerar pânico\n\n**O que a [Cliente C] deve fazer:**\n1. **Não pagar o Pix**\n2. Gerar o DAS correto do período 08/2026 diretamente pelo **Portal do Simples Nacional** ou no escritório\n3. Guardar a carta falsa como evidência\n4. Registrar boletim de ocorrência\n\n---\n\n## MENSAGEM 4 — [Cliente D] (WhatsApp)\n### **GOLPE — MENSAGEM FALSA**\n\n**Por quê é falsa:**\n- A Receita Federal e o Simples Nacional **nunca notificam por WhatsApp**\n- O número `[telefone]` não é canal oficial de nenhum órgão público\n- O domínio do link (`[link retirado]`) **não é gov.br**\n- \"Suspenso hoje às 18h\" é urgência artificial, tática de golpe\n\n**O que o [Cliente D] deve fazer:**\n1. **Não clicar no link**\n2. Bloquear e reportar o número\n3. Verificar a real situação do CNPJ no **Portal do Simples Nacional** (`www8.receita.fazenda.gov.br/SimplesNacional`) ou no **e-CAC**\n4. Se houver débitos reais, o escritório orienta a regularização pelo canal correto\n\n---\n\n## MENSAGEM 5 — [Cliente E] (Print/Screenshot)\n### **CONTEÚDO APARENTEMENTE LEGÍTIMO — VERIFICAR OBRIGATORIAMENTE**\n\n**Por quê parece verdadeiro:**\n- O Termo de Exclusão do Simples Nacional é um ato real e previsto na LC 123/2006\n- Os prazos descritos (90 dias para regularizar débitos, 20 dias úteis para contestar) são **exatamente os previstos na legislação**\n- A numeração e a estrutura são compatíveis com os termos reais emitidos pela RF\n- **Não há link suspeito nem pedido de pagamento** no texto\n\n**Por que exige verificação:**\n- Chegou como *print* (screenshot), não pelo canal oficial (DTE — Domicílio Tributário Eletrônico, acessado pelo e-CAC)\n- Screenshots podem ser adulterados\n\n**O que a [Cliente E] deve fazer:**\n1. Acessar imediatamente o **e-CAC** (`eCAC.receita.fazenda.gov.br`) e verificar a **Caixa Postal** e o **Relatório de Pendências do Simples Nacional**\n2. Verificar também no **Portal do Simples Nacional** se há termo de exclusão registrado\n3. Trazer ao escritório **com urgência** — o prazo de 90 dias começa a contar da ciência\n4. Se confirmado, levantar todos os débitos e avaliar parcelamento ou pagamento integral dentro do prazo\n\n---\n\n## MENSAGEM 6 — [Cliente F] (Carta)\n### **GOLPE — INTIMAÇÃO FALSA**\n\n**Por quê é falsa:**\n- O domínio `[link retirado]` **não é gov.br** — intimações fiscais reais são acessadas pelo **e-CAC**, com domínio oficial\n- A Receita Federal não direciona contribuintes a sites de terceiros com \"códigos de acesso\"\n- O texto mistura ameaças reais (multa, inaptidão de CNPJ) com instruções falsas para criar credibilidade\n\n**O que a [Cliente F] deve fazer:**\n1. **Não acessar o site indicado**\n2. Verificar se há intimações reais acessando o **e-CAC** diretamente (`eCAC.receita.fazenda.gov.br`) → Caixa Postal / Processos\n3. Verificar a situação cadastral do CNPJ em `servicos.receita.fazenda.gov.br/Servicos/cnpjreva`\n4. Se houver pendências reais, o escritório pode assessorar no atendimento correto\n\n---\n\n## Resumo Executivo\n\n| # | Cliente | Canal | Situação | Ação Imediata |\n|---|---------|-------|----------|---------------|\n| 1 | [Cliente A] | Carta Correios | **Legítima** | Consultar e-CAC / retificar declaração |\n| 2 | [Cliente B] | E-mail | **Golpe** | Não clicar; deletar |\n| 3 | [Cliente C] | Carta + guia | **Golpe** | Não pagar; gerar DAS real |\n| 4 | [Cliente D] | WhatsApp | **Golpe** | Não clicar; verificar no portal oficial |\n| 5 | [Cliente E] | Screenshot | **Verificar** | Confirmar no e-CAC com urgência |\n| 6 | [Cliente F] | Carta | **Golpe** | Não acessar o site; verificar e-CAC |\n\n> **Regra de ouro para seus clientes:** Qualquer comunicação do governo federal — Receita Federal, Simples Nacional, PGFN — que exija ação urgente, contenha link fora do domínio `.gov.br` ou peça pagamento via Pix para beneficiário privado é **golpe**. A verificação segura é sempre pelo **e-CAC** ou **Portal do Simples Nacional**, acessando o endereço digitado diretamente no navegador.\n\nVocê:\nO cliente da guia do Simples (mensagem 3) perguntou se pode pagar pelo QR Code da própria guia, que é mais rápido. E a cliente da carta do imposto de renda (mensagem 1) quer saber até quando ela tem de responder. O que eu digo a cada um?\n\nIA:\n## [Cliente C] — QR Code da guia falsa\n\n**Diga que não, em hipótese alguma.**\n\nO QR Code impresso naquela carta não aponta para o governo — aponta para a conta da empresa fraudulenta (\"SN ARRECADACAO DIGITAL LTDA\"). Pagar por ele seria transferir R$ 1.874,32 diretamente para o golpista. O DAS real continuaria em aberto, e a empresa estaria com o dinheiro perdido **e** ainda devendo o imposto.\n\nO caminho correto, sem exceção, é:\n1. Acessar o **Portal do Simples Nacional** (`www8.receita.fazenda.gov.br/SimplesNacional`) ou o **PGMEI** (se for MEI)\n2. Gerar o DAS legítimo do período 08/2026 diretamente pelo sistema\n3. Pagar esse DAS gerado pelo portal — aí sim pode ser por Pix, boleto ou débito bancário, pois o beneficiário será o correto (Tesouro Nacional)\n\n> **Resumo para o cliente:** \"O QR Code dessa carta paga o golpista, não a Receita. Jogue a carta fora e a gente gera a guia certa para você pagar.\"\n\n---\n\n## [Cliente A] — Prazo para responder à malha\n\n**A carta em si não traz um prazo legal — mas isso não significa que ela pode esperar.**\n\nExplique a distinção importante:\n\n| Situação | O que é | Tem prazo? |\n|---|---|---|\n| A carta que ela recebeu | **Aviso de retenção** — a RF informando que a declaração está retida | Não impõe prazo |\n| **Intimação formal** | Ato seguinte, se ela não agir | Geralmente **30 dias** para responder, já com risco de multa |\n\n**O que ela deve fazer agora:**\n1. Verificar o motivo da retenção no **Meu Imposto de Renda** (site ou app, com conta gov.br)\n2. Trazer os documentos ao escritório o quanto antes\n3. Se houver erro na declaração original, apresentar a **retificadora antes de ser intimada** — esse é exatamente o momento em que a RF permite corrigir sem multa\n\n> **Resumo para a cliente:** \"Prazo fixo não tem, mas agir agora é o que evita ter prazo — e multa. Se a Receita mandar uma intimação formal antes de você corrigir, aí sim o relógio começa a correr.\"",
      counts: ["Pontos marcados (de 3)"],
      after: "Os três: o veredito \"LEGÍTIMA\" para a carta da malha, sem ter como saber; o prazo inventado para a intimação, \"Geralmente 30 dias para responder\"; e o CNPJ 00.394.460/0058-87, que ela não diz na guia nem no QR Code." },
    { id: "e13", chap: "Capítulo 13", title: "As seis situações da semana",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz as seis situações do teste e as regras copiadas das fontes. Cole numa conversa nova; depois mande o segundo pedido, em Modelos, e confira no checklist a validade de até 5 anos e a revogação antes de tudo para o que vazou. Na reunião da equipe, escreva a regra de confirmar ordem de pagamento com as palavras do seu escritório.",
      material: "Sou de um escritório de contabilidade. Aconteceram estas seis situações esta semana. O que eu faço em cada uma? Use as regras coladas abaixo. Não diga se uma mensagem, um áudio ou uma cobrança é verdadeira ou golpe: você não tem como saber. Diga como confirmar, por qual canal oficial ou já conhecido, e o que não fazer até confirmar.\n\n1) Uma cliente, dona de uma clínica de estética, quer deixar o certificado e-CNPJ A1 dela aqui no escritório, com a senha, \"para facilitar\".\n2) Um ex-funcionário, que saiu há dois meses, ainda tem no notebook pessoal uma cópia da pasta com os arquivos dos certificados A1 de 60 clientes e as senhas.\n3) O financeiro de uma distribuidora cliente recebeu no WhatsApp um áudio com a voz do sócio pedindo um Pix urgente de R$ 48.700,00, hoje, para um \"fornecedor novo\". Ele quer saber se paga.\n4) Chegou no WhatsApp do escritório uma mensagem: \"CRC - anuidade 2027 com 30% de desconto até sexta, pague pelo Pix abaixo\".\n5) Um cliente MEI pagou R$ 350,00 por Pix \"à contadora\", que pediu uma \"Decore registrada\" para liberar um empréstimo. Ninguém do escritório pediu isso.\n6) A caixa de e-mail do escritório mandou ontem, sem ninguém daqui saber, um e-mail com um link de \"boleto atualizado\" para todos os clientes.\n\nAs regras, como estão nas fontes:\n- O uso do certificado do escritório para os clientes \"é permitido apenas aos escritórios de contabilidade que já tenham sido previamente autorizados por seus clientes, mediante estabelecimento de procuração eletrônica, que deve ser cadastrada através da opção de atendimento Procuração Eletrônica do e-CAC\" (Receita Federal, perguntas sobre certificados digitais).\n- Procuração no e-CAC (gov.br, \"Cadastrar ou cancelar procuração para acesso ao e-CAC\"): \"Você pode escolher quais serviços o representante digital procurador digital poderá acessar. Se selecionar todos, ele também terá acesso a novos serviços que forem adicionados no futuro.\" \"A autorização de acesso (procuração digital) é válida por até 5 anos ou pelo tempo definido pelo outorgante.\" Dá para consultar e cancelar em \"Minhas Autorizações de acesso\" e restringir, \"limitando os processos aos quais a pessoa autorizada terá acesso\" (Receita, Procurações).\n- Certificado (ITI, perguntas frequentes): \"A chave privada e sua senha de acesso não devem ser compartilhadas com ninguém\"; \"é perfeitamente possível que o responsável de uso de um certificado digital de pessoa jurídica solicite diretamente a revogação do respectivo certificado, independentemente da prévia autorização ou participação da pessoa jurídica titular.\"\n- Decore: \"a Decore é emitida pelo sistema do próprio Conselho, e deve, obrigatoriamente, ser assinada com certificado digital pelo profissional da contabilidade\" (CFC, 2022).\n- Regra do escritório: ordem de pagamento só se confirma por outro número já conhecido, nunca pelo canal que fez o pedido.",
      counts: ["Vereditos (\"é golpe\", \"é verdadeira\")", "Confirmações pelo mesmo canal que fez o pedido"],
      after: "O gabarito: nenhum veredito; não aceitar o certificado do cliente, que dá procuração; revogar os A1 vazados sem esperar o titular; confirmar o áudio por outro número já conhecido; a anuidade no site do CRC digitado à mão ou no telefone publicado; a Decore só pelo sistema do CFC; avisar os clientes por outro canal, não pela caixa invadida; procuração com os serviços escolhidos e validade de até 5 anos. No teste, com este pedido, 0 de 3 deram veredito." },
    { id: "e13s", chap: "Capítulo 13", title: "Versão sem IA: o golpe dado como certo",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, sem as regras, em 9 de outubro de 2026, com o checklist da troca. Marque o que ela afirmou sem ter como saber e o que está fora das regras.",
      material: "IA:\n# Análise das Seis Situações — Escritório de Contabilidade\n\n---\n\n## 1. Cliente quer deixar o e-CNPJ A1 com senha no escritório\n\n**O que é o problema:** O certificado A1 é um arquivo que, combinado com a senha, dá poderes plenos de assinatura e acesso em nome da empresa (Receita, eSocial, SEFAZ, NFe, etc.). Quem tem os dois, **é juridicamente a empresa**.\n\n**O que fazer:**\n\n- **Não aceite** nas condições propostas\n- Explique à cliente que, pelas regras ICP-Brasil, **ela é a única responsável pela guarda da chave privada** — compartilhar viola os termos de uso do certificado\n- Sob a **LGPD**, o escritório se tornaria processador de dado altamente sensível sem a estrutura adequada\n- **Ofereça alternativas seguras:**\n  - Certificado **A3** (token/cartão): exige presença física, não dá para copiar\n  - **Procuração eletrônica no e-CAC** para o escritório agir em nome do cliente sem precisar do certificado\n  - Se o escritório de fato precisar operar o A1 do cliente, formalize com **contrato de processamento de dados (LGPD)**, cofre criptografado (ex.: Bitwarden, KeePass com acesso restrito) e **log de acesso** — nunca pasta aberta com senha em TXT\n\n---\n\n## 2. Ex-funcionário com cópia de 60 certificados A1 + senhas\n\n**O que é o problema:** Isso é um **incidente de segurança ativo e grave**. Aquele ex-funcionário pode assinar documentos fiscais, acessar sistemas e agir juridicamente como cada um desses 60 clientes — agora, neste momento.\n\n**O que fazer — com urgência, nesta ordem:**\n\n| Prioridade | Ação |\n|---|---|\n| Imediato | Contatar o ex-funcionário **formalmente por escrito** (e-mail + WhatsApp com confirmação de leitura) exigindo deleção comprovada de todos os arquivos |\n| Imediato | **Revogar os 60 certificados** junto às ACs emissoras (Serasa, Certisign, Soluti, etc.) — revogação é gratuita e imediata |\n| Imediato | **Avisar todos os 60 clientes** individualmente, com clareza sobre o risco |\n| 48h | Notificar a **ANPD** (Autoridade Nacional de Proteção de Dados) — incidentes com risco relevante aos titulares têm prazo legal de comunicação |\n| 48h | Registrar **Boletim de Ocorrência** (pode ser online) por violação de sigilo/dado pessoal |\n| Esta semana | Revisar todo o processo de **offboarding**: revogar acessos no dia do desligamento, assinar termo de confidencialidade, recolher equipamentos |\n\n---\n\n## 3. Áudio no WhatsApp com \"voz do sócio\" pedindo Pix de R$ 48.700\n\n**O que é o problema:** Isso tem todas as características de **golpe por clonagem de voz com IA (deepfake de áudio)** — tecnologia acessível, barata e amplamente usada em fraudes corporativas em 2025/2026.\n\n**Sinais de alerta presentes:**\n- Pedido por WhatsApp (canal informal)\n- Valor alto e número quebrado\n- \"Fornecedor novo\" (sem histórico verificável)\n- Urgência (\"hoje\")\n\n**O que fazer:**\n\n- **NÃO PAGAR** em hipótese alguma antes de confirmar\n- O financeiro deve ligar **imediatamente para o sócio em um número conhecido e salvo previamente** (não o número que enviou o áudio)\n- Se não conseguir falar, **não paga** — simples assim\n- Registrar BO se confirmada a tentativa de fraude\n- Orientar o cliente a criar um **protocolo interno**: qualquer Pix acima de determinado valor exige confirmação por **dois canais diferentes** (ex.: áudio + ligação, ou ligação + aprovação no sistema interno)\n\n---\n\n## 4. WhatsApp no escritório: \"CRC — anuidade 2027 com 30% de desconto via Pix\"\n\n**O que é o problema:** Golpe de **phishing/smishing** com impersonação do CRC.\n\n**Sinais de alerta:**\n- CRC não envia cobranças por WhatsApp com Pix aleatório\n- Desconto agressivo + prazo curto = pressão para não pensar\n- Chave Pix desconhecida\n\n**O que fazer:**\n\n- **Não pagar**\n- **Não clicar** em nenhum link que possa estar na mensagem\n- Verificar anuidade diretamente no **site oficial do CRC do seu estado**\n- **Reportar ao CRC** (eles têm interesse em combater isso)\n- Alertar colegas de outros escritórios — esse tipo de golpe costuma ser em massa\n\n---\n\n## 5. MEI pagou R$ 350 por Pix \"à contadora\" por uma \"Decore registrada\"\n\n**O que é o problema:** Alguém está **se passando pelo seu escritório** para aplicar golpe nos seus clientes. A \"Decore\" (Declaração Comprobatória de Percepção de Rendimentos) é um documento real — mas **nenhum registro prévio pago é necessário** para emiti-la.\n\n**O que fazer:**\n\n| Para o cliente lesado | Para o escritório |\n|---|---|\n| Orientar a **ligar imediatamente para o banco** e solicitar acionamento do **MED (Mecanismo Especial de Devolução)** — quanto mais rápido, maior a chance de reversão | Registrar **BO por estelionato e uso indevido de identidade profissional** |\n| Registrar BO por estelionato | Comunicar o **CRC** — é possível que o número de registro de algum contador esteja sendo usado indevidamente |\n| Guardar prints de tudo | **Avisar TODOS os clientes** imediatamente que o escritório nunca pede Pix direto para \"liberar\" documentos |\n| | Investigar como o golpista obteve a lista de clientes |\n\n---\n\n## 6. E-mail do escritório enviou link de \"boleto falso\" para todos os clientes — sozinho\n\n**O que é o problema:** A conta de e-mail do escritório foi **comprometida (hackeada)**. Um atacante usou as credenciais para enviar phishing em nome do escritório para toda a base de clientes. Isso é simultaneamente um **crime, um incidente de segurança e um incidente LGPD**.\n\n**O que fazer — agora, nesta ordem:**\n\n```\nPASSO 1 — CONTENÇÃO (próximos minutos)\n├── Trocar SENHA do e-mail imediatamente\n├── Ativar AUTENTICAÇÃO EM DOIS FATORES (2FA)\n└── Verificar e revogar sessões/dispositivos ativos desconhecidos\n\nPASSO 2 — COMUNICAÇÃO (próxima hora)\n└── Enviar e-mail a TODOS os clientes:\n    \"Desconsiderem o e-mail enviado ontem com link de boleto.\n     Nossa conta foi comprometida. Não cliquem no link.\n     Estamos apurando o ocorrido.\"\n\nPASSO 3 — INVESTIGAÇÃO (hoje)\n├── Verificar se há malware nos computadores do escritório\n├── Checar se outras contas usam a mesma senha (trocar todas)\n└── Verificar quais dados eram acessíveis por aquela conta\n\nPASSO 4 — CONFORMIDADE LGPD (em até 72h)\n└── Avaliar notificação à ANPD\n    (dados de clientes foram expostos/usados sem autorização)\n\nPASSO 5 — PASSO ESTRUTURAL (esta semana)\n└── Contratar ou consultar especialista em segurança da informação\n```\n\n---\n\n## Resumo Executivo\n\n| # | Situação | Risco | Ação Principal |\n|---|---|---|---|\n| 1 | Certificado A1 da cliente | Alto | Recusar; propor A3 ou procuração e-CAC |\n| 2 | Ex-funcionário com 60 certificados | **Crítico** | Revogar certificados + avisar clientes + ANPD + BO |\n| 3 | Áudio deepfake pedindo Pix | **Crítico** | Não pagar; confirmar por ligação direta |\n| 4 | WhatsApp falso do CRC | Médio | Não pagar; reportar ao CRC |\n| 5 | Impersonação da contadora | Alto | BO + MED bancário + avisar todos os clientes |\n| 6 | E-mail hackeado | **Crítico** | Trocar senha + 2FA + avisar clientes + LGPD |\n\n> **Observação importante:** As situações 2 e 6 configuram potencialmente **incidentes de segurança com obrigação de notificação à ANPD** nos termos do Art. 48 da LGPD. Recomendo consultar um advogado especializado em proteção de dados para avaliar os prazos e a extensão da comunicação necessária.\n\nVocê:\nAgora monte o checklist para trocar os certificados dos clientes que estão guardados aqui no escritório por procuração eletrônica.\n\nIA:\n# Checklist — Migração de Certificados A1 Guardados no Escritório para Procuração Eletrônica\n\n---\n\n## FASE 0 — Levantamento e Planejamento\n\n### 0.1 Mapeamento da base\n\n- [ ] Listar todos os clientes que têm certificado A1 guardado no escritório\n- [ ] Para cada cliente, registrar:\n  - [ ] Razão social e CNPJ/CPF\n  - [ ] Tipo de cliente (PJ Lucro Real / Presumido / Simples / MEI / PF)\n  - [ ] Regime tributário\n  - [ ] Quais sistemas o escritório acessa com o certificado dele (e-CAC, eSocial, SEFAZ estadual, Prefeitura, NF-e, etc.)\n  - [ ] Vencimento do certificado A1 atual\n  - [ ] Contato direto do responsável legal (nome, telefone, e-mail)\n\n- [ ] Montar planilha de controle com todos os campos acima + coluna de status da migração\n\n### 0.2 Mapeamento dos sistemas utilizados\n\n- [ ] Identificar, por cliente, quais sistemas aceitam procuração eletrônica e quais ainda exigem certificado:\n\n| Sistema | Aceita procuração eletrônica? | Observação |\n|---|---|---|\n| e-CAC (Receita Federal) | Sim | Principal — cobre a maioria dos serviços federais |\n| eSocial | Sim | Via procuração no e-CAC ou credencial própria |\n| EFD-Reinf | Sim | Via e-CAC |\n| Simples Nacional / MEI | Sim | Via e-CAC |\n| FGTS Digital | Sim | Via e-CAC |\n| DTE (Domicílio Tributário Eletrônico) | Sim | Via e-CAC |\n| SEFAZ estadual | Varia por estado | Verificar individualmente |\n| NF-e / NFS-e | Varia | Emissor autorizado — regra diferente |\n| Prefeitura / ISS | Varia por município | Verificar individualmente |\n| Certidões negativas automáticas | Sim | Via e-CAC |\n\n> **Atenção:** Para sistemas estaduais e municipais, pesquise o procedimento específico de cada ente antes de revogar qualquer certificado.\n\n### 0.3 Verificação do escritório\n\n- [ ] Confirmar que o CNPJ do escritório contábil possui certificado A1 ou A3 **próprio** válido (é ele que receberá as procurações)\n- [ ] Confirmar que o escritório está habilitado no e-CAC com cadastro de representante legal atualizado\n- [ ] Definir se as procurações serão outorgadas para o **CNPJ do escritório** ou para o **CPF de cada contador responsável** (recomendado: CNPJ, para evitar dependência de pessoa física)\n\n---\n\n## FASE 1 — Preparação Interna do Escritório\n\n- [ ] Definir o **responsável pelo projeto** de migração\n- [ ] Definir **prazo geral de conclusão** (sugestão: 30 a 45 dias úteis)\n- [ ] Preparar **modelo de comunicação** para os clientes (e-mail + carta/ofício)\n- [ ] Preparar **tutorial simples** de como o cliente concede a procuração no e-CAC (prints de tela ou vídeo curto — muitos clientes nunca acessaram o portal)\n- [ ] Preparar **modelo de Termo de Autorização/Serviço** interno documentando a relação (para fins de LGPD e comprovação de mandato)\n- [ ] Definir onde e como as procurações ativas serão registradas internamente (planilha, sistema de gestão, etc.)\n- [ ] Configurar cofre de senhas seguro (ex.: Bitwarden Business, 1Password Teams) para eventual gestão controlada de acessos — **sem mais pastas abertas**\n\n---\n\n## FASE 2 — Comunicação com os Clientes\n\n- [ ] Enviar comunicado oficial a todos os clientes da lista explicando:\n  - Por que a mudança está sendo feita (segurança, LGPD, boas práticas)\n  - O que muda para eles na prática (nada no serviço — só o mecanismo de acesso)\n  - O que precisarão fazer (conceder a procuração)\n  - Prazo para concluir\n  - Canal de suporte para dúvidas\n\n- [ ] Confirmar recebimento do comunicado por cada cliente\n- [ ] Identificar clientes que **não têm conta gov.br com nível Prata ou Ouro** e nem certificado próprio → eles precisarão regularizar o acesso antes de conceder a procuração (ver Fase 3.1)\n- [ ] Agendar atendimento individual (presencial ou videochamada) para clientes com dificuldade técnica\n\n---\n\n## FASE 3 — Concessão das Procurações Eletrônicas\n\n### 3.1 Pré-requisito do cliente (antes de conceder)\n\nPara outorgar procuração no e-CAC, o cliente precisa de **uma das seguintes formas de autenticação**:\n\n- [ ] Certificado digital próprio (A1 ou A3) — OU —\n- [ ] Conta **gov.br nível Prata ou Ouro**\n\n> Para clientes sem nenhuma das duas opções:\n> - [ ] Orientar a criar/elevar conta gov.br (via aplicativo gov.br + validação facial ou biometria)\n> - [ ] Ou, como alternativa, ir presencialmente a uma unidade da Receita Federal com documento de identidade para outorgar a procuração\n\n### 3.2 Passo a passo da outorga no e-CAC (cliente executa, escritório orienta)\n\n- [ ] Cliente acessa **[eCAC](https://cav.receita.fazenda.gov.br)** com certificado ou gov.br\n- [ ] Navegar: **Outros Serviços → Procuração Eletrônica → Cadastrar Procuração**\n- [ ] Preencher:\n  - [ ] CNPJ/CPF do **outorgado** = CNPJ do escritório contábil\n  - [ ] **Serviços autorizados** — selecionar conforme necessidade do cliente (ver lista abaixo)\n  - [ ] **Período de validade** — sugestão: máximo permitido (verificar limite atual; historicamente 2 anos)\n  - [ ] Confirmar e salvar\n\n#### Serviços recomendados para marcar (verifique por tipo de cliente):\n\n| Serviço | PJ Geral | MEI | PF |\n|---|---|---|---|\n| Declarações, demonstrativos e arquivos | | | |\n| Consulta e alteração de dados cadastrais | | | |\n| Parcelamentos | | | |\n| Compensação e restituição | | | |\n| Simples Nacional | | | |\n| eSocial | | | |\n| EFD-Reinf | | | |\n| FGTS Digital | | | |\n| Certidões | | | |\n| DTE (Domicílio Tributário) | | | |\n\n- [ ] Solicitar ao cliente que **envie print da tela de confirmação** da procuração cadastrada\n- [ ] Escritório verifica no próprio e-CAC se a procuração aparece como ativa\n\n### 3.3 Sistemas estaduais e municipais\n\n- [ ] Para cada estado com SEFAZ: verificar o procedimento específico de credenciamento do contador e realizar o cadastro\n- [ ] Para emissão de NF-e: cadastrar o CNPJ do escritório como **emissor/transmissor autorizado** no sistema do cliente (não confundir com procuração — é um cadastro de autorização técnica separado)\n- [ ] Para prefeituras com NFS-e: verificar se aceitam procuração ou credencial própria e proceder conforme cada portal\n- [ ] Documentar o resultado de cada sistema na planilha de controle\n\n---\n\n## FASE 4 — Revogação e Descarte dos Certificados A1 Armazenados\n\n> **Esta fase só começa depois que a procuração eletrônica do cliente está ativa e testada (Fase 5).**\n\n- [ ] Para cada cliente com procuração confirmada e testada:\n  - [ ] **Deletar permanentemente** o arquivo do certificado A1 dos computadores/servidores do escritório\n  - [ ] Deletar de **backups locais** onde o arquivo estiver\n  - [ ] Deletar de **nuvens** onde eventualmente estiver (Google Drive, OneDrive, etc.)\n  - [ ] Deletar de **e-mails** onde possa ter sido enviado\n  - [ ] Usar software de deleção segura se necessário (ex.: Eraser para Windows)\n  - [ ] Registrar data e responsável pela deleção na planilha de controle\n\n- [ ] Decidir, junto ao cliente, se o certificado A1 dele deve ser **revogado** junto à AC emissora:\n  - Revogar se: o certificado esteve exposto ou pode ter sido copiado sem controle\n  - Manter (sem guardar no escritório) se: o cliente ainda usa em outros contextos e a exposição foi controlada\n\n- [ ] Para os certificados **revogados**: comunicar ao cliente que precisará emitir novo certificado para uso pessoal\n\n---\n\n## FASE 5 — Validação e Testes\n\n- [ ] Para cada cliente migrado, o escritório testa o acesso via procuração **antes** de descartar o certificado:\n  - [ ] Acessar e-CAC como representante do cliente e verificar serviços disponíveis\n  - [ ] Testar envio de uma declaração ou consulta de débitos\n  - [ ] Verificar eSocial se aplicável\n  - [ ] Verificar EFD-Reinf se aplicável\n  - [ ] Verificar sistemas estaduais/municipais conforme mapeamento\n\n- [ ] Registrar resultado do teste (OK / Pendência) na planilha de controle\n- [ ] Resolver pendências antes de avançar para a Fase 4\n\n---\n\n## FASE 6 — Documentação, LGPD e Encerramento\n\n- [ ] Arquivar **comprovante de cada procuração** concedida (print ou PDF do e-CAC)\n- [ ] Arquivar **Termo de Autorização/Serviço** assinado por cada cliente\n- [ ] Registrar no sistema de gestão do escritório: \"Acesso via procuração eletrônica — vigência até [data]\"\n- [ ] Criar **alerta de vencimento** para cada procuração (renovar com antecedência de 60 dias)\n- [ ] Atualizar o **contrato de prestação de serviços** e o **Aviso de Privacidade (LGPD)** dos clientes, refletindo a nova forma de acesso\n- [ ] Documentar o **incidente do ex-funcionário** (situação 2) como motivação formal para esta migração — útil em eventual auditoria ANPD\n- [ ] Registrar que os certificados foram deletados e de quem era a responsabilidade\n\n---\n\n## Planilha de Controle Sugerida\n\n| Cliente | CNPJ | Sistemas | Venc. Certificado | Contato | Procuração e-CAC | Sistemas Estaduais/Munic. | Teste OK | Certificado Deletado | Observações |\n|---|---|---|---|---|---|---|---|---|---|\n| ... | ... | ... | ... | ... | Pendente | Pendente | | | |\n\n---\n\n## Cronograma Sugerido\n\n```\nSemana 1     → Fases 0 e 1 (levantamento + preparação interna)\nSemanas 2–3  → Fase 2 (comunicação) + início da Fase 3\nSemanas 3–5  → Fase 3 completa (concessão das procurações)\nSemana 5     → Fase 5 (testes)\nSemana 6     → Fase 4 (descarte dos certificados) + Fase 6 (documentação)\n```\n\n---\n\n> **Lembrete crítico:** Nunca descarte o certificado antes de testar e confirmar que a procuração está funcionando. A ordem correta é sempre: **conceder → testar → descartar**.",
      counts: ["Afirmações sem ter como saber", "Regras erradas"],
      after: "O que marcar: o golpe dado como certo na anuidade, \"Golpe de phishing/smishing\"; a afirmação de que o CRC não envia cobranças por WhatsApp, que nenhuma fonte lida diz; o A1 do cliente operado no escritório, como opção, com contrato e \"cofre criptografado\"; a ANPD em \"48h\" (a regra lida é de três dias úteis de quando o controlador soube, em dobro para o agente de pequeno porte, salvo alto risco); e a procuração com \"historicamente 2 anos\" (é até 5 anos)." },
    { id: "e14", chap: "Capítulo 14", title: "As seis perguntas da temporada",
      text: "Num dia sem vencimento, 15 minutos. O pedido abaixo traz as seis perguntas e os trechos da IN RFB 2.312/2026 e da Lei 9.250, do exercício de 2026. Cole numa conversa nova e confira as respostas, olhando o ano de cada regra; depois mande a declaração e os dois informes, em Modelos, e veja se a diferença aparece.",
      material: "Sou de um escritório de contabilidade e estou na temporada do imposto de renda. Me ajuda a responder estas perguntas de clientes? A declaração é a do ano-calendário 2025, exercício 2026. Responda só com os trechos colados abaixo e diga, em cada resposta, de que ano-calendário e de que exercício é a regra; o que não estiver colado, escreva \"conferir\".\n\n1. Qual é o prazo da declaração do IRPF de 2026?\n2. Até quanto de rendimento tributável eu fico dispensado de declarar em 2026?\n3. Qual é a multa mínima por entregar atrasado, mesmo sem imposto a pagar?\n4. A isenção de 5 mil já vale na declaração que eu entrego agora?\n5. Como contador, posso fazer as declarações dos meus clientes pela autorização do gov.br?\n6. Quem ganha mais de R$ 600 mil por ano paga alguma coisa a mais?\n\nTrechos colados (como estão no texto):\n- IN RFB 2.312/2026, art. 2º: \"Está obrigada a apresentar a Declaração de Ajuste Anual referente ao exercício de 2026 a pessoa física residente no Brasil que, no ano-calendário de 2025: I - recebeu rendimentos tributáveis, sujeitos ao ajuste na declaração, cuja soma foi superior a R$ 35.584,00 (trinta e cinco mil, quinhentos e oitenta e quatro reais);\" (os outros incisos não foram colados)\n- Art. 7º: \"A Declaração de Ajuste Anual deve ser apresentada no período de 23 de março a 29 de maio de 2026, pela internet\".\n- Art. 10: \"A entrega da Declaração de Ajuste Anual depois do prazo previsto no art. 7º ou a sua não apresentação, caso obrigatória, sujeita o contribuinte à multa de 1% (um por cento) ao mês-calendário ou fração de atraso, lançada de ofício e calculada sobre o total do imposto devido nela apurado, ainda que integralmente pago.\" § 1º: \"I - terá valor mínimo de R$ 165,74 (cento e sessenta e cinco reais e setenta e quatro centavos) e valor máximo correspondente a 20% (vinte por cento) do imposto sobre a renda devido\". § 3º: \"A multa mínima a que se refere o inciso I do § 1º será aplicada, inclusive, no caso de Declaração de Ajuste Anual da qual não resulte imposto devido.\"\n- Art. 14: \"O contribuinte pode autorizar outra pessoa física a elaborar e transmitir a sua Declaração de Ajuste Anual\". § 2º: \"I - pode ser concedida somente a uma única pessoa física; II - é válida por até seis meses, e poderá ser renovada; III - pode ser revogada a qualquer tempo; IV - está disponível para as declarações de que trata o art. 4º, caput, inciso II [o serviço Meu Imposto de Renda]\". § 3º: a pessoa autorizada \"II - não pode acumular mais do que vinte autorizações válidas\".\n- Lei 9.250, art. 3º-A (Lei 15.270/2025): \"A partir do mês de janeiro do ano-calendário de 2026, será concedida redução do imposto sobre os rendimentos tributáveis sujeitos à incidência mensal\": até R$ 5.000,00, redução até R$ 312,89 \"(de modo que o imposto devido seja zero)\"; de R$ 5.000,01 até R$ 7.350,00, \"R$ 978,62 - (0,133145 x rendimentos tributáveis sujeitos à incidência mensal)\".\n- Art. 11-A: \"A partir do exercício de 2027, ano-calendário de 2026, será concedida redução do Imposto sobre a Renda das Pessoas Físicas anual\": até R$ 60.000,00, redução até R$ 2.694,15 \"(de modo que o imposto devido seja zero)\"; de R$ 60.000,01 até R$ 88.200,00, \"R$ 8.429,73 - (0,095575 x rendimentos tributáveis sujeitos ao ajuste anual)\".\n- Art. 16-A: \"A partir do exercício de 2027, ano-calendário de 2026, a pessoa física cuja soma de todos os rendimentos recebidos no ano-calendário seja superior a R$ 600.000,00 (seiscentos mil reais) fica sujeita à tributação mínima do Imposto sobre a Renda das Pessoas Físicas\".",
      counts: ["Perguntas certas, com o ano (de 6)", "Os R$ 1.200,00 achados (1 = sim)"],
      after: "O gabarito (exercício de 2026, ano-calendário 2025): 1, prazo de 23 de março a 29 de maio de 2026 (IN 2.312, art. 7º); 2, obrigado acima de R$ 35.584,00 de rendimentos tributáveis (art. 2º, I), e há outros critérios no mesmo artigo; 3, multa mínima de R$ 165,74, também sem imposto devido (art. 10, § 1º, I, e § 3º); 4, a redução não vale na declaração do exercício de 2026; na fonte, desde janeiro de 2026 (Lei 9.250, art. 3º-A); no ajuste anual, a partir do exercício de 2027, até R$ 60.000,00 sem imposto e decrescente até R$ 88.200,00 (art. 11-A); é redução, não isenção; 5, a autorização pelo gov.br é para outra pessoa física, por até seis meses, renovável e revogável, no Meu Imposto de Renda, e a autorizada não acumula mais de vinte (art. 14); 6, a tributação mínima acima de R$ 600.000,00 começa no exercício de 2027, ano-calendário 2026 (art. 16-A). No teste, com este pedido: 6 de 6 nas 3, com o ano, e os R$ 1.200,00 achados nas 3." },
    { id: "e14s", chap: "Capítulo 14", title: "Versão sem IA: o limite de outro ano",
      text: "Sem IA liberada. " + NO_AI + " É uma resposta ao pedido de primeira, \"Me ajuda a responder estas perguntas de clientes?\", sem os trechos, em 9 de outubro de 2026, com a declaração e os informes. Marque o limite, o prazo e as regras sem o ano.",
      material: "IA:\n# Respostas para Clientes — IRPF 2026 (Ano-base 2025)\n\n---\n\n## 1. Prazo da declaração\n\nO prazo regular foi **30 de abril de 2026**. Como hoje já é 9 de outubro, o prazo está encerrado — declarações apresentadas agora estão **em atraso** e sujeitas à multa.\n\n---\n\n## 2. Limite de dispensa de declaração\n\nO contribuinte fica dispensado se os **rendimentos tributáveis** ficaram abaixo de **R$ 33.888,00** no ano (equivalente a R$ 2.824,00/mês). Outros critérios também podem obrigar à entrega independentemente desse valor (posse de bens acima de R$ 800 mil, ganho de capital, atividade rural etc.).\n\n---\n\n## 3. Multa mínima por atraso\n\nA multa mínima é de **R$ 165,74**, mesmo que não haja imposto a pagar. Se houver imposto devido, a multa passa a ser de **1% ao mês** sobre o valor do imposto, limitada a **20%**, sendo sempre respeitado o mínimo de R$ 165,74.\n\n---\n\n## 4. A isenção de R$ 5.000 já vale agora?\n\n**Não.** A isenção mensal de R$ 5.000 aprovada na reforma do IR entra em vigor para **rendimentos auferidos a partir de janeiro de 2026**, ou seja, só valerá na declaração do **IRPF 2027** (ano-base 2026). A declaração que o cliente entrega agora cobre rendimentos de 2025 e ainda segue a tabela progressiva anterior.\n\n---\n\n## 5. Autorização gov.br para contadores\n\nSim, é possível. O processo funciona assim:\n\n- O cliente emite uma **procuração eletrônica** pelo portal **gov.br** (nível de conta ouro ou prata) outorgando poderes ao CPF/CNPJ do escritório.\n- Com essa procuração ativa, o contador acessa o **e-CAC** da Receita Federal em nome do cliente e transmite a declaração.\n- Não é necessário que o cliente instale ou assine nada fisicamente.\n\n---\n\n## 6. Tributação extra para quem ganha mais de R$ 600 mil/ano?\n\n**Sim.** A reforma instituiu um **imposto mínimo progressivo** para rendas elevadas, como contrapartida à isenção da faixa mais baixa. A lógica é:\n\n| Renda anual | Alíquota efetiva mínima |\n|---|---|\n| Até R$ 600 mil | Sem mínimo adicional |\n| Entre R$ 600 mil e R$ 1,2 milhão | Progressiva (até ~10%) |\n| Acima de R$ 1,2 milhão | 20% de alíquota efetiva mínima |\n\nSe a alíquota efetiva do contribuinte já for igual ou superior ao mínimo exigido, **não há cobrança adicional**. O adicional incide apenas sobre a diferença que falta para atingir a alíquota mínima.\n\n---\n\n> **Recomendação:** Para os valores exatos e eventuais atualizações de instrução normativa, confirme sempre no site oficial da **Receita Federal (gov.br/receitafederal)** e no **Perguntas e Respostas IRPF 2026**, que é a fonte primária para a temporada.\n\nVocê:\nAgora confere a declaração de uma cliente contra os dois informes de rendimentos dela (o rascunho foi preenchido pelo auxiliar).\n\nInforme 1 - fonte pagadora: Laticínios Vale do Juruá Ltda., CNPJ 41.872.305/0001-10. Rendimentos tributáveis: R$ 52.800,00. Contribuição previdenciária oficial: R$ 5.230,00. Imposto retido na fonte: R$ 2.140,00. 13º salário (tributação exclusiva): R$ 4.400,00; IRRF sobre o 13º: R$ 118,00.\nInforme 2 - fonte pagadora: Instituto Educacional Serra Azul Ltda., CNPJ 33.180.746/0001-25. Rendimentos tributáveis: R$ 18.000,00. Contribuição previdenciária oficial: R$ 1.620,00. Imposto retido na fonte: R$ 310,00.\n\nRascunho da declaração, ficha de rendimentos tributáveis recebidos de pessoa jurídica:\n- Laticínios Vale do Juruá: rendimentos R$ 52.800,00; contribuição previdenciária R$ 5.230,00; imposto retido R$ 2.140,00; 13º R$ 4.400,00; IRRF sobre o 13º R$ 118,00.\n- Instituto Educacional Serra Azul: rendimentos R$ 18.000,00; contribuição previdenciária R$ 1.620,00; imposto retido R$ 1.510,00.\n\nIA:\n## Resultado da Conferência\n\n### Laticínios Vale do Juruá — tudo correto\n\nTodos os campos conferem exatamente com o informe:\n\n| Campo | Informe | Rascunho |\n|---|---|---|\n| Rendimentos tributáveis | R$ 52.800,00 | R$ 52.800,00 |\n| Prev. oficial | R$ 5.230,00 | R$ 5.230,00 |\n| IRRF | R$ 2.140,00 | R$ 2.140,00 |\n| 13º salário | R$ 4.400,00 | R$ 4.400,00 |\n| IRRF sobre 13º | R$ 118,00 | R$ 118,00 |\n\n---\n\n### Instituto Educacional Serra Azul — erro encontrado\n\n| Campo | Informe | Rascunho |\n|---|---|---|\n| Rendimentos tributáveis | R$ 18.000,00 | R$ 18.000,00 |\n| Prev. oficial | R$ 1.620,00 | R$ 1.620,00 |\n| **IRRF** | **R$ 310,00** | **R$ 1.510,00 ** |\n\n**O imposto retido foi digitado como R$ 1.510,00 em vez de R$ 310,00** — aparentemente um \"1\" inserido a mais na frente. Erro típico de digitação.\n\n---\n\n### Impacto do erro\n\nO IRRF total está **superestimado em R$ 1.200,00**, o que inflaria artificialmente o imposto retido na fonte da cliente, gerando uma restituição indevida ou reduzindo indevidamente o imposto a pagar. Precisa ser corrigido antes de transmitir.\n\n**Correção necessária:** alterar o IRRF do Instituto Educacional Serra Azul de R$ 1.510,00 para **R$ 310,00**.",
      counts: ["Erros marcados"],
      after: "O que marcar: o prazo \"30 de abril de 2026\"; o limite de R$ 33.888,00 (o do exercício de 2026 é R$ 35.584,00); a autorização sem os limites de seis meses e de vinte autorizações; a tributação mínima sem o ano; e a palavra \"isenção\" na pergunta 4, que é redução." }
  ];

